// ÜRETİLDİ/HİZALANDI: _canon omurgası (2026-07-13 canon-align.mjs) — pattern 11, shape3d 7, adlar canon nameTr
export const HOME_TRAJ = {"meta":{"framework":"Clements & Sarama [LT]² — learningtrajectories.org","source":"ADIM / numap öğrenme yörüngeleri — LT_MASTER_TR 17 Eyl 2026 (223 kazanım)","trajectoryCount":20,"levelCount":223,"schema":"her kategori (gunluk=günlük hayat / oyun / yaprak=çalışma yaprağı) → {t:başlık, adim:[adımlar], soyle:ebeveyn cümlesi, isaret:başarı işareti}","note":"ADIM Adım 6 (Evde Destek) bu dosyadan beslenir. Her etkinlik ilgili yörünge düzeyinin kazanımına doğrudan bağlıdır."},"trajectories":{"sub":{"code":"Y01","name":"Saymadan Anlık Bilme (Sanbil)","strand":"sayi","levels":[{"order":1,"kazanim":"Sayı Duyarlılığı: Temeller","gunluk":{"t":"Az ve çok yığın","adim":["Tabağa önce 1, sonra bir avuç (3-4) zeytin koyun.","«Bak, bu çok daha kalabalık oldu!» deyin; sayı söylemeyin.","Sadece «az» ve «çok» yığınları gözle fark ettirin."],"soyle":"«Bu yığın çok, bu az; hangisi daha kalabalık?»","isaret":"Sayı söylemeden belirgin az-çok farkını gözle ayırır."},"oyun":{"t":"Hangi avuç çok","adim":["İki avucunuza fasulye saklayın (birine 1-2, ötekine bir avuç).","Ellerinizi açıp «hangisi daha çok?» diye sorun.","Doğruda birlikte sevinin, yanlışta düzeltmeden tekrar oynayın."],"soyle":"«İki avucumda fasulye var; hangisinde daha çok?»","isaret":"İki kümeden çok olanı saymadan, sezgiyle gösterir."},"yaprak":{"t":"Kalabalık tarafa el","adim":["Kâğıdın soluna 2, sağına 6 çıkartma/nokta yapıştırın.","Çocuktan «daha kalabalık olan tarafa» elini koymasını isteyin.","Fark büyük olduğu için her seferinde başarır."],"soyle":"«Daha kalabalık olan tarafa elini koy.»","isaret":"Belirgin çok olan tarafı sezgiyle seçer."}},{"order":2,"kazanim":"Çok Küçük Sayıları Tanıyan","gunluk":{"t":"Bir mi, iki mi","adim":["Çocuk bir şey isteyince «1 mi istersin, 2 mi?» diye sorun.","Eşyaları yan yana koyup gösterin (1 bisküvi mi, 2 mi).","Gün içinde birkaç kez bu «bir mi iki mi» anını yakalayın."],"soyle":"«Bir tane mi istersin, iki tane mi? Bak, bu iki.»","isaret":"1 ile 2'yi bakışta ayırıp seçimini söyler."},"oyun":{"t":"Hangisinde iki vardı","adim":["İki bardağın altına 1 ve 2 düğme saklayın.","Kaldırınca «hangisinde iki tane vardı?» deyin.","Saymadan, bakışta seçmesini isteyin."],"soyle":"«Hangi bardakta iki düğme vardı? Bakışta söyle.»","isaret":"1 ve 2'lik kümeyi saymadan ayırt eder."},"yaprak":{"t":"İki olanı bul","adim":["Yan yana iki kutu çizin; birine 1, birine 2 kalp koyun.","Çocuk «iki olanı» yuvarlak içine alsın.","Sonra kutuları boşaltıp kendisi 1 ve 2 çizsin."],"soyle":"«İki kalp olanı yuvarlağa al.»","isaret":"1 ve 2'yi ayırıp ikiyi doğru işaretler ve çizer."}},{"order":3,"kazanim":"Küçük Grupların Aynısını Oluşturan","gunluk":{"t":"Bana iki ver","adim":["Sofrayı kurarken «bana 2 çatal verir misin?» deyin.","Elinize tam 2 tane bırakmasını isteyin.","Fazla verirse «bu kaç oldu, 2 mi?» diye birlikte bakın."],"soyle":"«Bana tam iki çatal ver; ne bir eksik ne bir fazla.»","isaret":"İstenen 1-2 nesneyi tam sayıda verir."},"oyun":{"t":"Garson siparişi","adim":["Üzerinde 1 veya 2 nokta olan «sipariş kartları» yapın.","Çocuk garson olsun: kartta kaç nokta varsa o kadar üzüm koysun.","Doğru sayıda koyunca alkışlayın."],"soyle":"«Kartta iki nokta var; tabağa iki üzüm koy lütfen.»","isaret":"Karttaki 1-2 sayısı kadar nesneyi oluşturur."},"yaprak":{"t":"Tabağa koy","adim":["Üç boş kâğıt tabak çizin; yanlarına «1» ve «2» yazın.","Çocuk her tabağa yazıldığı kadar fasulye yapıştırsın.","Az ya da çok olursa silmeden birlikte düzeltin."],"soyle":"«Bu tabağa bir, bu tabağa iki fasulye koy.»","isaret":"Yazılan 1-2 sayısı kadar nesne yerleştirir."}},{"order":4,"kazanim":"Küçük Grupları Adlandıran","gunluk":{"t":"Bir bakışta kaç","adim":["Eline aldığı oyuncakları gösterip «kaç tane?» deyin.","Saymasına fırsat vermeden 1, 2, 3'lük grupları söyletin.","4 olursa zorlanması normaldir; gün içinde 2-3 kez yineleyin."],"soyle":"«Saymadan bak: kaç tane? Bir bakışta söyle.»","isaret":"1-3'lük grupları saymadan, bir bakışta adlandırır."},"oyun":{"t":"Bir saniye göster","adim":["Bir bardağın altına 1-3 düğme saklayın.","«Hazır mısın?» deyip 1 saniye gösterip kapatın.","Çocuk «3!» desin; 4'e doğru yavaş yavaş ilerleyin."],"soyle":"«Bir saniye göstereceğim; kaç tane gördün?»","isaret":"Kısa süre gösterilen 1-3'ü saymadan söyler."},"yaprak":{"t":"Grubun sayısı","adim":["Kâğıda dağınık 1, 2 ve 3 noktalı küçük gruplar çizin.","Her grubun yanına rakamını çocuk yazsın/söylesin.","Gruplar 3'ü geçmesin ki saymadan tanısın."],"soyle":"«Bu gruba bak; saymadan kaç olduğunu yaz.»","isaret":"1-3'lük grupları saymadan adlandırıp yazar."}},{"order":5,"kazanim":"Algısal Sanbil (4’e kadar)","gunluk":{"t":"Dörde bak","adim":["Çatal-kaşık verirken «şimdi 4 tane lazım» deyip eline 4 koyun.","«Saymadan, baktın mı 4 olduğunu anlıyor musun?» diye oynayın.","4'ü 3+1 gibi gösterip 3'ten 4'e geçişi rahatlatın."],"soyle":"«Saymadan bak: bu dört mü? Üç ve bir, dört.»","isaret":"4'ü saymadan, bir bakışta tanır (3'le karıştırmaz)."},"oyun":{"t":"Zarda dört","adim":["Zar atın ama yalnız 1-4 yüzlerini kullanın (5-6 gelince tekrar atın).","Çocuk zardaki noktaları saymadan «4!» desin.","Doğruysa bir adım ilerlesin; sabit dizilim tanımayı kolaylaştırır."],"soyle":"«Zara bak, sayma: kaç nokta var?»","isaret":"Zardaki 4'ü saymadan anında söyler."},"yaprak":{"t":"Hepsi dört mü","adim":["Kâğıda 4 noktayı bazen köşe köşe (zar gibi), bazen sıra halinde çizin.","Çocuk hepsine bakıp «hepsi 4 mü?» diye işaretlesin.","Aynı sayının farklı dizilişini görmek 4'ü sağlamlaştırır."],"soyle":"«Diziliş değişse de hepsi dört mü? İşaretle.»","isaret":"Farklı dizilişlerde 4'ü saymadan tanır."}},{"order":6,"kazanim":"Algısal Sanbil (5’e kadar)","gunluk":{"t":"El beştir","adim":["Bir elin parmaklarını açıp «hepsi 5; saymadan da biliyoruz» deyin.","Çorabı, kalemi 5'erli gösterip «bu da 5 mi?» diye onaylatın.","Eli, 5'in en güçlü çapası olarak kullanın."],"soyle":"«Elimde beş parmak; saymadan beş olduğunu biliyoruz.»","isaret":"5'lik kümeyi saymadan, bir bakışta tanır."},"oyun":{"t":"Beşli çerçeve","adim":["Yumurta kartonunun 5'li bir sırasını kullanın.","Bazı gözlere boncuk koyup «kaç tane, baktın mı anladın mı?» deyin.","Örn. 4 dolu 1 boş = 4; 5'lik çerçeve bakışta görmeyi destekler."],"soyle":"«Çerçeveye bak: kaç göz dolu? Saymadan söyle.»","isaret":"5'lik çerçevede 5'e dek miktarı bakışta bilir."},"yaprak":{"t":"Kaç dolu","adim":["Kâğıda 5'lik kutular (□□□□□) çizip içine 3, 4 ya da 5 nokta koyun.","Çocuk saymadan kaç dolu olduğunu söylesin.","Hep 5'lik çerçevede olduğundan «bir eksik», «tam beş» sezgisi gelişir."],"soyle":"«Beşlik kutuda kaç dolu? Tam beş mi, bir eksik mi?»","isaret":"5'lik çerçevede dolu sayısını saymadan söyler."}},{"order":7,"kazanim":"Kavramsal Sanbil (5’e kadar)","gunluk":{"t":"İki ve üç beş","adim":["Meyveleri ikiye ayırın: «2 elma burada, 3 elma şurada».","«Hepsi 5 değil mi?» diye parça-bütünü sesli kurun.","Çocuğun «2 ve 3 beş eder» demesini sağlayın."],"soyle":"«İki burada, üç şurada; ikisi birlikte beş eder.»","isaret":"5'i 2+3 gibi parçalardan, saymadan görür."},"oyun":{"t":"Beş eden domino","adim":["Domino taşlarından 5 edenleri (4+1, 3+2) bulup ayırın.","«Bu iki parça birlikte kaç?» diye sorun.","Çocuk iki küçük grubu saymadan birleştirip 5 desin."],"soyle":"«Bu iki yan birlikte kaç eder? Saymadan, gruplara bak.»","isaret":"İki alt grubu birleştirerek 5'i kavramsal görür."},"yaprak":{"t":"Beşin parçaları","adim":["Kâğıda 5'i iki renge bölünmüş gösterin (2 kırmızı + 3 mavi nokta).","Çocuk «kaç + kaç» olduğunu söylesin.","Aynısını boş kutuda kendi renklendirsin."],"soyle":"«Beş, iki ve üçten oluşuyor; sen de renklendir.»","isaret":"5'in saklı parçalarını (2+3) gösterir."}},{"order":8,"kazanim":"Kavramsal Sanbil (7’ye kadar)","gunluk":{"t":"Yediyi grupla","adim":["Sofrada 7 cevizi 5+2 ya da 4+3 diye gruplayın.","«Saymadan, gruplara bakarak 7 olduğunu görüyor musun?» deyin.","Büyük çokluğu tanıdık küçük parçalara bölmeyi özendirin."],"soyle":"«Beş ve iki; gruplara bakınca yedi olduğunu görüyor musun?»","isaret":"7'yi tanıdık alt gruplara bölerek saymadan görür."},"oyun":{"t":"Beşi ayır","adim":["Bir avuç düğmeyi (6-7) masaya atın.","Çocuk önce «5'i bir kenara ayır» desin.","Sonra kalanları ekleyip «5 ve 2, yedi» desin."],"soyle":"«Önce beşi ayır, kalanı ekle: beş ve iki, yedi.»","isaret":"İki grup üzerinden 7'yi parça-bütünle bulur."},"yaprak":{"t":"Yediyi iki öbek","adim":["Kâğıtta 7'yi iki öbek çizin (5'li çerçeve dolu + yanda 2 nokta).","Çocuk «5 ve 2 = 7» diye okusun.","Sonra 7'yi 4+3 olarak kendi çizsin."],"soyle":"«Beş ve iki, yedi; şimdi yediyi dört ve üç olarak çiz.»","isaret":"7'yi iki ayrı parçalanışla gösterir."}},{"order":9,"kazanim":"Kavramsal Sanbil (10’a kadar)","gunluk":{"t":"Beş ve fazlası","adim":["Yumurta/bardakları «5'erli iki grup» ya da «5 ve birkaç fazlası» gösterin.","«Baktın, kaç var? 5 ve 3, sekiz» deyin.","10'a kadar çoklukları hep 5'i çapa alıp gruplatın."],"soyle":"«Beş ve üç; gruplara bakınca sekiz olduğunu görüyor musun?»","isaret":"6-10 arası sayıları 5'i çapa alıp gruplayarak görür."},"oyun":{"t":"İki zarı grupla","adim":["İki zar atın.","Çocuk her zarı tek tek değil, ikisini grup halinde görsün.","Toplamı saymadan söylesin (örn. 5 ve 4 → 9)."],"soyle":"«Zarları tek tek sayma; gruplara bak, toplam kaç?»","isaret":"İki zar grubunu birleştirip toplamı saymadan söyler."},"yaprak":{"t":"Onluk çerçevede","adim":["10'luk çerçeve (iki sıra 5'li kutu) çizip içine 8 nokta koyun.","Çocuk «üst sıra dolu 5, altta 3, yani 8» desin.","10'luğun yapısı 6-10'u bakışta çözmeyi sağlar."],"soyle":"«Üst sıra beş dolu, altta üç; demek sekiz.»","isaret":"Onluk çerçevede 6-10'u 5+fazlası diye okur."}},{"order":10,"kazanim":"Kavramsal Sanbil (20’ye kadar)","gunluk":{"t":"On ve birkaç","adim":["Bir avuç (12-16) makarna gösterip «önce 10'unu bir tabağa al» deyin.","«Kalan kaç?» diye sorup «10 ve 4, on dört» diye okutun.","Büyük çoklukları «bir tam onluk + birkaç tane» diye gördürün."],"soyle":"«Önce on'u ayır; on ve dört, on dört.»","isaret":"20'ye dek sayıyı bir onluk + birlikler olarak görür."},"oyun":{"t":"Çift çerçeve","adim":["İki 10'luk yumurta kartonu/çerçeve koyun.","Çocuk 14 boncuğu yerleştirsin.","«Bir çerçeve tam doldu (10), öbüründe 4 var» diye saymadan söylesin."],"soyle":"«Bir çerçeve doldu, on; ötekinde dört; hepsi on dört.»","isaret":"11-20'yi onluk öbek + birlik olarak görür."},"yaprak":{"t":"On ve nokta","adim":["Kâğıda dolu bir 10'luk + yanında 5 nokta çizin.","Çocuk «10 ve 5 = 15» diye okusun.","Sonra siz 17 deyince onu 10+7 olarak işaretlesin."],"soyle":"«On ve beş, on beş; şimdi on yediyi on ve yedi olarak göster.»","isaret":"20'ye dek sayıları onluk+birlik öbekleriyle tanır."}},{"order":11,"kazanim":"Basamak Değeriyle Sanbil","gunluk":{"t":"Kaç onluk kaç tek","adim":["Para üstü verirken 23'ü «2 onluk (yirmi) ve 3 birlik» diye gösterin.","10'luk paraları/çubukları öbekleyin.","«Kaç onluk, kaç tek?» diye bakıştan okutun."],"soyle":"«İki onluk yirmi, üç birlik; demek yirmi üç.»","isaret":"Sayıyı onluk-birlik öbek yapısı olarak bakışta okur."},"oyun":{"t":"Demet yap","adim":["10 kürdanı bir lastikle bağlayıp «demet» yapın.","Masaya 2 demet + 4 tek koyun.","«Saymadan kaç? Yirmi dört» dedirtin; demet sayısı onluğu anında verir."],"soyle":"«İki demet, dört tek; saymadan: yirmi dört.»","isaret":"Onluk demetleri ve tekleri öbekleyerek bakışta okur."},"yaprak":{"t":"Onluk çubuk","adim":["Kâğıda onluk çubuklar (||) ve tek noktalar çizip «3 onluk 2 birlik» gösterin.","Çocuk «32» yazsın.","Sonra siz 41 deyince 4 demet 1 tek çizsin."],"soyle":"«Üç onluk, iki birlik; bu sayı kaç? Otuz iki.»","isaret":"Onluk-birlik öbeklerini basamak değerine çevirir."}},{"order":12,"kazanim":"Çarpımsal Düşünmeyle Sanbil","gunluk":{"t":"Sıra çarpı sütun","adim":["Yumurta kartonuna (2 sıra × 5) bakın.","«Saymadan: 2 sıra, her biri 5, demek 10» deyin.","Bisküvi tepsisini «şu kadar sıra × şu kadar» diye okutun."],"soyle":"«İki sıra, her sıra beş; saymadan demek ki on.»","isaret":"Dizilimi satır×sütun çarpımsal birimle, saymadan okur."},"oyun":{"t":"Dört sıra üç","adim":["Düğmeleri 3'erli 4 sıra dizin.","Çocuk «4 sıra, her sıra 3, hepsi saymadan 12» desin.","Sıra/sütun sayısını değiştirip her seferinde çarpımsal birimle buldurun."],"soyle":"«Dört sıra, her sırada üç; tek tek sayma, kaç eder?»","isaret":"Diziyi sıra ve sütun olarak görüp çarpımsal bulur."},"yaprak":{"t":"Nokta dizisi","adim":["Kâğıda nokta dizileri çizin (örn. 5 sütun × 3 satır).","Çocuk «3 kere 5, on beş» diye okuyup yanına yazsın.","Sonra boş ızgaraya kendisi 2×6'lık bir dizi çizip adlandırsın."],"soyle":"«Üç sıra, beşer nokta; üç kere beş, on beş.»","isaret":"Diziyi çarpımsal birimle okuyup kendi dizisini kurar."}}]},"count":{"code":"Y02","name":"Sayma","strand":"sayi","levels":[{"order":1,"kazanim":"Sayı Sözcükleriyle Tanışan: Temeller","gunluk":{"t":"Gün boyu sayı mırıltısı","adim":["Merdiven çıkarken her basamakta 'bir, iki, üç' deyin.","Mama verirken 'bir kaşık, iki kaşık' diye sesli sayın.","Doğru sayı değil, kulağın sayı sözcüklerine alışması amaç; bol bol tekrarlayın."],"soyle":"«Bir kaşık... iki kaşık... aferin sana!»","isaret":"Bebek sizi duyunca seslere bakıyor, ağzıyla taklit etmeye çalışıyor."},"oyun":{"t":"Parmak sayma şarkısı","adim":["Karşılıklı oturun, parmakları tek tek açarak 'bir parmak, iki parmak' söyleyin.","Bir ezgi uydurup sayı sözcüklerini neşeyle tekrarlayın.","Çocuk sesleri taklit etmeye çalıştıkça gülümseyip alkışlayın."],"soyle":"«Bir parmak, iki parmak... hadi sen de söyle!»","isaret":"Çocuk parmaklarına bakıp sizinle birlikte sesler çıkarmaya çalışıyor."},"yaprak":{"t":"Sayılı tekerleme","adim":["İçinde sayı geçen sevdiği bir tekerleme/şarkı seçin (örn. 'Bir küçük serçe').","Her gün birlikte söyleyin, sayı sözcüklerini biraz vurgulayın.","Siz model olun; çocuğun katılması yeterli, doğruluk aramayın."],"soyle":"«Bir küçük serçe... duydun mu, 'bir' dedik!»","isaret":"Çocuk tekerlemenin sayı kısmını mırıldanmaya başlıyor."}},{"order":2,"kazanim":"Ezbere Sayan","gunluk":{"t":"Akışı bozmayan sayma","adim":["Birlikte sesli sayın; çocuk 'bir, iki, dört' dese bile durdurmayın.","Siz arkadan doğru sırayı neşeyle mırıldanıp model olun.","Amaç diziyi duya duya akıcı söylemek; hata düzeltmeyin."],"soyle":"«Sen say, ben de yanında sayayım: bir, iki, üç...»","isaret":"Çocuk kendiliğinden sayı dizisini söylüyor, birkaç sözcüğü sırayla getiriyor."},"oyun":{"t":"Saklambaçta sayma","adim":["Saklambaç oynayın; ebe olunca yüksek sesle sayın.","Çocuğu da saymaya katın, eksik söylese bile oyunu sürdürün.","Sayı dizisini oyunun keyfiyle, baskısız duysun."],"soyle":"«Ben sayarken sen de say, sonra gelip seni bulacağım!»","isaret":"Çocuk saklanırken sizinle birlikte birkaç sayıyı sırayla söylüyor."},"yaprak":{"t":"Havada birlikte sayma","adim":["'Hadi beraber sayalım' deyip parmağınızı havada sallayın.","1'den yukarı doğru birlikte sayın, çocuğun temposuna uyun.","Nereye kadar gittiği değil, denemesi önemli; çabasını kutlayın."],"soyle":"«Bakalım bugün nereye kadar sayabileceğiz!»","isaret":"Çocuk istekle sayıyor ve dünden biraz daha ileri gidiyor."}},{"order":3,"kazanim":"Ezbere Sayan (10’a kadar)","gunluk":{"t":"On'a kadar günlük sayım","adim":["Merdiven basamaklarını, kapı çalışlarını ya da el çırpışlarını 1'den 10'a sayın.","Hata olursa baştan başlatmayın; doğru sözcüğü siz söyleyip akıcı devam edin.","Orta bölgede 'altı-yedi' gibi takıldığı yerlere ekstra tempo verin."],"soyle":"«...beş, altı, yedi... hadi onluğa kadar gidelim!»","isaret":"Çocuk 1'den 10'a kadar atlamadan, sırayı bozmadan söylüyor."},"oyun":{"t":"On'a kadar kovalama","adim":["'10'a kadar sayınca yakalıyorum' deyin; siz 1-10 sayarken çocuk kaçıp saklansın.","Her turda sayıyı birlikte düzgün söyleyin.","10'a varınca neşeyle yakalamaya gidin."],"soyle":"«Bir, iki, üç... on! Şimdi geliyorum!»","isaret":"Çocuk her turda 10'a kadar diziyi sizinle doğru söylüyor."},"yaprak":{"t":"On adım yürüyüşü","adim":["Yere bir ip/çizgi koyun ya da çizin.","Çizgi boyunca tam 10 adım atın, her adımda sırayla sayın.","10'a varınca 'Tam 10!' diye birlikte sevinin."],"soyle":"«Bir adım, iki adım... on! Tam onluk oldu!»","isaret":"Çocuk on adımı sayarak atıyor ve onda durmayı biliyor."}},{"order":4,"kazanim":"Birebir Eşleyerek Sayan","gunluk":{"t":"Dokunarak birebir sayma","adim":["Sofra kurarken her tabağa dokunarak 'bir... iki... üç' deyin.","Çocuk da parmağıyla her nesneye dokunarak saysın.","Her nesneye TAM bir sözcük düşmesine dikkat çekin; el ile söz aynı anda gitsin."],"soyle":"«Her tabağa dokununca bir sayı söylüyoruz: bir... iki...»","isaret":"Çocuğun parmağı ile söylediği sayı aynı anda gidiyor; atlama ya da çift sayma yok."},"oyun":{"t":"Birer birer dokun-say","adim":["Düğme ya da fasulyeleri bir sıraya dizin.","Çocuk her birine parmak basarak saysın.","Hızlanıp atlarsa elini hafifçe tutup 'birer birer dokunalım' deyin."],"soyle":"«Parmağın nereye değerse oraya bir sayı: dokun-say, dokun-say.»","isaret":"Çocuk acele etmeden her nesneye dokunup bir sayı söylüyor."},"yaprak":{"t":"Noktalara parmak basma","adim":["Kâğıda 3-4 çıkartma/nokta yapıştırın ya da çizin.","Çocuk her birinin üstüne parmağını koyup saysın.","Kaç noktaya dokunduysa o kadar söylesin; eşleşmeyi gözleyin."],"soyle":"«Bu noktaya dokun, 'bir'; şuna dokun, 'iki'...»","isaret":"Nokta sayısı kadar sayı söylüyor; her noktaya bir kez dokunuyor."}},{"order":5,"kazanim":"Küçük Sayıları Sayan (Kardinal Değer)","gunluk":{"t":"Son sayı toplamı verir","adim":["Çocuk birkaç oyuncağı sayınca 'Peki kaç tane var?' diye sorun.","Yeniden saymaya başlarsa 'Son söylediğin sayı bize toplamı verir' deyin.","Son sözcüğü vurgulayıp tekrarlatın: 'Demek 4 tane.'"],"soyle":"«Saydın: bir, iki, üç, dört. O zaman toplam kaç? Dört!»","isaret":"'Kaç tane?' sorusuna yeniden saymadan son sayıyı söylüyor."},"oyun":{"t":"Avuçta kaç var?","adim":["Avucunuza 3-4 küçük nesne saklayıp açın.","Birlikte sayın, sonra 'Hepsi kaç?' diye sorun.","Çocuk son sayıyı söyleyince 'Evet, 4 tane!' diye onaylayın."],"soyle":"«Saydık, en son 'dört' dedik; demek hepsi dört tane.»","isaret":"Sayımı bitirince toplam sorusuna son sayıyla cevap veriyor."},"yaprak":{"t":"Kutuda kaç vardı?","adim":["Bir kutuya 2-5 nesne koyup çocuğa saydırın.","Kapağı kapatıp 'İçinde kaç tane vardı?' diye sorun.","Kapalıyken son sayıyı hatırlayıp söylemesini bekleyin."],"soyle":"«Kapağı kapattık ama biliyorsun: en son kaç demiştin?»","isaret":"Kutu kapalıyken yeniden açmaya gerek duymadan toplamı söylüyor."}},{"order":6,"kazanim":"10’a Kadar Sayan","gunluk":{"t":"On'a güvenli sayım","adim":["Market poşetinden elma/yumurta gibi 10'a kadar şeyi birlikte birer birer yerleştirin.","Her gün farklı bir nesneyle 10'a ulaşın.","Hızlanınca atlamamasına, bir nesneyi iki kez saymamasına dikkat edin."],"soyle":"«Yavaş yerleştirelim ki hiçbirini atlamayalım: bir, iki...»","isaret":"On nesneyi atlamadan ve tekrar saymadan doğru sayıyor."},"oyun":{"t":"Zar at, birleştir, say","adim":["Bir zar atıp çıkan sayı kadar adım attırın.","Sonra iki avuçtaki nesneleri masada birleştirip 10'a kadar sayın.","Her seferinde doğru bitirmesine sevinin."],"soyle":"«Hepsini bir araya koyduk; şimdi tek tek sayalım, kaç çıkacak?»","isaret":"Birleştirdiği nesneleri karıştırmadan 10'a kadar sayabiliyor."},"yaprak":{"t":"Say, karıştır, yine say","adim":["10 bardak/kapak dizip sırayla sayın.","Sonra karıştırıp tekrar saydırın.","Sayının değişmeden hep 10 çıktığını birlikte görün."],"soyle":"«Yerlerini değiştirdik ama yine on; saymak hep on veriyor!»","isaret":"Dizilim değişse de her seferinde 10'da bitiriyor."}},{"order":7,"kazanim":"İstenen Sayıda Nesne Veren (Küçük Sayılar)","gunluk":{"t":"Tam o kadarını getir","adim":["Mutfakta 'Bana 3 çatal verir misin?' gibi küçük istekler yapın.","Çocuk sayarak tam o kadarını getirsin, fazla ya da eksik değil.","Doğru sayıda durduğunda 'tam 3, harika' diye pekiştirin."],"soyle":"«Bana tam 3 tane lazım; sayarak getir, üçte dur.»","isaret":"İstenen sayıda nesneyi sayıp doğru miktarda durarak getiriyor."},"oyun":{"t":"Sipariş oyunu","adim":["Siz 'müşteri' olun: '2 düğme lütfen', 'şimdi 4 fasulye' deyin.","Çocuk 'garson' olarak istenen kadarını sayıp tabağa koysun.","Her siparişte farklı sayı isteyip doğru sayıda durmasını bekleyin."],"soyle":"«Garson, bana 4 fasulye lütfen; sayarak koy.»","isaret":"Söylenen sayı kadar nesne koyup orada duruyor, eklemeye devam etmiyor."},"yaprak":{"t":"Karttaki kadar koy","adim":["Üzerinde 2, 3 ya da 4 nokta olan bir kart gösterin.","'Bu kadar taş koy' deyin; çocuk istenen çokluğu sayarak üretsin.","Koydukça dokunup kontrol etsin, sayı ile miktarı eşlesin."],"soyle":"«Kartta 3 nokta var; sen de tam 3 taş koy.»","isaret":"Karttaki sayı kadar nesneyi sayarak üretip doğru sayıda bırakıyor."}},{"order":8,"kazanim":"Sayıp Veren (10 ve ötesi)","gunluk":{"t":"On'un ötesine sayma","adim":["Çamaşır asarken/oyuncak toplarken 'on bir, on iki...' diye 10'u geçin.","Sonra 'Bana 12 mandal getir' deyip o kadarını saydırın.","'On bir, on iki' derken onluk yapısını koparmamasına dikkat edin."],"soyle":"«On'dan sonra duruyoruz: on bir, on iki, on üç...»","isaret":"On'un ötesini 'on bir, on iki' diye doğru söylüyor ve istenen sayıyı getiriyor."},"oyun":{"t":"İki zar topla, say","adim":["İki zar atıp çıkanları birleştirerek 12-15'e kadar sayma yarışı yapın.","Ardından 'Şu kadar fındık say bana' diyerek istenen çokluğu ürettirin.","On geçişinde takılırsa birlikte 'on, on bir' diye köprüleyin."],"soyle":"«İki zarı topladık; on'u geçtik mi? On bir, on iki!»","isaret":"İki kümeyi birleştirip 10'un üstüne çıkarak sayıyor."},"yaprak":{"t":"Kavanozda on üstü","adim":["Bir kavanoza 11-15 nesne koyup birlikte sayın.","Sonra 'Şuraya 13 tane say' deyin.","Hem doğru saysın hem o kadarını üretsin."],"soyle":"«On'u geçtik, devam: on bir, on iki, on üç!»","isaret":"On'un ötesinde sayıyor ve istenen sayıda nesneyi ayırabiliyor."}},{"order":9,"kazanim":"10’dan Geriye Sayan","gunluk":{"t":"Geriye sayım uçuşu","adim":["Roket/asansör oyunu yapın: '10, 9, 8... fırlat!' diye geriye sayın.","Yatmadan ışıkları kapatırken 10'dan geriye sayıp uykuya geçin.","Bir basamak atlamamasına ve yön karıştırmamasına dikkat edin."],"soyle":"«On, dokuz, sekiz... sıfır! Fırlat!»","isaret":"10'dan geriye atlamadan, ileri kaçırmadan akıcı sayıyor."},"oyun":{"t":"Kuleyi yıkma sayımı","adim":["10 bloktan bir kule yapın.","Her bloğu çekerken 10'dan geriye sayın.","Sıfıra inince 'Bom!' deyip kuleyi yıkın."],"soyle":"«Bir blok çek: on. Bir daha: dokuz... sıfırda yıkıyoruz!»","isaret":"Her bloğu çekerken bir önceki sayıdan geriye doğru söylüyor."},"yaprak":{"t":"Geriye inen merdiven","adim":["Kâğıda 10'dan 1'e doğru bir merdiven çizin.","Çocuk parmağıyla yukarıdan aşağı her basamağı geriye sayarak insin.","Yön karışırsa parmağını tutup aşağı doğru ilerletin."],"soyle":"«En üstten başla: on, dokuz... aşağı doğru iniyoruz.»","isaret":"Parmağıyla aşağı inerken 10'dan geriye sırayı bozmadan sayıyor."}},{"order":10,"kazanim":"İstenen Sayıdan Sayan (öncesi/sonrası)","gunluk":{"t":"O sayıdan devam et","adim":["Bir sayıdan başlatın: 'Hadi 4'ten devam: beş, altı, yedi...'","Geri için 'Yediden geri: altı, beş' deyin.","Başlangıç sayısını TEKRAR söylemeden bir sonrakinden başlasın ('dört' deyince beşten devam)."],"soyle":"«Dört'ten devam; dört'ü tekrar söyleme, beşten başla.»","isaret":"Verilen sayıyı tekrar etmeden bir sonraki/önceki sayıdan devam ediyor."},"oyun":{"t":"İleri mi, geri mi?","adim":["Zar atın; çıkan sayıyı (örn. 6) söyleyin.","'İleri mi, geri mi?' diye seçtirip oradan saydırın.","1'den başlamadan, o sayıdan devam etmesini isteyin."],"soyle":"«Altı geldi; ileri gidersek yedi, geri gidersek beş.»","isaret":"Baştan saymaya gerek duymadan verilen sayının komşusundan devam ediyor."},"yaprak":{"t":"Karttan ileri-geri","adim":["Bir kart çekip üstündeki sayıyı (örn. 7) okuyun.","O sayıdan başlayarak ileri ya da geri 3-4 sayı söyletin.","Baştan saymaya gerek olmadığını gösterin."],"soyle":"«Kartta yedi var; bundan sonra ne gelir? Sekiz, dokuz...»","isaret":"Karttaki sayıdan başlayıp ileri/geri birkaç sayıyı doğru söylüyor."}},{"order":11,"kazanim":"Onar Sayan (100’e kadar)","gunluk":{"t":"Onar onar yüze","adim":["Bozuk paraları/onlukları onar onar dizerken 'on, yirmi, otuz...' diye sayın.","Merdiveni onar sayar gibi tempo tutup 100'e ulaşın.","'On-on' diye birer eklemeye kaymamasına, gruplayarak gitmesine dikkat edin."],"soyle":"«On, yirmi, otuz... her seferinde tam bir onluk ekliyoruz.»","isaret":"Birer eklemeye kaymadan onar onar 100'e kadar sayıyor."},"oyun":{"t":"Onluk yığın oyunu","adim":["Fasulyeleri 10'arlı yığınlara ayırın.","Her yığını eklerken 'on, yirmi, otuz' diye sayın.","Yığınlar bittiğinde 100'e ulaştığınızı birlikte görün."],"soyle":"«Bir yığın on; bir yığın daha, yirmi...»","isaret":"Her 10'luk yığını eklerken onar ritmiyle sayıyor."},"yaprak":{"t":"El açışıyla onar","adim":["Elinizi açıp kapatın; her açışta 10 sayın.","'On, yirmi, otuz...' diye her açışta 10 ekleyin.","On kez açınca 100'e vardığınızı birlikte sayın."],"soyle":"«Her elimi açışım on; kaç kez açtık, o kadar onluk!»","isaret":"On açışta onar sayarak 100'e ulaştığını fark ediyor."}},{"order":12,"kazanim":"100’e Kadar Sayan","gunluk":{"t":"Yüze birer sayım","adim":["Uzun bir yürüyüşte ya da ip atlarken sırayla 1'er 1'er 100'e sayın.","Yorulunca kaldığınız sayıyı not edip ertesi gün oradan devam edin.","Onluk geçişlerde (yirmi dokuz→otuz) takılırsa birlikte aşın."],"soyle":"«Yirmi dokuz'dan sonra... otuz! Yeni onluğa geçtik.»","isaret":"Onluk geçişlerinde takılmadan 100'e kadar birer birer sayıyor."},"oyun":{"t":"Sırayı kaçırma topu","adim":["Top atıp tutarken sırayla bir sayı söyleyin (siz 41, o 42...).","100'e ulaşan kazanır.","Geçiş eşiklerinde durmadan akıcı devam edin."],"soyle":"«Ben kırk bir, sen kırk iki... kim yüze varacak?»","isaret":"Sırayla, geçişlerde duraksamadan 100'e doğru sayıyor."},"yaprak":{"t":"Yüzlük tablo gezisi","adim":["1-100 sayı tablosunu (gazete/takvim olur) parmakla takip edin.","1'er 1'er okuyun.","Her on sonunda durup 'şimdi yeni onluğa geçiyoruz' deyin."],"soyle":"«...yirmi dokuz, otuz; bak, otuzlu onluğa geçtik!»","isaret":"Tabloda parmağıyla izleyerek 100'e kadar onluk geçişleri doğru okuyor."}},{"order":13,"kazanim":"Ritim Tutarak Üzerine Sayan","gunluk":{"t":"Sonları aynı gidiyor","adim":["İleri sayarken örüntüyü fark ettirin: '21, 22, 23... 31, 32, 33'.","'Duydun mu, sonları aynı gidiyor!' deyin.","Bir onluktan diğerine geçerken kuralı sesli söyleyin."],"soyle":"«Yirmi BİR, otuz BİR, kırk BİR — son hep aynı!»","isaret":"Sayı örüntüsünü fark edip her sayıyı baştan saymadan ileri gidiyor."},"oyun":{"t":"Sütunla zıplama","adim":["Sayı tablosunda bir sütunu (1, 11, 21, 31) örüntüyle okuyun.","'Sıradaki ne olur?' diye tahmin ettirin.","Örüntüyü kullanarak ileri zıplayın."],"soyle":"«Bir, on bir, yirmi bir... sıradaki sence kaç?»","isaret":"Örüntüye bakarak bir sonraki sayıyı saymadan tahmin ediyor."},"yaprak":{"t":"Örüntüyü tamamla","adim":["Bir satırı yarıya kadar yazın: '34, 35, 36, __, __'.","Örüntüye bakarak devamını çocuğa tamamlatın.","Kuralı bulup yazmasına sevinin."],"soyle":"«Üç-dört, üç-beş, üç-altı... sonra ne yazarız?»","isaret":"Boşlukları örüntü kuralıyla, tek tek saymadan dolduruyor."}},{"order":14,"kazanim":"Ritmik Sayan (beşer, ikişer)","gunluk":{"t":"İkişer-beşer-onar","adim":["Çorapları/ayakkabıları 2'şer ('2, 4, 6...') sayın.","Parmakları 5'er, paraları 10'ar sayın.","Araya fazladan terim katmamasına, örüntüyü birer saymaya çevirmemesine dikkat edin."],"soyle":"«Çoraplar ikişer gelir: iki, dört, altı...»","isaret":"Araya terim katmadan ikişer/beşer/onar ritmik sayabiliyor."},"oyun":{"t":"El çırpma ritmi","adim":["Birlikte '2, 4, 6, 8' diye çırparak sayın.","Sonra 5'er, sonra 10'ar tempoyla sayın.","Ritmi kaçıran olunca birlikte gülün ve baştan tutturun."],"soyle":"«İki (çırp), dört (çırp), altı (çırp)...»","isaret":"Çırpma temposuyla ritmik sayıyı bozmadan sürdürüyor."},"yaprak":{"t":"Gruplayıp say","adim":["Nesneleri 2'şerli (ya da 5'erli) gruplayın.","Her grubu bir kez sayarak '2, 4, 6' deyin.","Tek tek saymadan gruplarla toplama ulaşın."],"soyle":"«Bu grup iki, şu grup dört... tek tek saymadık!»","isaret":"Grupları kullanarak ritmik sayıyor, her nesneyi tek tek saymıyor."}},{"order":15,"kazanim":"Saydığını Takip Ederek Sayan","gunluk":{"t":"Nerede kaldığını bil","adim":["'Şimdi 5 ceviz say, parmaklarında tut' gibi görevler verin.","Saydıkça nerede kaldığını parmakla işaretlesin.","Şaşırmadan, baştan başlamadan istenen sayıda dursun."],"soyle":"«Beş ceviz; parmaklarında say, kaçta olduğunu unutma.»","isaret":"Kaç saydığını takip edip istenen sayıda durabiliyor, baştan başlamıyor."},"oyun":{"t":"Saklı sayım","adim":["Nesneleri bir örtü altında tek tek alıp sayın.","Örtü kapalıyken 'kaça geldik?' diye sorun.","Saydığını aklında tutup söylesin."],"soyle":"«Göremiyoruz ama sen biliyorsun: şu ana kadar kaç saydık?»","isaret":"Göremeden, saydığı miktarı zihninde tutup söyleyebiliyor."},"yaprak":{"t":"Kaç attığını izle","adim":["Bir kavanoza fasulye atarken her atışı parmakla işaretletin.","Kaç attığını takip etsin.","'Tam 8 attın mı?' diye birlikte kontrol edin."],"soyle":"«Her attığında bir parmak; bakalım sekize geldik mi?»","isaret":"Attığı sayıyı kaybetmeden takip edip hedefte durabiliyor."}},{"order":16,"kazanim":"Basamak Değerini Kavrayan","gunluk":{"t":"Onluk on eder","adim":["Para/lego sayarken 'bir onluk on eder' fikrini kullanın.","'Şu 10'luk demet 10, üstüne 3 birlik, eder 13' deyin.","Onluk ve birlikleri ayırarak, tek tek saymadan sayın."],"soyle":"«Bir onluk on; üstüne üç tek koyduk: on üç.»","isaret":"Çokluğu onluk ve birlik diye ayırıp tek tek saymadan söylüyor."},"oyun":{"t":"Onluk demet sayımı","adim":["10 çöpü bir lastikle bağlayıp 'onluk demet' yapın.","Demetleri ve tek çöpleri birlikte sayın.","'10, 20, 23' gibi önce demetleri sonra tekleri okuyun."],"soyle":"«İki demet: yirmi; üstüne üç tek: yirmi üç.»","isaret":"Demet sayısından onluğu anında verip birlikleri ekleyebiliyor."},"yaprak":{"t":"Demet ve tek diz","adim":["Bir sayıyı (örn. 24) onluk demetler + tek nesnelerle dizdirin.","'2 demet, 4 tek' diye çözümlesin.","Çokluğu basamaklara ayırarak göstersin."],"soyle":"«Yirmi dört: iki demet, dört tek. Demetler onluk!»","isaret":"Bir sayıyı doğru sayıda onluk ve birliğe ayırarak diziyor."}},{"order":17,"kazanim":"100’ün Ötesine Sayan","gunluk":{"t":"Yüzü geçen sayım","adim":["100'ü geçen şeyleri sayarken geçişe dikkat çekin: '...98, 99, 100, 101!'","Araba plakaları, sayfa numaralarıyla 100'ün ötesine geçin.","Yüzlük/onluk geçişlerde atlamamasına dikkat edin."],"soyle":"«Doksan dokuz'dan sonra yüz, sonra yüz bir!»","isaret":"100'ün ötesinde geçişlerde takılmadan, atlamadan sayıyor."},"oyun":{"t":"Yüz eşiği yarışı","adim":["Zar atıp 95'ten başlayarak ileri sayma yarışı yapın.","'99'dan sonra ne gelir?' eşiğinde durun.","Birlikte '100, sonra 101' diye geçişi aşın."],"soyle":"«Doksan dokuz... şimdi büyük eşik: yüz!»","isaret":"Yüz eşiğinde duraksamadan 100'ün ötesine geçebiliyor."},"yaprak":{"t":"Geçişleri işaretle","adim":["98'den 110'a kadar olan sayıları sırayla yazdırın.","100 ve 110 geçişlerinde durun.","'Yeni yüzlüğe/onluğa geçtik' diye birlikte işaretleyin."],"soyle":"«Yüz'e ve yüz on'a geldik; yeni basamak başladı!»","isaret":"Yazarken yüzlük ve onluk geçişlerini doğru ve sırasıyla yapıyor."}},{"order":18,"kazanim":"Sayının Korunduğunu Bilen","gunluk":{"t":"Yine aynı sayı","adim":["Bisküvileri sayıp sonra tabakta yayın ya da üst üste koyun.","'Dağıttık ama yine 6 tane, değişmedi' deyin.","Dizilim değişince 'daha çok/az' dememesine dikkat çekin."],"soyle":"«Yaydık ama eklemedik; saysak yine altı çıkar.»","isaret":"Nesneler yayılıp toplansa da sayının değişmediğini söylüyor."},"oyun":{"t":"Yer değişse de aynı","adim":["5 düğmeyi sıralayıp birlikte sayın.","Sonra dağıtıp tekrar saydırın.","Her seferinde 5 çıkınca birlikte şaşırıp gülün."],"soyle":"«Karıştırdık ama yine beş; sihir gibi, değil mi?»","isaret":"Düzeni bozulan kümede yeniden saymadan aynı sayıyı bekliyor."},"yaprak":{"t":"Sık-seyrek eşitlik","adim":["Aynı sayıda nesneyi iki farklı dizilişte (sık/seyrek) yan yana koyun.","İkisini de saydırın.","'Hangisi daha çok?' deyip eşit olduğunu keşfettirin."],"soyle":"«Biri uzun durdu, biri toplu; ama ikisi de altı!»","isaret":"Seyrek dizilen kümeyi 'daha çok' sanmadan, sayarak eşitliği görüyor."}},{"order":19,"kazanim":"İleri-Geri Akıcı Sayan","gunluk":{"t":"Onlar ve birlerle gez","adim":["Para üstü/merdiven sayarken esnek gidin: '40'tan 43'e birer, sonra 53'e onar'.","İleri-geri, onluk-birlik karışık sayın.","Birler bitince onluğu eksiltmeyi unutmamasına dikkat edin."],"soyle":"«Kırk'tan birer: kırk bir, iki, üç; şimdi onar: elli üç!»","isaret":"Onlar ve birler arasında yön ve basamak değiştirerek esnek sayıyor."},"oyun":{"t":"Ev tahtasında esnek atlama","adim":["Yılan-merdiven benzeri bir ev tahtası kurun.","Zar atıp bazen onar bazen birer ileri/geri ilerleyin.","'37'den 5 geri neresi?' gibi esnek sorular sorun."],"soyle":"«Otuz yedi'den beş geri: otuz altı, beş, dört, üç, iki!»","isaret":"İleri-geri ve onluk-birlik geçişlerini karıştırmadan yapıyor."},"yaprak":{"t":"Önce onar, sonra birer","adim":["Bir sayıdan (örn. 46) başlatın.","Önce onar ileri gitsin (56, 66), sonra birer geri (65, 64).","Onlar ve birler arasında rahatça gezinsin."],"soyle":"«Kırk altı'dan onar ileri, sonra birer geri; basamağa dikkat!»","isaret":"Onluk basamağı doğru ayarlayarak ileri-geri esnek sayıyor."}}]},"comp":{"code":"Y03","name":"Sayı Karşılaştırma ve Sıralama","strand":"sayi","levels":[{"order":1,"kazanim":"Karşılaştırma Duyarlılığı: Temeller","gunluk":{"t":"Tabakta çok-az","adim":["Bir tabağa bir avuç üzüm, ötekine 2-3 üzüm koyun; aradaki fark gözle belli olsun.","Saymadan «hangisinde daha çok var?» diye sorun.","Çocuk eliyle gösterince doğrulayın, gün içinde başka yiyeceklerle tekrarlayın."],"soyle":"«Bak, bu tabak çok daha kalabalık; hangisinde daha çok var?»","isaret":"Saymadan, bir bakışta kalabalık tabağı doğru gösterir."},"oyun":{"t":"Hangi kâse dolu?","adim":["İki kâseye belirgin farkla 1 ve 6 düğme koyun.","«Çok olan hangisi?» deyip çocuğun göstermesini bekleyin.","Doğru gösterince birlikte sevinin; kâseleri değiştirip yineleyin."],"soyle":"«Düğmeler hangi kâsede daha çok? Bana göster.»","isaret":"Çok olan kâseyi saymadan, kararlı biçimde seçer."},"yaprak":{"t":"Kalabalık tarafı bul","adim":["Kâğıdın bir yanına 1, öbür yanına 5 çıkartma/nokta yapıştırın.","Çocuktan kalabalık tarafı parmağıyla daire içine almasını isteyin.","Fark büyük olduğu için her denemede başarır; bol bol övün."],"soyle":"«Daha çok olanın etrafına bir yuvarlak çiz.»","isaret":"Daha çok olan tarafı saymadan daire içine alır."}},{"order":2,"kazanim":"Eşleyerek Karşılaştırmaya Başlayan","gunluk":{"t":"Çatala kaşık eşle","adim":["Sofrada çatalları bir sıra, kaşıkları altına bir sıra dizin.","Her çatalın altına bir kaşık eşleyip «hangisi arttı?» diye birlikte bakın.","Eşsiz kalan sıranın daha çok olduğunu birlikte söyleyin."],"soyle":"«Her çatala bir kaşık koyalım; bak, hangisinden arttı?»","isaret":"Eşleştirme sonunda artan sıranın çok olduğunu söyler."},"oyun":{"t":"Ayıya bardak","adim":["Oyuncak ayılarla bardakları birebir eşleyin.","Her ayıya bir bardak verin; artan ya da eksik kalanı bulun.","«Bu grupta fazla kaldı, demek daha çok» diye birlikte söyleyin."],"soyle":"«Her ayıya bir bardak; eşi olmayan kaldı mı?»","isaret":"Birebir eşleyip eşsiz kalan grubu çok diye seçer."},"yaprak":{"t":"Şekerleri bağla","adim":["İki sıra şeker çizin (biri bir fazla olsun).","Çocuk her üst şekeri alttakiyle çizgiyle bağlasın.","Eşi olmayan şekerin sırasını «daha çok» diye işaretlesin."],"soyle":"«Üsttekini alttakine çizgiyle bağla; eşsiz kalanı işaretle.»","isaret":"Eşleşmeden artan sırayı çok olarak işaretler."}},{"order":3,"kazanim":"Bakarak Karşılaştıran","gunluk":{"t":"Göz kararı seç","adim":["Markette biri belirgin kalabalık iki poşet/grup gösterin.","«Saymadan, bir bak: hangisinde daha çok var?» deyin.","Fark en az iki kat olduğundan göz kararı seçmesini destekleyin."],"soyle":"«Saymana gerek yok, bir bakışta söyle: hangisi daha çok?»","isaret":"Belirgin farklı iki grupta çoğu olanı saymadan seçer."},"oyun":{"t":"Para yığını","adim":["Masaya biri ötekinin iki katı olacak şekilde bozuk para dökün.","«Daha çok para nerede?» deyip çocuk kazananı seçsin.","Yığınları değiştirerek birkaç tur oynayın."],"soyle":"«İki para yığını var; hangisi daha çok? Bakışta söyle.»","isaret":"İki kat farklı yığında çok olanı tek bakışta seçer."},"yaprak":{"t":"Dolu kutuyu boya","adim":["Bir kutuya 3, diğerine 8 yıldız çizin.","«Belli ki dolu olanı boya, azı boş bırak» deyin.","Çocuk kalabalık kutuyu boyayınca onaylayın."],"soyle":"«Hangi kutu daha dolu? Onu boya.»","isaret":"Belirgin çok olan kutuyu saymadan boyar."}},{"order":4,"kazanim":"“Birinci–İkinci” Diyen","gunluk":{"t":"Birinci basamak","adim":["Merdiven çıkarken «birinci basamak, ikinci basamak» diye söyleyin.","Sonra durup «hangisine birinci dedik?» diye sorun.","Başlangıç noktasını sabit tutarak birinci-ikinciyi pekiştirin."],"soyle":"«Bu birinci basamak, bu ikinci; hangisi birinciydi?»","isaret":"Birinci ve ikinciyi sabit başlangıçtan doğru gösterir."},"oyun":{"t":"Yarış kürsüsü","adim":["İki oyuncak arabayı yarıştırın.","Önce geleni birinci, sonrakini ikinci kürsüye koyun.","«Birinci kim, ikinci kim?» diye çocuğa söyletin."],"soyle":"«Kim birinci geldi, kim ikinci? Kürsüye koyalım.»","isaret":"Yarış sonunu birinci-ikinci diye doğru sıralar."},"yaprak":{"t":"Birinciye yıldız","adim":["Yan yana iki kupa çizin.","Çocuk birinci olana 1 (ya da yıldız), ikinciye 2 koysun.","Hangisinin birinci olduğunu kendisi seçip işaretlesin."],"soyle":"«Birinci olana bir yıldız, ikinciye iki yaz.»","isaret":"Birinci ve ikinciyi doğru işaretler."}},{"order":5,"kazanim":"Aynı Tür Nesneleri Karşılaştıran","gunluk":{"t":"Bir fazla kurabiye","adim":["İki tabağa yakın sayıda (3 ve 4) aynı kurabiyeden koyun.","«Hangisinde bir tane daha fazla?» diye birlikte sayın.","Yakın sayılarda sayarak karar vermeyi gösterin."],"soyle":"«Sayalım bakalım: hangi tabakta bir tane daha çok?»","isaret":"Yakın çoklukta bir fazla olan tabağı sayarak bulur."},"oyun":{"t":"Lego eşleştir","adim":["İki kovaya aynı renk 4 ve 5 Lego koyun.","Çocuk Legoları teker teker eşlesin.","Eşsiz kalan tek parçadan «bu grup bir fazla» desin."],"soyle":"«Birer birer eşle; hangisinde bir tane artıyor?»","isaret":"Benzer nesnelerde bir fazla olan grubu eşleyerek bulur."},"yaprak":{"t":"Çok olana çentik","adim":["Aynı tür 4 ve 5 elma çizin.","Çocuk her iki grubu saysın.","Daha çok olan sepete bir çentik/işaret koysun."],"soyle":"«İkisini de say; çok olana bir çentik koy.»","isaret":"Yakın sayıdaki iki grubu sayıp çoğu olanı işaretler."}},{"order":6,"kazanim":"Farklı Tür Nesneleri Karşılaştıran","gunluk":{"t":"Farklı ama çok","adim":["Sofrada 3 çatal ile 5 peçeteyi yan yana koyun.","«Biri çatal, biri peçete ama hangisinden daha çok var?» deyin.","Nesneler farklı olsa da çokluğa bakmayı vurgulayın."],"soyle":"«Farklı şeyler bunlar; yine de hangisinden daha çok var?»","isaret":"Tür farklı olsa da çoğu olan grubu seçer."},"oyun":{"t":"Düğme mi fasulye mi","adim":["Bir avuç düğme ile bir avuç fasulyeyi masaya koyun.","Çocuk ikisini eşleyip sayıca çok olanı seçsin.","«Tür önemli değil, sayıya bakıyoruz» deyin."],"soyle":"«Düğme mi çok, fasulye mi? Sayıya bak.»","isaret":"Farklı nesneleri çokluğa göre karşılaştırıp seçer."},"yaprak":{"t":"Yıldız mı kalp mi","adim":["Kâğıda 4 yıldız ve 6 kalp çizin.","Çocuk ikisini saysın.","Şekiller farklı olsa da çok olan grubu yuvarlağa alsın."],"soyle":"«Yıldızlar mı çok, kalpler mi? Çok olanı yuvarlağa al.»","isaret":"Farklı şekilleri sayıp çoğu olanı daire içine alır."}},{"order":7,"kazanim":"Eşleyerek Karşılaştıran","gunluk":{"t":"Birebir kurabiye","adim":["İki tabağa aynı boy kurabiyeleri koyun.","Parmakla bir üstteki bir alttaki diye teker teker eşleyin.","Eşsiz kalan tabağı «bunda daha çok var» diye söyleyin."],"soyle":"«Birini buna, birini şuna; eşi kalmayan hangisinde?»","isaret":"Birebir eşleyip eşsiz kalan tabağı çok diye bulur."},"oyun":{"t":"Üst-alt eşle","adim":["İki sıraya aynı oyuncakları üst üste gelecek şekilde dizin.","Çocuk üsttekini alttakiyle birer birer eşlesin.","Fazla kalan sırayı «kazanan» ilan edin."],"soyle":"«Üsttekini alttakiyle eşle; fazla kalan sıra kazanır.»","isaret":"Eşlemede artan sırayı çok olarak belirler."},"yaprak":{"t":"Topları bağla","adim":["İki sıra aynı top çizin (biri bir fazla).","Her üst topu alt topla çizgiyle bağlasın.","Eşsiz kalan sırayı «çok» diye işaretlesin."],"soyle":"«Topları çizgiyle eşle; eşi olmayanı işaretle.»","isaret":"Birebir eşleyip artan sırayı çok diye işaretler."}},{"order":8,"kazanim":"Sayarak Karşılaştıran (eş boy nesneler)","gunluk":{"t":"Boncukları say","adim":["Aynı boy iki bardağa boncuk koyun.","İkisini de «bir, iki, üç» diye sesli sayın.","Sayıları karşılaştırıp «hangisi daha çok çıktı?» deyin."],"soyle":"«İkisini de sayalım; hangisinde daha çok çıktı?»","isaret":"Aynı boy iki kümeyi sayıp sayılara göre çoğu seçer."},"oyun":{"t":"Kâsede makarna","adim":["İki kâseye aynı makarnadan koyun.","Çocuk ikisini sayıp «4 mü, 3 mü çok?» diye karşılaştırsın.","Sezgiyle değil, sayı sonucuyla karar vermesini isteyin."],"soyle":"«Say bakalım, dört mü çok yoksa üç mü?»","isaret":"İki kümeyi sayıp sayıları kıyaslayarak çoğu söyler."},"yaprak":{"t":"Say ve yaz","adim":["Aynı büyüklükte iki kutuya farklı sayıda nokta koyun.","Çocuk her kutuyu sayıp altına sayıyı yazsın.","Büyük sayıyı işaretlesin."],"soyle":"«Her kutuyu say, sayısını yaz; büyük olanı işaretle.»","isaret":"İki kümeyi sayıp yazdığı sayılara göre büyüğü işaretler."}},{"order":9,"kazanim":"Kapladığı Yere Bakıp Tahmin Eden (az/çok)","gunluk":{"t":"Dolu mu, boş mu","adim":["İki kutuyu çocuğun eline alın; ağırlık/doluluk farkını hissetsin.","«Hangisi daha dolu hissettiriyor?» diye tahmin ettirin.","Sonra açıp tahmini birlikte kontrol edin."],"soyle":"«Elinde tut; sence hangisi daha dolu? Açıp bakalım.»","isaret":"Kaba bir doluluk tahmini yapıp kontrolle karşılaştırır."},"oyun":{"t":"Hangisine sığar","adim":["Farklı boy iki kutu hazırlayın.","«Hangisine daha çok şey sığar?» diye saymadan tahmin ettirin.","Sonra boşaltıp gerçeği birlikte görün."],"soyle":"«Sence hangisine daha çok sığar? Dökelim, görelim.»","isaret":"Uzamsal büyüklük tahmini yapıp sonra doğrular."},"yaprak":{"t":"Büyüğü boya","adim":["Bir küçük, bir büyük daire çizin.","«Daha çok şeker hangisine sığar?» diye düşündürün.","Çocuk büyük olanı boyasın."],"soyle":"«Hangi daireye daha çok şeker sığar? Onu boya.»","isaret":"Daha büyük alanı çok sığar diye seçer."}},{"order":10,"kazanim":"Sayarak Karşılaştıran (5’e kadar)","gunluk":{"t":"Beşe kadar say","adim":["İki tabağa birer avuç fındık koyun (4 ve 5 gibi).","İkisini de beşe kadar parmakla sayın.","«Hangisinde daha çok var?» diye sayıya göre birlikte söyleyin."],"soyle":"«Beşe kadar sayalım; hangi tabakta daha çok var?»","isaret":"5'e kadar sayıp sayılara göre çoğu olanı söyler."},"oyun":{"t":"Sayan kazanır","adim":["İki kâseye beşe kadar makarna koyun.","Çocuk ikisini de beşe kadar saysın.","Daha çok olanı bulan el oyunu kazansın."],"soyle":"«İkisini de beşe kadar say; çok olanı bulan kazanır.»","isaret":"Her kümeyi 5'e dek sayıp sayıları kıyaslar."},"yaprak":{"t":"Say, yaz, işaretle","adim":["İki kutuya beşe kadar farklı sayıda nokta çizin.","Çocuk her kutuyu sayıp altına sayıyı yazsın.","Çok olan kutuyu işaretlesin."],"soyle":"«Beşe kadar say, sayıyı yaz, çok olanı işaretle.»","isaret":"5'e dek sayıp yazdığı sayılarla çoğu işaretler."}},{"order":11,"kazanim":"Zihinsel Sayı Doğrusu (5’e kadar)","gunluk":{"t":"Merdivende kaç kaldı","adim":["Merdivende «şu an üçüncü basamaktasın» deyin.","«Beşe ulaşmak için kaç basamak kaldı?» diye sorun.","Sayıları sıralı bir yol gibi kafasında canlandırmasını sağlayın."],"soyle":"«Üçtesin; beşe varmak için kaç adım kaldı?»","isaret":"Sayıları sıralı bir doğru gibi düşünüp aradaki adımı söyler."},"oyun":{"t":"Zar at, ilerle","adim":["Yere 0'dan 5'e kartları sırayla dizin.","Zar atıp çıkan sayıya kadar adım atın.","Çocuk «şu an hangi sayıdayım?» diye durduğu yeri söylesin."],"soyle":"«Zarı at, o kadar ilerle; şimdi hangi sayıdasın?»","isaret":"Sayı yolunda durduğu konumu doğru söyler."},"yaprak":{"t":"Beşin yolu","adim":["Düz bir çizgiye 0 1 2 3 4 5 yazın.","«Üç burada nereye düşer?» diye sorun.","Çocuk 3'ün üstüne bir oyuncak/işaret koysun."],"soyle":"«Bu çizgide üç nereye düşer? Oraya koy.»","isaret":"0-5 doğrusunda sayıyı yaklaşık doğru yere koyar."}},{"order":12,"kazanim":"Büyüklük Sırasına Dizen (5’e kadar)","gunluk":{"t":"Azdan çoğa diz","adim":["Yerdeki 1-5 oyuncağı en azdan en çoğa sıralayın.","«İkiden sonra ne gelir?» diye sırayı konuşun.","Artan yönü bozmadan sırayı tamamlatın."],"soyle":"«En azdan en çoğa dizelim; ikiden sonra ne gelir?»","isaret":"1-5'i artan sırada, yön bozmadan dizer."},"oyun":{"t":"En küçüğü seç","adim":["1-5 noktalı kartları karışık verin.","Çocuk küçükten büyüğe dizsin.","Her adımda kalanların en küçüğünü seçsin."],"soyle":"«Her seferinde en küçüğü bul ve sıraya koy.»","isaret":"Kartları 5'e dek doğru artan sırayla dizer."},"yaprak":{"t":"Sırayı kur","adim":["Dağınık yazılmış 1-5 sayılarını verin.","Çocuk ok yönünde küçükten büyüğe dizsin.","Kutucuklara sırayla yazsın."],"soyle":"«Bu sayıları küçükten büyüğe sıraya diz.»","isaret":"1-5'i kutulara doğru artan sırayla yazar."}},{"order":13,"kazanim":"Sıra Sayılarını Kullanan (1.–10.)","gunluk":{"t":"Sırada kaçıncı","adim":["Sırada beklerken «öndeki birinci, sonraki ikinci, sen üçüncü» deyin.","Konumu sayıyla, çoklukla karıştırmadan söyleyin.","«Sen kaçıncısın?» diye sorup pekiştirin."],"soyle":"«Önde birinci, sonra ikinci; sen kaçıncısın?»","isaret":"Sıradaki konumunu (birinci, ikinci, üçüncü) doğru söyler."},"oyun":{"t":"Kaçıncıyı ver","adim":["Beş oyuncağı bir sıraya koyun.","«Üçüncüyü ver», «şimdi dördüncüyü göster» diye isteyin.","Çocuk konumu bulup o nesneyi seçsin."],"soyle":"«Soldan üçüncü oyuncağı bana ver.»","isaret":"İstenen sıra sayısındaki nesneyi (3., 4.) doğru seçer."},"yaprak":{"t":"Üçüncüyü boya","adim":["Yarış çizgisinde beş figür çizin.","Çocuk altlarına birinci, ikinci, üçüncü yazsın.","Üçüncü figürü boyasın."],"soyle":"«Soldan üçüncü figürü boya.»","isaret":"Sıra sayısını çoklukla karıştırmadan doğru figürü işaretler."}},{"order":14,"kazanim":"Sayarak Karşılaştıran (10’a kadar)","gunluk":{"t":"Ona kadar say","adim":["İki tabağa 7 ve 9 çekirdek koyun.","«Sayalım da görelim» deyip ona kadar dikkatlice sayın.","Sayılara göre hangisinin çok olduğuna karar verin."],"soyle":"«Ona kadar sayalım; hangi tabakta daha çok var?»","isaret":"10'a dek sayıp sayılara göre çoğu olanı seçer."},"oyun":{"t":"Kimde çok para","adim":["8 ve 6 parayı iki gruba ayırın.","Çocuk her grubu teker teker ona kadar saysın.","Daha çok para kimdeyse kazansın ve toplasın."],"soyle":"«İkisini de say; daha çok para kimde?»","isaret":"İki kümeyi 10'a dek dikkatle sayıp çoğu bulur."},"yaprak":{"t":"Daireleri say","adim":["İki kutuya ona kadar farklı sayıda daire çizin.","Çocuk ikisini de saysın ve sayıları yazsın.","Büyük olanı işaretlesin."],"soyle":"«Daireleri say, sayıları yaz, büyük olanı işaretle.»","isaret":"10'a dek sayıp yazdığı sayılara göre büyüğü işaretler."}},{"order":15,"kazanim":"Zihinsel Sayı Doğrusu (10’a kadar)","gunluk":{"t":"Yarıyı geçtin mi","adim":["Merdivende «yedinci basamaktasın» deyin.","«Beş nerede kalır, yarısını geçtin mi?» diye konuşun.","Sayıları 0-10 arası orantılı bir yol gibi düşündürün."],"soyle":"«Yedidesin; beşin ötesine geçtin mi, yarıyı aştın mı?»","isaret":"Bir sayının 0-10 yolunda nereye düştüğünü orantılı tahmin eder."},"oyun":{"t":"Sayıyı yerine koy","adim":["Yere 0-10 sayı doğrusu yapın.","«8'i koy» deyince çocuk doğru yere atlasın.","«5'in sağında mı solunda mı?» diye sorun."],"soyle":"«Sekizi doğruda nereye koyarsın? 5'in neresinde?»","isaret":"0-10 doğrusunda sayıyı orantılı yere yerleştirir."},"yaprak":{"t":"Orantılı işaretle","adim":["0 ve 10 işaretli boş bir çizgi çizin.","Çocuk 7'yi sağa yakın işaretlesin.","Sonra 3'ü de orantılı yere koysun."],"soyle":"«Yediyi sağa yakın, üçü sola yakın işaretle.»","isaret":"0-10 doğrusunda iki sayıyı da orantılı konumlandırır."}},{"order":16,"kazanim":"Büyüklük Sırasına Dizen (6 ve ötesi)","gunluk":{"t":"Küçükten büyüğe","adim":["Asansör ya da takvimden 8, 6, 9 gibi sayılar seçin.","«Bunları küçükten büyüğe nasıl sıralarız?» diye sorun.","«Sonra gelen daha büyüktür» kuralını birlikte söyleyin."],"soyle":"«Sekiz, altı, dokuz; küçükten büyüğe nasıl dizilir?»","isaret":"6 ve üzeri sayıları doğru artan sırayla söyler."},"oyun":{"t":"Kartları sırala","adim":["Üstünde 6-10 yazan kartları karışık verin.","Çocuk küçükten büyüğe dizsin.","«Yediden sonra hangisi gelir?» diye sorun."],"soyle":"«Bu kartları küçükten büyüğe diz; yediden sonra ne gelir?»","isaret":"6+ sayı kartlarını doğru artan sırayla dizer."},"yaprak":{"t":"En büyüğü bul","adim":["Dağınık 6-12 sayılarını yazın.","Çocuk küçükten büyüğe sıraya dizip kutulara yazsın.","En büyüğü daire içine alsın."],"soyle":"«Küçükten büyüğe sırala; en büyüğü yuvarlağa al.»","isaret":"6-12 sayılarını sıralayıp en büyüğü işaretler."}},{"order":17,"kazanim":"Kapladığı Yere Bakıp Tahmin Eden","gunluk":{"t":"İnce tahmin et","adim":["İki kavanoz fındık gösterin (biri ~20, biri ~30).","«Saymadan, hangisinde yaklaşık 30 var?» diye ince tahmin ettirin.","Sonra sayıp tahmine ne kadar yaklaştığını birlikte görün."],"soyle":"«Sayma; bir bak: hangisinde yaklaşık otuz var?»","isaret":"İki kümeyi göz kararıyla makul biçimde tahmin eder."},"oyun":{"t":"Kaç tane dersin","adim":["Bir avuç düğme gösterin.","«15 mi, 25 mi?» diye tahmin ettirin.","Beşerli gruplayıp gerçeğe ne kadar yaklaştığına bakın."],"soyle":"«Sence kaç tane: on beş mi, yirmi beş mi?»","isaret":"Bir kümeyi gözle tahmin edip gerçeğe yaklaştırır."},"yaprak":{"t":"Tahminini yaz","adim":["Seyrek ve sık iki nokta öbeği çizin.","Çocuk her birinin tahmini sayısını yanına yazsın.","Yoğunluğa değil çokluğa baktığını konuşun."],"soyle":"«Her öbekte sence kaç var? Tahminini yan tarafa yaz.»","isaret":"İki öbeğin sayısını makul biçimde tahmin eder."}},{"order":18,"kazanim":"Basamak Değeriyle Karşılaştıran","gunluk":{"t":"Önce onluğa bak","adim":["Etikette 23 mü 31 mi büyük diye sorun.","«Önce onluklara bak: 3 onluk, 2 onluktan çoktur» deyin.","Rakam adedine değil basamak değerine bakmayı gösterin."],"soyle":"«Önce onluklara bak: hangisinde daha çok onluk var?»","isaret":"İki basamaklı sayıları onluk basamağa bakarak karşılaştırır."},"oyun":{"t":"Onluk yarışı","adim":["43 ve 38'i onluk-birlik kartlarla gösterin.","Önce onluğa bakıp büyüğü bulan oyuncu puan alsın.","Onluk eşitse birliğe bakmayı ekleyin."],"soyle":"«Önce onlukları say; kimde çok onluk varsa o büyük.»","isaret":"Basamak değerini kullanarak büyük sayıyı seçer."},"yaprak":{"t":"Onlukları çiz","adim":["52 ve 49'u yan yana yazın.","Çocuk her sayının onluklarını çizip karşılaştırsın.","Büyük olanı işaretlesin."],"soyle":"«Onlukları çiz, karşılaştır; büyük olanı işaretle.»","isaret":"Onlukları çizerek basamak değerine göre büyüğü bulur."}},{"order":19,"kazanim":"Zihinsel Sayı Doğrusu (100’e kadar)","gunluk":{"t":"Sokakta konumla","adim":["Kapı numaralarında «50 burada, 100 sokağın sonunda» deyin.","«70 numara nereye düşer, ortayı geçti mi?» diye sorun.","Sayıyı 0-100 yolunda orantılı düşündürün."],"soyle":"«Elli ortada, yüz sonda; yetmiş nereye düşer?»","isaret":"Bir sayının 0-100 aralığında yerini orantılı kestirir."},"oyun":{"t":"Banda yerleştir","adim":["Yere 0 ve 100 yazılı uzun bir bant gerin.","«65'i koy» deyince çocuk ortanın biraz sağına atlasın.","Farklı sayılarla yineleyin."],"soyle":"«Altmış beşi bantta nereye koyarsın? Ortanın neresine?»","isaret":"0-100 bandında sayıyı orantılı yere koyar."},"yaprak":{"t":"Çeyrek-orta-son","adim":["0-100 işaretli boş bir çizgi çizin.","Çocuk 25'i çeyreğe, 60'ı ortanın sağına, 90'ı sona yakın koysun.","Yerleştirmeleri birlikte değerlendirin."],"soyle":"«Yirmi beş çeyrekte, doksan sona yakın; orantılı işaretle.»","isaret":"0-100 doğrusunda birkaç sayıyı orantılı konumlandırır."}},{"order":20,"kazanim":"Göz Atarak Çokluk Tahmin Eden","gunluk":{"t":"Bir köşeyi say","adim":["Kalabalık bir gruba bakın (kuş, insan, taş).","«Bir köşeyi sayalım, gerisini ona göre tahmin edelim» deyin.","«Yaklaşık kaç eder?» diye birlikte konuşun."],"soyle":"«Şu köşede bu kadar var; hepsi yaklaşık kaç eder?»","isaret":"Küçük bir öbekten yola çıkıp bütünü makul tahmin eder."},"oyun":{"t":"Öbekle tahmin","adim":["Bir kâseye bol fasulye koyun.","Küçük bir grubu sayıp «gerisi de bunun birkaç katı» deyin.","Toplamı tahmin edip sonra sayarak doğrulayın."],"soyle":"«Şu kadarlık öbekten kaç tane var sence? Sayıp bakalım.»","isaret":"Bir öbeği çıpa alıp büyük kümeyi tarayarak tahmin eder."},"yaprak":{"t":"Sayfayı tahmin et","adim":["Kalabalık bir nokta öbeği çizin.","Çocuk bir köşedeki 10'u saysın.","Sayfada yaklaşık kaç olduğunu tahmin edip yazsın."],"soyle":"«Köşedeki onu say; sayfada yaklaşık kaç var dersin?»","isaret":"Bilinen bir öbekten bütünü tarayarak tahmin eder."}},{"order":21,"kazanim":"Zihinsel Sayı Doğrusu (1000’e kadar)","gunluk":{"t":"Koridorda binlik","adim":["Uzun bir koridorda «0 burada, 1000 öteki uçta» deyin.","«500 tam orta; 750 nereye düşer?» diye konuşun.","Büyük ölçekte orantılı düşünmeyi destekleyin."],"soyle":"«Beş yüz tam ortada; yedi yüz elli nereye düşer?»","isaret":"Bir sayının 0-1000 aralığındaki yerini orantılı kestirir."},"oyun":{"t":"İpe mandalla","adim":["Bir ipin uçlarını 0 ve 1000 yapın.","«600» kartını çekince çocuk yaklaşık yere mandal taksın.","Farklı sayılarla yineleyin."],"soyle":"«Altı yüzü ipte nereye takarsın? Ortanın neresine?»","isaret":"0-1000 ipinde sayıyı orantılı yere yerleştirir."},"yaprak":{"t":"Binliği böl","adim":["0-1000 işaretli boş bir çizgi çizin.","Çocuk 250, 500 ve 800'ü orantılı yerlerine koysun.","«Hangisi yarıyı geçti?» diye sorun."],"soyle":"«İki yüz elli, beş yüz, sekiz yüz; orantılı işaretle.»","isaret":"0-1000 doğrusunda yüzlükleri orantılı yerleştirir."}},{"order":22,"kazanim":"Bir Bölümünü Sayıp Tahmin Eden","gunluk":{"t":"Ölçütle tahmin","adim":["Markette «bir koli 24 su» olduğunu söyleyin.","«Yaklaşık 100 yapmak için kaç koli gerekir?» diye sorun.","Bilinen bir ölçütten yola çıkıp tahmin ettirin."],"soyle":"«Bir koli yirmi dört; yüze ulaşmak için kaç koli lazım?»","isaret":"Bilinen bir ölçüt noktasına dayanarak tahmin yapar."},"oyun":{"t":"Bardak ölçüsü","adim":["Bir bardağı «10 fındık ölçüsü» olarak belirleyin.","«Kâsedeki fındık kaç bardak eder?» diye tahmin ettirin.","Bardakla ölçüp gerçeği görün."],"soyle":"«Bir bardak on fındık; kâsedeki kaç bardak eder?»","isaret":"Bir ölçütü çıpa alıp büyük kümeyi tahmin eder."},"yaprak":{"t":"Örnek öbekle","adim":["Sayfada 10'luk bir öbeği örnek gösterin.","Çocuk başka bir kalabalığı «bu öbekten kaç tane var?» diye tahmin etsin.","Ölçütle kıyaslamayı pekiştirin."],"soyle":"«Şu on'luk örneğe bak; bu kalabalık ondan kaç tane?»","isaret":"Verili bir ölçüt öbeğine göre kalabalığı tahmin eder."}},{"order":23,"kazanim":"Öbeklere Ayırıp Tahmin Eden","gunluk":{"t":"Parçaları topla","adim":["Sofradaki parçaları sayın: 4 çatal, 4 bardak, 2 tabak.","«Hepsi yaklaşık kaç parça eder?» diye sorun.","Sayıları bileşenlere ayırıp toplayarak tahmin ettirin."],"soyle":"«Dört çatal, dört bardak, iki tabak; hepsi kaç eder?»","isaret":"Bütünü parçalara ayırıp toplayarak tahmin eder."},"oyun":{"t":"Kutuları birleştir","adim":["Farklı kutulardaki oyuncakları ayrı ayrı tahmin edin (on, beş, on).","Tahminleri toplam için birleştirin.","Sonra sayarak doğrulayın."],"soyle":"«Bunda on, şunda beş; hepsini toplarsak yaklaşık kaç?»","isaret":"Parça tahminlerini toplayarak bütünü kestirir."},"yaprak":{"t":"On artı on","adim":["Sayfada üç ayrı öbek çizin.","Çocuk her öbeği ayrı tahmin etsin.","«On artı on artı beş» diye toplayıp bütünün tahminini yazsın."],"soyle":"«Her öbeği ayrı tahmin et, sonra topla; hepsi kaç?»","isaret":"Öbekleri ayrı tahmin edip toplayarak bütünü bulur."}}]},"add":{"code":"Y04","name":"Toplama ve Çıkarma","strand":"islemler","levels":[{"order":1,"kazanim":"Aritmetik Duyarlılığı: Temeller","gunluk":{"t":"Çoğaldı azaldı hissi","adim":["Çocuğun gözü önünde tabağa birkaç üzüm koyun.","Bir avuç daha ekleyip 'Bak, daha çok oldu!' deyin.","Sonra birkaçını alıp 'Şimdi azaldı' deyin; sayı söylemeyin."],"soyle":"«Ekledik, çoğaldı; aldık, azaldı.»","isaret":"Çocuk eklenince 'çok', alınınca 'az' olduğunu fark eder."},"oyun":{"t":"Hangisinde çok var","adim":["İki kaseye kraker doldurun: birine bol, diğerine bir-iki tane.","'Hangisinde daha çok var?' diye sorun.","Çocuk çok olanı gösterince kutlayın; her turda kaseleri değiştirin."],"soyle":"«Bu kasede daha çok kraker var, görüyor musun?»","isaret":"Çocuk belirgin farkta çok olan kaseyi gösterir."},"yaprak":{"t":"Çok olan eli göster","adim":["İki avucunuzu açın.","Birine bir tutam fasulye, diğerine tek tane koyun.","Çocuk 'çok olan eli' işaret etsin."],"soyle":"«Hangi elimde daha çok fasulye var?»","isaret":"Çocuk daha kalabalık eli sezgiyle seçer."}},{"order":2,"kazanim":"Sözsüz Toplayıp Çıkaran","gunluk":{"t":"Bir tane gelmiş gibi","adim":["Çocuğun önündeki 2 zeytine birlikte bakın.","Bir örtüyle kapatıp gizlice 1 tane daha ekleyin.","Örtüyü kaldırınca 'Bir tane gelmiş gibi mi?' diye şaşkınlığını paylaşın."],"soyle":"«İki taneydi, şimdi sanki bir tane daha var.»","isaret":"Çocuk küçük bir eklemenin olduğunu sezer."},"oyun":{"t":"Bir şey değişti mi","adim":["Üç oyuncağı masaya dizin, çocuk baksın.","Gözünü kapatınca 1'ini saklayın ya da 1 ekleyin.","Gözünü açınca 'Arttı mı, azaldı mı?' diye merakla sorun."],"soyle":"«Bak bakalım, bir şey değişti mi? Arttı mı, azaldı mı?»","isaret":"Çocuk 3'e kadar miktarda artma/azalmayı sezer."},"yaprak":{"t":"Bardağın altında","adim":["Bir bardağın altına 2 düğme saklayın, çocuk önce görsün.","Siz gizlice 1 düğme daha ekleyin.","Bardağı kaldırınca 'Daha mı çok şimdi?' deyin."],"soyle":"«Az önce daha azdı, şimdi biri daha geldi.»","isaret":"Çocuk 3'ü geçmeyen miktarda eklenmeyi fark eder."}},{"order":3,"kazanim":"Küçük Sayılarla Toplayıp Çıkaran","gunluk":{"t":"Bir daha alsan kaç olur","adim":["Çocuğun eline 2 üzüm verin.","'Bir tane daha alırsan kaç olur?' diye sorun.","Birlikte 'üç!' deyin."],"soyle":"«İki üzümün vardı, bir daha aldın; üç oldu.»","isaret":"Çocuk çok küçük bir toplamayı sözel olarak söyler."},"oyun":{"t":"Zar at bir ekle","adim":["3'e kadar yüzleri olan bir zar (ya da 1-2-3 fişler) atın.","Çıkan kadar fındık alın.","Bir tane daha ekleyip 'Şimdi kaç oldu?' diye birlikte sayın."],"soyle":"«İki çıktı, bir ekledik; şimdi kaç var?»","isaret":"Çocuk 1-2-3 ile minik toplamaları söyler."},"yaprak":{"t":"İki nokta bir nokta","adim":["Küçük bir kâğıda iki nokta çizin.","Yanına bir nokta daha ekleyin.","Çocukla 'iki ve bir, üç' diye söyleyin."],"soyle":"«İki ve bir daha; hep beraber üç eder.»","isaret":"Çocuk 1+1, 2+1 gibi minik toplamları parmakla pekiştirir."}},{"order":4,"kazanim":"Sonucu Bulan","gunluk":{"t":"Hepsini sayıp bul","adim":["Sofraya çatal dizerken '3 çatal vardı, 2 tane daha koyduk' deyin.","'Hadi hepsini sayalım' deyin.","Çocuk baştan sona dokunup '1, 2, 3, 4, 5' saysın."],"soyle":"«Üç vardı, iki ekledik; hepsini sayalım: beş!»","isaret":"Çocuk iki grubu birleştirip baştan sayarak toplamı bulur."},"oyun":{"t":"İki avuç dök","adim":["İki avucunuza fasulye saklayın (örn. 4 ve 3).","İkisini birden masaya dökün.","Çocuk hepsini tek tek sayarak toplamı bulsun."],"soyle":"«İki elimi de döktüm; hepsini say, kaç tane?»","isaret":"Çocuk dökülen tüm nesneleri sayıp toplamı söyler."},"yaprak":{"t":"İki kutuyu birleştir","adim":["Kâğıda iki kutu çizip birine 4, birine 3 fasulye koyun.","Çocuk hepsini bir araya itsin.","Baştan sayarak 'yedi' desin."],"soyle":"«İki kutuyu birleştir, baştan say; toplam kaç?»","isaret":"Çocuk gerçek nesnelerle sonucu sayarak bulur."}},{"order":5,"kazanim":"İstenen Sayıya Tamamlayan","gunluk":{"t":"Onu doldur","adim":["10'luk yumurta kartonunun yarısına 6 ceviz koyun.","'Onu doldurmak için kaç tane daha lazım?' diye sorun.","Çocuk boş gözleri sayarak tamamlasın."],"soyle":"«Altı var; ona tamamlamak için kaç tane daha lazım?»","isaret":"Çocuk hedef sayıya kaç eksik kaldığını bulur."},"oyun":{"t":"Beşe tamamla","adim":["Bir kâğıda 5 daire çizip üzerine düğme dizin.","Bazı daireleri boş bırakın.","'Beşe tamamlamak için kaç düğme koymalıyız?' deyip yerleştirin."],"soyle":"«Üç düğme koyduk; beşe tamamlamak için kaç kaldı?»","isaret":"Çocuk 5'e (sonra 10'a) tamamlayan eksik sayıyı bulur."},"yaprak":{"t":"Parmakla beş yap","adim":["Çocuğun elinde 3 parmak açık olsun.","'Beş yapmak için kaç parmak daha kaldırmalısın?' diye sorun.","Hedef sayıyı (5, sonra 10) parmakla tekrarlayın."],"soyle":"«Üç parmağın açık; beş için kaç parmak daha?»","isaret":"Çocuk verilen sayıya tamamlayan eksiği söyler."}},{"order":6,"kazanim":"Eksik Olanı Bulan","gunluk":{"t":"Kaç tane ekledim","adim":["Bir tabağa 5 kraker koyun, çocuk baksın.","Mendille kapatıp birkaçını alın ya da ekleyin.","'Önce 5 vardı, şimdi 8 oldu — kaç tane EKLEDİM?' diye sorun."],"soyle":"«Beşti, sekiz oldu; aradaki değişim kaç?»","isaret":"Çocuk başlangıç ve sonuçtan değişim miktarını bulur."},"oyun":{"t":"Kutuya kaç attım","adim":["Bir kutuya 4 düğme koyup gösterin, kapağı kapatın.","Gizlice birkaç düğme daha atın.","Açıp toplamı sayın; 'Kaç tane attım?' diye tahmin ettirin."],"soyle":"«Dört vardı, şimdi yedi; demek ki kaç attım?»","isaret":"Çocuk bilinmeyen eklenen miktarı bulur."},"yaprak":{"t":"Üçten yediye kaç adım","adim":["Kâğıda '3 → 7' yazıp arasına bir kutu çizin.","'Üçten yediye gitmek için kaç adım attık?' diye sorun.","Çocuk fasulye ekleyerek farkı bulsun."],"soyle":"«Üçten yediye kaç tane eklemen gerekti?»","isaret":"Çocuk küçük, garantili değişimi (farkı) bulur."}},{"order":7,"kazanim":"Sayma Stratejileriyle Çözen","gunluk":{"t":"Büyükten üzerine say","adim":["Sepete 6 elma koyduğunuzu söyleyin.","'6'dan başlayıp 2 tane daha sayalım: yedi, sekiz' deyin.","Çıkarmada '8 vardı, geriye sayalım: yedi, altı' deyin."],"soyle":"«Baştan değil, altıdan devam et: yedi, sekiz.»","isaret":"Çocuk baştan saymadan büyük sayıdan üzerine sayar."},"oyun":{"t":"Zardan ileri say","adim":["Bir zar atın (örn. 6), 'altıdan başla' deyin.","İkinci küçük zarı atıp o kadar ileri sayın.","Geri sayma için avuçtan teker teker alıp 'sekiz... yedi... altı' deyin."],"soyle":"«Altı çıktı; şimdi üç ileri say: yedi, sekiz, dokuz.»","isaret":"Çocuk verilen sayıdan ileri/geri sayarak işlem yapar."},"yaprak":{"t":"Sayı şeridinde zıpla","adim":["Kâğıda 1-10 sayı şeridi çizin.","'7'nin üstüne parmağını koy, 3 zıpla' deyin.","Sonra '9'dan 2 geri zıpla' deyin."],"soyle":"«Yedinin üstünden üç ileri zıpla, nereye geldin?»","isaret":"Çocuk baştan saymadan verilen sayıdan devam eder."}},{"order":8,"kazanim":"Parça-Bütün İlişkisi Kuran","gunluk":{"t":"Yedi içinde parçalar","adim":["Mutfakta 7 üzümü tabakta ikiye bölün.","'Bunu 4 ve 3 diye ayırabiliriz, ya da 5 ve 2' deyin.","Çocuk farklı gruplara ayırarak aynı bütünün parçalarını keşfetsin."],"soyle":"«Yedi; dört ve üç de olur, beş ve iki de.»","isaret":"Çocuk aynı sayıyı farklı iki parçaya ayırır."},"oyun":{"t":"Bez ile ikiye böl","adim":["8 düğmeyi bir bez parçasıyla ikiye bölün.","Çocuk 'kaç burada, kaç orada?' diye iki parçayı söylesin (6 ve 2, 5 ve 3...).","Toplama yaparken '6+3'ü 6 ve 3'e ayırıp birleştirsin."],"soyle":"«Sekizi böldük; bir yanda kaç, öbür yanda kaç?»","isaret":"Çocuk bütünü parçalara ayırıp ikisini birden söyler."},"yaprak":{"t":"Parça-bütün kutusu","adim":["Kâğıda bir 'bütün' kutusu, altında iki 'parça' kutusu çizin.","Üste 7 fasulye koyun.","Çocuk bunları iki parçaya dağıtıp her dağılımı kutulara koysun."],"soyle":"«Yediyi iki parçaya böl; hangi ikili olur?»","isaret":"Çocuk sayıyı parçalayarak parça-bütün ilişkisini gösterir."}},{"order":9,"kazanim":"Parçayı ve Bütünü Birlikte Düşünen","gunluk":{"t":"İçinde beş saklı","adim":["Tabakta 8 zeytin varken 'İçinde 5 saklı, kalanı kaç?' diye sorun.","Çocuk 5'i bir kenara çeksin.","Kalan 3'ü görüp söylesin."],"soyle":"«Sekizin içinde beş var; geriye kaç kaldı?»","isaret":"Çocuk büyük sayının içindeki tanıdık küçük sayıyı görür."},"oyun":{"t":"Beşi gör say","adim":["9 düğmeyi gösterip 'İçinde 5 görebiliyor musun?' deyin.","Çocuk 5'i ayırıp '5 ve 4' desin.","6+3'ü hesaplarken 'içinde 5 var, üstüne say' diye kullansın."],"soyle":"«Dokuz; beşi ayır, üstünde kaç kaldı?»","isaret":"Çocuk gömülü 5'i kullanarak işlemi kolaylaştırır."},"yaprak":{"t":"Beş ve biraz daha","adim":["Kâğıda 10'luk bir nokta sırası çizin, 5'ten sonra küçük boşluk bırakın.","'8 noktada 5'i ve fazlasını göster' deyin.","Çocuk her sayıyı '5 ve biraz daha' olarak görsün."],"soyle":"«Sekiz, beş ve üç daha demek.»","isaret":"Çocuk sayıları '5 ve fazlası' ilişkisiyle çözümler."}},{"order":10,"kazanim":"Bildiklerinden Türeten","gunluk":{"t":"Bildiğinden yenisini bul","adim":["Çocuk '5+5=10' biliyorsa, '5+6 kaç eder?' diye sorun.","'On'un bir fazlası, yani on bir!' diye türetin.","'10-1' biliyorsa '10-2'yi oradan çıkarın."],"soyle":"«Beş artı beş on; bir fazlası on bir.»","isaret":"Çocuk bilinen bir olgudan komşu işlemi türetir."},"oyun":{"t":"Domino komşusu","adim":["Domino taşlarıyla oynayın.","Çocuk 6+6'yı (çift) biliyorsa yanına 6+7 taşını koyun.","'Çiftin bir fazlası' deyip birlikte üretin."],"soyle":"«Altı artı altı on iki; bir fazlası on üç.»","isaret":"Çocuk bilinen çiftten komşu toplamı türetir."},"yaprak":{"t":"Komşu işlem zinciri","adim":["Kâğıda solda '4+4=8' yazın, sağda '4+5=?' bırakın.","'Sadece bir fazla, kaç olur?' diye sorun.","Bilinen işlemlerin yanına komşularını koyup zincir kurun."],"soyle":"«Dört artı dört sekiz; bir fazlası dokuz.»","isaret":"Çocuk bilinenden türeterek sonucu bulur."}},{"order":11,"kazanim":"Her Tür Problemi Çözen","gunluk":{"t":"Markette iki adım","adim":["'Elimde 10 lira var' deyin.","'3 liralık ekmek ve 4 liralık süt alırsak ne kadar harcarız?' diye sorun.","'Kaç lira kalır?' diye ikinci adımı birlikte çözün."],"soyle":"«Önce harcadığımızı toplayalım, sonra kalanı bulalım.»","isaret":"Çocuk iki adımlı bir durumu sırayla çözer."},"oyun":{"t":"Evde market","adim":["Nesnelere küçük fiyatlar yazıp çocuğa kâğıt paralar verin.","'2 oyuncak al, ne kadar tuttu?' diye sorun.","'Paran yeter mi, üstü kaç?' diye adımları oyunlaştırın."],"soyle":"«İkisinin fiyatını topla, sonra üstünü hesapla.»","isaret":"Çocuk birden çok adımı esnek bir yolla çözer."},"yaprak":{"t":"Hikâye problemi","adim":["Kâğıda kısa bir hikâye yazın: 'Sepette 6 elma vardı, 2 yedik, sonra 5 elma daha koyduk.'","'Şimdi kaç?' diye sorun.","Çocuk hangi adımı önce yapacağını seçip çözsün."],"soyle":"«Önce ne oldu, sonra ne oldu? Adım adım gidelim.»","isaret":"Çocuk çok adımlı problemi doğru sırayla çözer."}},{"order":12,"kazanim":"Çok Basamaklı Toplayıp Çıkaran","gunluk":{"t":"Onlukları ayrı topla","adim":["Fişe bakarak '23 lira ile 14 lirayı toplasak kaç eder?' diye sorun.","Önce onlukları (20+10), sonra birlikleri (3+4) toplayın.","'35 gram un vardı, 20 ekledik' gibi durumları konuşun."],"soyle":"«Önce onlukları topla: yirmi artı on; sonra birlikleri.»","isaret":"Çocuk iki basamaklı toplamayı onluk-birlik ayırarak yapar."},"oyun":{"t":"Onluk grupla","adim":["İki zar atıp onluk-birlik sayı kurun (örn. 4 ve 2 → 42).","İkinci sayıyı da üretip toplayın.","Bozuk para ya da çöplerle '10 olunca bir onluk yapıp tarafa koy' deyin."],"soyle":"«On tane oldu; bunları bir onluk yapıp ayır.»","isaret":"Çocuk eldeyi (onluk geçişini) somut olarak gösterir."},"yaprak":{"t":"İki sütunlu toplama","adim":["Kâğıda '34 + 25' yazıp onluklar ve birlikler için iki sütun çizin.","Çocuk önce birlikleri (4+5), sonra onlukları (30+20) toplasın.","Sonra elde gerektiren '28+15' gibi bir örnekle ilerleyin."],"soyle":"«Birlikleri topla, onlukları topla, sonra birleştir.»","isaret":"Çocuk çok basamaklı işlemi basamaklara ayırıp yürütür."}}]},"compose":{"code":"Y05","name":"Sayı Birleştirme (Parça-Bütün)","strand":"islemler","levels":[{"order":1,"kazanim":"Parçalarla Oynayan: Temeller","gunluk":{"t":"Ayır, sonra birleştir","adim":["Banyoda/oyunda bir kova oyuncağı birlikte ikinci kaba boşaltın.","Sonra 'hepsi yine bir arada!' diyerek tek kaba toplayın.","Çamaşır toplarken çorapları iki sepete ayırıp sonra birleştirin."],"soyle":"«İkiye ayırdık... şimdi hepsi yine bir arada!»","isaret":"Çocuk bir bütünü ayırıp tekrar birleştirme hareketini keyifle yapıyor."},"oyun":{"t":"Dök-topla oyunu","adim":["İki kâse ve bir avuç fasulye/düğme/kapak hazırlayın.","Fasulyeleri bir kâseden ötekine dökün, karıştırın.","Sonra hepsini tek kâsede toplayıp 'hepsi geri geldi' deyin."],"soyle":"«Döktük, karıştırdık... hepsi yine tek kâsede!»","isaret":"Dökme-toplama oyununu kendiliğinden tekrarlamaya başlıyor."},"yaprak":{"t":"İki tabak, tek tabak","adim":["Sofrada iki tabak verin.","Çocuk üzümleri/krakerleri bir tabaktan diğerine taşısın.","Sonra hepsini ortadaki tek tabakta toplasın."],"soyle":"«Bu tabaktan şuna taşı... şimdi hepsi ortada!»","isaret":"Parçaları ayırıp tek kümede toplama hareketini bol bol yaşıyor."}},{"order":2,"kazanim":"Parçaları Birleştiren","gunluk":{"t":"İki parça tek bütün","adim":["Bir elinize 2 fındık, çocuğun eline 1 fındık koyun.","'Hepsini bir araya koyalım, kaç oldu?' deyin.","Meyve verirken 'sana 2, bir de 1 daha, hepsi senin' diye birleştirin."],"soyle":"«İki ve bir; bir araya koyunca hepsi üç oldu.»","isaret":"İki ayrı küçük parçayı birleştirip tek bir sayı olarak söylüyor."},"oyun":{"t":"Avuçları birleştir","adim":["İki renk düğme (ya da iki tür kuruyemiş) ve küçük bir tabak alın.","Sizin avucunuzdaki 2 ile çocuğun avucundaki 1'i tabakta birleştirin.","'Şimdi hepsi bir arada' deyip 2 ve 2 yaparak yineleyin."],"soyle":"«Benim ikim, senin birin; tabakta üç oldu!»","isaret":"İki avucu birleştirince oluşan bütünü tek küme görüyor."},"yaprak":{"t":"İki daireden bir avuç","adim":["Bir kâğıda iki küçük daire çizin.","Çocuk birine 2 çakıl, ötekine 1 çakıl koysun.","İkisini ortadaki bir avuçta toplayıp 'hepsi kaç?' desin."],"soyle":"«İki daire, sonra hepsini avucumuzda topladık: kaç?»","isaret":"İki parçayı tek küme yapıp toplamı söyleyebiliyor."}},{"order":3,"kazanim":"Parça-Bütünü Kabaca Kavrayan","gunluk":{"t":"Saklı parça da var","adim":["4 üzümü dizip 2'sini elinizle kapatın.","'İki görünüyor, peki avucumun altında kaç saklı? Hepsi kaç?' deyin.","Oyuncak toplarken kutuya 2 araba koyup 'içeride 2, dışarıda 2, hepsi 4' deyin."],"soyle":"«İki görünüyor ama elimin altında da iki var; hepsi dört!»","isaret":"Görünmeyen parçanın da bütüne ait olduğunu söylüyor."},"oyun":{"t":"Sakladım-buldum","adim":["4 küçük nesne ve bir bardak/kart hazırlayın.","4 düğmeyi gösterip birkaçını bardakla örtün.","Çocuk 'kaç saklı?' sorusunu düşünüp söylesin, sonra kaldırıp doğrulayın."],"soyle":"«Dört vardı, ikisini örttüm; altında kaç kaldı?»","isaret":"Örtülen sayıyı, bütünü hatırlayarak bulabiliyor."},"yaprak":{"t":"Kaç görünüyor, kaç saklı","adim":["Bir kâğıda 4 nokta çizin.","2 noktanın üstüne küçük bir kâğıt yapıştırın.","Çocuk 'kaç görünüyor, kaç saklı, hepsi kaç?' diye söylesin."],"soyle":"«İkisi görünüyor, ikisi kapalı; ama hepsi yine dört.»","isaret":"Saklı parçayı da sayıp bütünü doğru söylüyor."}},{"order":4,"kazanim":"Sayı Kuran (önce 4, sonra 5)","gunluk":{"t":"Başka türlü, yine dört","adim":["4 zeytini iki tabağa böldürün (önce 3 ve 1, sonra 2 ve 2).","Her seferinde 'yine dört, sadece başka türlü dağıttık' deyin.","5 çorabı eşleştirirken '4 ile 1, ya da 3 ile 2 — hepsi yine 5' deyin."],"soyle":"«Üç ve bir, ya da iki ve iki; ikisi de dört!»","isaret":"Aynı sayıyı farklı parçalara ayırıp toplamın değişmediğini görüyor."},"oyun":{"t":"Kaç yolla ayrılır?","adim":["4-5 düğme ve bölmeli bir tabak (ya da iki kapak) alın.","Çocuk 4 düğmeyi iki bölmeye her seferinde başka türlü dağıtsın (3+1, 2+2).","'Hepsi hâlâ dört mü?' diye sorun; sağlamlaşınca 5 ile yineleyin."],"soyle":"«Bir daha böl, başka türlü; toplam yine dört mü?»","isaret":"Dördü/beşi birden çok ikiliyle ayırıp her seferinde aynı bütünü buluyor."},"yaprak":{"t":"İkilileri listele","adim":["İki kutu çizili bir kâğıda 4 çakıl dağıttırın.","Bulduğu her ikiliyi (3 ve 1, 2 ve 2) yan yana söyletin.","Sonra 5 ile tüm ikilileri (4+1, 3+2) liste gibi bulun."],"soyle":"«Dört kaç türlü ayrılır? Üç-bir, iki-iki...»","isaret":"Yeniden saymadan 'yine aynı' diyerek farklı ayrılışları buluyor."}},{"order":5,"kazanim":"Sayı Kuran (7’ye kadar)","gunluk":{"t":"Eksik parçayı bul","adim":["7 cevizi 5 ve 2 diye gösterip 'beş ve iki, yedi' deyin.","'Elimde 3 var, yedi olması için kaç lazım?' diye sorun.","Sofra kurarken '7 çatal lazım, 4'ünü koydum, kaç kaldı?' deyin."],"soyle":"«Yedi için elimde üç var; kaç tane daha lazım?»","isaret":"Bir parçayı görüp eksik parçayı saymadan söylüyor."},"oyun":{"t":"Kaçı saklı?","adim":["7 düğme, iki renk ve bir kapatma kartı alın.","Düğmeleri 5+2 dizip bir kısmını örtün.","Çocuk '3 gördüm, kaçı saklı?' diye saymadan 'dört' desin; parçaları değiştirin (6 ve 1, 4 ve 3)."],"soyle":"«Üç gördün; yedi olması için kaçı saklı?»","isaret":"Görünen parçadan yola çıkıp eksik parçayı saymadan buluyor."},"yaprak":{"t":"7'nin iki rengi","adim":["Kâğıda 7 nokta çizin.","Çocuk ikisini bir renge, kalanı başka renge boyasın.","'5 ve 2 yedi', sonra başka türlü '4 ve 3 yedi' diye yazsın/söylesin."],"soyle":"«Beş ve iki yedi; peki dört ve üç de yedi mi?»","isaret":"7'yi farklı ikililere ayırıp her birinin yine 7 ettiğini söylüyor."}},{"order":6,"kazanim":"Sayı Kuran (10’a kadar)","gunluk":{"t":"Ona kaç lazım?","adim":["10'luk yumurta kartonunun içine 7 ceviz koyup 'kaç dolu, kaç boş — ona kaç lazım?' deyin.","Meyve suyu doldururken '7 bardak doldu, 10 olması için kaç kaldı?' deyin.","Tümleyeni saymadan söylemesini bekleyin."],"soyle":"«Yedi var; ona tamamlamak için kaç lazım?»","isaret":"Verilen sayıya 10'un tümleyenini saymadan söylüyor."},"oyun":{"t":"10 dostları","adim":["10 gözlü yumurta kartonu ve düğmeler hazırlayın.","Kartona bir miktar (ör. 6) düğme koyun; çocuk boş gözleri görüp 'dört lazım' desin ve doldursun.","9+1, 8+2, 7+3, 6+4, 5+5 dostlarını sırayla bulup söyleyin."],"soyle":"«Altı koyduk; on dostu için dört daha!»","isaret":"10'a tümleyen ikilileri akıcı, saymadan söyleyebiliyor."},"yaprak":{"t":"Dolu-boş şeridi","adim":["10 kutulu bir şerit çizin.","Çocuk bir kısmını boyayıp 'kaç dolu, kaç boş' yazsın.","Her satırda bir '10 dostu' çıkarsın (7 ve 3, 8 ve 2)."],"soyle":"«Yedi dolu, üç boş; yedi ve üç on eder!»","isaret":"Bir parçaya 10'un tümleyenini saymadan söyleyip yazıyor."}},{"order":7,"kazanim":"Sayı Kuran (20 ve ötesi); Onluk ve Birliklerle Sayı Kuran","gunluk":{"t":"On ve birkaç daha · Bir onluk, birkaç birlik","adim":["14 fındığı '10 ve 4' diye karton dolusu + yanına 4 koyarak gösterip 'on dört' deyin.","Markette '10 elma torbada, 4 daha — kaç oldu?' diye sorun.","'17 var, yirmi olması için kaç kalır?' diye onluğu temel alın.","17 düğmeyi önce dağınık koyup 'saymak yerine onar demet yapalım' deyin.","Bir demet (10) ve yanında 7 tek bırakıp 'bir onluk, yedi birlik — on yedi' dedirtin."],"soyle":"«On ve dört: on dört. Onluğu bir parça gibi kullanıyoruz.»","isaret":"Onluğu tek bir parça sayıp üstüne birlik ekleyerek 20'ye dek bileştiriyor."},"oyun":{"t":"Demetle oyunu · Önce 10'a tamamla","adim":["10'arlı demet yapılabilen çubuk-makarna/düğme ve 11-19 sayı kartları alın.","Çocuk bir kart çeksin (ör. 13), bir onluk demet + 3 tek kurup 'bir onluk, üç birlik' desin.","Bir tek ekleyip 'şimdi kaç?' diye sorun.","Dolu bir 10'luk karton + ayrı düğmeler (20'ye dek) alın."],"soyle":"«On üç: bir demet, üç tek. Bir tek eklersek?»","isaret":"Kart sayısını bir onluk demet ve doğru sayıda birlikle kuruyor."},"yaprak":{"t":"Çubuk ve kareler · Onluk-temelli ayır","adim":["Bir uzun çubuk (onluk) + 7 küçük kare (birlik) çizdirin.","'1 onluk + 7 birlik = 17' yazdırın.","Yazılı 17'yi gösterip 1'in ve 7'nin ne anlattığını söyletin.","Bir onluk demet + birkaç tek nesne çizdirip '10 ve 4 — on dört' yazdırın."],"soyle":"«Baştaki 1 bir onluk demek, 7 ise yedi birlik.»","isaret":"11-19'u onluk+birlik kurup yazılı basamakları açıklayabiliyor."}},{"order":8,"kazanim":"Bildiklerinden Türeten (parça-bütün)","gunluk":{"t":"Bir fazla, kaç eder?","adim":["'6+4=10 biliyoruz; 6+5 bir fazla, kaç eder?' diye sorup 'on bir' dedirtin.","Sofrada 'dün 5 ve 5 on yapmıştık, bugün 5 ve 6 — bir fazla, demek?' deyin.","Sonucu değil, 'neden' yolunu söyletin."],"soyle":"«Altı-dört on'du; altı-beş bir fazla, demek on bir.»","isaret":"Bilinen bir toplamadan komşusunu saymadan türetip gerekçe veriyor."},"oyun":{"t":"Bir fazla / bir az","adim":["Düğmeler ve birkaç 'bildiğimiz' kart (6+4=10, 5+5=10) hazırlayın.","Bilinen bir toplamı kurun; bir düğme ekleyip 'şimdi bir fazla, kaç?' deyin.","Bir düğme alıp 'bir az, kaç?' diye saymadan buldurun; nedenini söyletin."],"soyle":"«On'du; bir düğme ekledim, şimdi bir fazla: kaç?»","isaret":"Bilinen olgudan bir fazla/bir az olanı saymadan buluyor."},"yaprak":{"t":"Komşu olguları çıkar","adim":["Bir kâğıda bildiği bir olguyu (7+3=10) yazın.","Altına komşularını (7+4=?, 7+2=?) çıkarın.","Çocuk 'bir fazla olduğu için 11' diye yazıp gerekçe versin."],"soyle":"«Yedi-üç on'sa, yedi-dört bir fazla: on bir.»","isaret":"Bilinenden türetip sonucu gerekçeli yazabiliyor."}},{"order":9,"kazanim":"Her Tür Problemi Çözen (parça-bütün)","gunluk":{"t":"Başka türlü nasıl bulurdun?","adim":["'Kutuda 8 kalem vardı, 5 ekledim, sonra 4 verdim — şimdi kaç?' gibi hikâye sorun.","Çözünce 'başka türlü nasıl bulurdun?' diye ikinci yolu konuşturun.","İkinci yol önce 10'a tamamlama ya da geriye sayma olabilir."],"soyle":"«Buldun; peki aynı sonuca başka hangi yoldan giderdin?»","isaret":"Çok adımlı problemi çözüp ikinci bir yolu da anlatabiliyor."},"oyun":{"t":"Mağazacılık","adim":["İki kutu, düğmeler ve sözlü kısa problemler hazırlayın.","Bir kutuda 7, ötekinde 6 'para' olsun: 'toplam kaç?'","'3 daha aldık, 4 harcadık' diye olayı büyütün; çocuk kendi yoluyla izleyip anlatsın."],"soyle":"«Yedi ve altı kaç? Şimdi üç aldık, dört harcadık...»","isaret":"Olay değiştikçe bileşimi takip edip kendi yolunu açıklıyor."},"yaprak":{"t":"İki yolla çöz","adim":["Kısa bir hikâye-problemi ('6 vardı, 7 daha geldi, kaç oldu?') yazın.","Çocuk hem somut çözsün hem '6+4+3' gibi yolunu yazsın.","Sonra aynısını ikinci bir yolla çözsün."],"soyle":"«Altı ve yedi; bir de 6+4+3 yoluyla dene!»","isaret":"Doğru sonuca iki farklı strateji ile ulaşabiliyor."}},{"order":10,"kazanim":"Çok Basamaklı Toplayıp Çıkaran (parça-bütün)","gunluk":{"t":"Bir onluğu açalım","adim":["23 düğmeyi 2 onluk demet + 3 tek diye dizip 'yirmi üç' deyin.","'3 birlikten 5 vermem lazım ama yetmiyor, bir demeti açalım' deyin.","Bir onluğu 10 tek yapıp 'şimdi 1 onluk + 13 birlik, yine 23' dedirtin."],"soyle":"«Birlik yetmedi; bir demeti açtık, ama bütün yine yirmi üç.»","isaret":"Bir onluğu 10 birliğe bozup bütünün değişmediğini görüyor."},"oyun":{"t":"Onluğu boz oyunu","adim":["10'arlı demetlenebilen nesneler ve 2 basamaklı sayı kartları alın.","23 kurulsun; '7 birlik çıkaracağız ama 3 var' deyip bir demeti çözerek 10 tek elde edin.","Sonra çıkarmayı yapın; 'hangi basamağı bozduk, neden?' diye sorun."],"soyle":"«Yedi tek lazım, üç var; bir demeti bozalım da yetsin.»","isaret":"Birlik yetmeyince onluğu bozarak çok basamaklı işlemi sürdürüyor."},"yaprak":{"t":"İki türlü yaz","adim":["Kâğıda 23'ü hem '20 + 3' hem '10 + 13' diye iki türlü yazdırın.","'Bozduk ama bütün değişmedi' dedirtin.","23+18 gibi bir işlemi onlukları-birlikleri ayrı toplayıp gerekince onluğa taşıyarak çözsün."],"soyle":"«Yirmi üç: hem 20+3 hem 10+13; bütün hep aynı.»","isaret":"Onluğu esnekçe kurup bozarak çok basamaklı bileşim/ayrışım yapıyor."}}]},"multdiv":{"code":"Y06","name":"Çarpma ve Bölme","strand":"islemler","levels":[{"order":1,"kazanim":"Eşitliği Gözetmeden Paylaştıran: Temeller","gunluk":{"t":"Herkese eşit olsun","adim":["İki kardeşin önüne aynı tabağı koyun.","Kurabiyeleri 'sana bir, sana bir' diyerek paylaştırın.","Sayı söylemeden 'ikinizin de eşit oldu mu, kim daha çok aldı?' diye sorun."],"soyle":"«İkinize de adil olsun; eşit mi oldu, kim daha çok aldı?»","isaret":"Eşit olmayan dağılımı gözüyle fark eder."},"oyun":{"t":"Ayılar küsmesin","adim":["İki oyuncak ayıya kraker dağıtın.","Krakerleri sırayla önlerine koyun, 'ayılar küsmesin, eşit olsun' deyin.","Çocuk fazlalığı görüp birinden alıp diğerine vererek dengelesin."],"soyle":"«Ayılar küsmesin; ikisinin de payı eşit mi?»","isaret":"Fazla olan taraftan alıp diğerine vererek dengeler."},"yaprak":{"t":"İki tabağa dağıt","adim":["Bir kâğıda iki büyük daire (tabak) çizin.","Çocuk bir avuç fasulyeyi 'herkese aynı olsun' diye gözüyle dağıtsın.","Bakıp hangisi kalabalık görünüyor diye birlikte yorumlayın."],"soyle":"«İki tabağa eşit dağıt; hangisi daha kalabalık görünüyor?»","isaret":"İki tabağa kabaca eşit dağıtmaya çalışır, eşitsizliği fark eder."}},{"order":2,"kazanim":"Teker Teker Dağıtmaya Başlayan","gunluk":{"t":"Her tabağa birer","adim":["Akşam sofrasında çatalları dağıttırın.","'Her tabağa birer çatal koy' deyin.","Çocuk tek tek, kişi kişi dolaşarak dağıtsın."],"soyle":"«Her tabağa birer çatal; sırayla, tek tek koy.»","isaret":"Her yere birer tane düşürerek sırayla dağıtır."},"oyun":{"t":"Bardaklara birer","adim":["Üç bardağa şeker dağıtma oyunu kurun.","Avuçtaki şekerleri 'bir bu bardağa, bir şu bardağa' diyerek tek tek elden çıkarsın.","Biterse kalanı da aynı sırayla gezdirsin."],"soyle":"«Bir buraya, bir şuraya... her bardağa sırayla birer tane.»","isaret":"Nesneleri tek tek, sırayla her kaba dağıtır."},"yaprak":{"t":"Kutulara birer","adim":["Bir kâğıda üç kutu çizin.","Çocuk düğmeleri tek tek alıp her kutuya sırayla birer düğme koysun.","Dağıtırken yüksek sesle 'bir... bir... bir...' desin."],"soyle":"«Her kutuya sırayla birer düğme; 'bir, bir, bir' diye dağıt.»","isaret":"Eli kutular arasında dönerek her birine birer tane koyar."}},{"order":3,"kazanim":"Eşit Dağıtan ve Küçük Gruplar Kuran","gunluk":{"t":"Herkese ikişer","adim":["Meyve ikram ederken 'herkese 2'şer üzüm' deyin.","Çocuk her kişinin önüne ikişerli kümeler koysun.","Tek tek değil, 'iki-iki' tutamlar hâlinde dağıtmasına yönlendirin."],"soyle":"«Herkese ikişer üzüm; iki-iki tutam yaparak ver.»","isaret":"Her kişiye eşit sayıda (ikişer) küme koyar."},"oyun":{"t":"Her göze üçer","adim":["Yumurta kutusu kullanın.","Çocuk fasulyeleri her göze 3'er koyarak eşit kümeler kursun.","'Her gözde aynı sayı var mı?' diye kontrol edip bir gözü boşaltıp tekrar 3'leyin."],"soyle":"«Her göze 3'er fasulye; hepsi eşit mi, kontrol edelim.»","isaret":"Her gruba eşit sayıda nesne koyup eşitliği kontrol eder."},"yaprak":{"t":"Sepetlere ikişer","adim":["Kâğıda 4 sepet çizin.","Çocuk çıkartmaları/fasulyeleri her sepete 2'şer olacak şekilde gruplayıp yapıştırsın.","'Her sepette kaç tane, hepsi eşit mi?' diye doğrulasın."],"soyle":"«Her sepete ikişer; her sepette aynı sayı var mı?»","isaret":"Her sepete eşit sayıda nesne koyarak eşit gruplar kurar."}},{"order":4,"kazanim":"Somut Modelleyen (×/÷)","gunluk":{"t":"Kaç tabak, kaçar dilim","adim":["Mutfakta 'pizza/poğaça paylaşalım' deyin.","3 tabağa 2'şer dilim koydurun.","'Şimdi say bakalım toplam kaç dilim oldu' deyin."],"soyle":"«3 tabak, her tabakta 2 dilim; toplam kaç dilim?»","isaret":"Eşit grupları nesneyle kurar ve toplamı sayar."},"oyun":{"t":"Düğme grupları kur","adim":["Bir zar atın (örn. 3); o kadar tabak dizin.","Her tabağa aynı sayıda (örn. 4) düğme koydurun.","'Kaç tabak, her tabakta kaç tane' diye işlemi nesneyle modelleyin."],"soyle":"«3 tabak, her birinde 4 düğme; bu kaç eder?»","isaret":"'Kaç grup × kaçar nesne' düzenini nesneyle kurar."},"yaprak":{"t":"Kutulara yıldız çiz","adim":["Kâğıda 3 kutu çizdirin.","Her kutuya 4 yıldız çizmesini isteyin.","'Üç kere dörder yıldız, toplam kaç oldu' diye birlikte sayın."],"soyle":"«Üç kutu, her birinde dört yıldız; toplam kaç yıldız?»","isaret":"Eşit grupları çizip çarpmayı dizilimden okur."}},{"order":5,"kazanim":"Kişi Artarsa Payın Azalacağını Bilen","gunluk":{"t":"İkişer beşer say","adim":["Çift çorap toplarken '2, 4, 6, 8' diye ikişer sayın.","Merdiven çıkarken ya da boncuk dizerken 5'er/10'ar ritimle sayın.","'Kaç çift, kaç tane' sorusuna ritimle ulaşın."],"soyle":"«2, 4, 6, 8... ritmik sayalım; toplam kaç tane?»","isaret":"İkişer/beşer ritmik sayarak toplama ulaşır."},"oyun":{"t":"Beşer ilerle","adim":["'Her elde 5 parmak' deyip 5, 10, 15 diye ritmik sayın.","Kaç el kadar olduğunu bulun.","2'şer ilerleyen kareli bir yolda pul atlatarak çarpımı adımlayın."],"soyle":"«5, 10, 15... kaç el oldu? Ritimle sayıp bulalım.»","isaret":"Katlamalı (ritmik) sayarak çarpımı bulur, tek tek saymaz."},"yaprak":{"t":"Sayı yolunda zıpla","adim":["Bir kâğıda 0'dan 20'ye sayı yolu çizin.","Çocuk 2'şer (sonra 5'er) zıplayarak konağı işaretlesin.","'Kaç zıplamada 10'a vardım' diye ritmik sayımı çarpmaya bağlasın."],"soyle":"«İkişer zıpla; kaç zıplamada 10'a ulaştın?»","isaret":"Eşit adımlarla zıplayıp zıplama sayısını çarpımla ilişkilendirir."}},{"order":6,"kazanim":"Ritmik Sayarak Çözen (×/÷)","gunluk":{"t":"Bilinenden komşusu","adim":["Sofrada '4 biliyorsan 5'i de bil' oyunu kurun.","'4 tabağa 2'şer 8 eder, bir tabak daha gelirse 2 ekle, 10' deyin.","Bilinen miktardan komşusunu türetmeyi sesli düşünün."],"soyle":"«4 tabakta 8'di; bir tabak daha gelince 2 ekle, kaç oldu?»","isaret":"Bilinen çarpımdan bir grup ekleyip komşusunu bulur."},"oyun":{"t":"İkinin katı","adim":["Kart eşleştirme oyunu kurun.","Bildiğiniz bir çarpımı (örn. 5×2=10) kartla gösterin.","'Peki 6×2 kaç eder?' diye 2 ekleyerek cevaplatın; 'ikinin katı' ilişkisini kurdurun."],"soyle":"«5×2=10 biliyoruz; 6×2 için kaç ekleriz, kaç eder?»","isaret":"Bilinen çarpıma bir kat ekleyerek yeni çarpımı türetir."},"yaprak":{"t":"Komşu çarpımı yaz","adim":["Kâğıda iki sütun yazın: solda bildiği çarpımlar (2×3=6), sağda komşusu (2×4=?).","Çocuk soldakine bir grup eklesin.","Sağdakini türetip yazsın."],"soyle":"«2×3=6 ise 2×4 kaç? Bir grup ekleyip yaz.»","isaret":"Ezber yerine bir grup ekleyerek komşu çarpımı türetir."}},{"order":7,"kazanim":"Bildiklerinden Türeten (×/÷)","gunluk":{"t":"İki tür bölme","adim":["Market/mutfak dağıtımında iki soruyu konuşun.","'12 kurabiye 3 çocuğa, herkese kaçar?' (paylaştırma).","'12 kurabiyeyi 3'erli poşetlere koyalım, kaç poşet?' (gruplama); çocuk hangi soruyu sorduğunuzu ayırt edip nesneyle çözsün."],"soyle":"«Bu soru 'herkese kaçar' mı, 'kaç grup' mu? Ona göre çöz.»","isaret":"Paylaştırma ile gruplama sorusunu ayırt edip her birini çözer."},"oyun":{"t":"Bölmenin iki yüzü","adim":["İki kutulu bölme oyunu kurun.","Bir kart 'kaç kişiye' der (payı bul), diğeri 'kaçarlı grup' der (grup sayısını bul).","Çocuk aynı malzemeyle iki durumu da çözsün."],"soyle":"«Kart 'kaç kişiye' mi diyor, 'kaçarlı grup' mu? Buna göre dağıt.»","isaret":"Aynı sayıyı iki bölme türüyle de doğru çözer."},"yaprak":{"t":"12'yi iki yolla böl","adim":["Kâğıda aynı 12 nesneyi iki şekilde böldürün.","Önce 4 tabağa eşit dağıt (paylaştırma).","Sonra 4'erli kümelere ayır (gruplama); altına 'her tabakta kaç / kaç küme' diye iki sonucu yazsın."],"soyle":"«Aynı 12'yi önce 4 tabağa dağıt, sonra 4'erli grupla; sonuçları yaz.»","isaret":"İki bölme türünü ayrı ayrı uygulayıp iki sonucu yazar."}},{"order":8,"kazanim":"Her Tür Problemi Çözen (×/÷)","gunluk":{"t":"Satır-sütun say","adim":["Çikolata kalıbı, yumurta kutusu ya da fayans gibi satır-sütun düzenleri gösterin.","'Bu sırada kaç var, kaç sıra var, toplam kaç?' deyin.","Raf dizerken dizilimi çarpıma çevirip günlük problemi sözle kurun."],"soyle":"«Kaç sıra, her sırada kaç tane; toplam kaç eder?»","isaret":"Dizilimi satır×sütun olarak okuyup toplamı çarpımla bulur."},"oyun":{"t":"Dizi kur, döndür","adim":["Pulları 3 satır 4 sütun dizdirin.","'Döndürsek de toplam değişir mi?' diye 3×4=4×3'ü keşfettirin.","Sonra 'iki kutuda altışar kalem var, toplam?' gibi kısa sözel problem atın."],"soyle":"«Diziyi döndürdük; toplam değişti mi? Şimdi şu problemi çöz.»","isaret":"Diziyi çarpımla niceler ve değişme özelliğini fark eder."},"yaprak":{"t":"Diziyi problemle eşle","adim":["Kâğıda noktalardan bir dizi (örn. 4×5) çizdirin.","Toplamı satır×sütun olarak yazdırın.","Altına basit bir hikâye problemi koyun ('5 vazoya 4'er çiçek, toplam kaç?') ve dizilimle eşleştirsin."],"soyle":"«Bu diziyi yazıyla anlat: kaç çarpı kaç, toplam kaç?»","isaret":"Diziyi çarpım olarak yazar ve sözel problemle eşleştirir."}},{"order":9,"kazanim":"Paylaştırarak Bölen","gunluk":{"t":"Tarifi ölçekle","adim":["Yemek tarifini ölçeklerken parça-bütünü konuşun.","'Bir kişilik 2 yumurta ise 4 kişiye kaç?' deyin.","'8 yumurtamız varsa kaç kişilik olur?' diye çarpma ve bölmeyi aynı bütünde ileri-geri kullandırın."],"soyle":"«Kişi başı 2 yumurta; 4 kişiye kaç, 8 yumurta kaç kişilik?»","isaret":"Aynı durumda hem çarpma hem bölmeyi (ters işlem) kullanır."},"oyun":{"t":"Kur ve boz","adim":["24 boncukla 'kaç tane 6'lık grup çıkar, ya 4'lük?' diye böldürün.","Sonra '6'lı gruplardan bütünü geri kur' deyin.","Parçadan bütüne ve bütünden parçaya çarpımsal gidiş-gelişi oynayın."],"soyle":"«24'ü 6'lı gruplara böl, sonra gruplardan bütünü geri kur.»","isaret":"Bütünü parçalara böler ve parçalardan bütünü geri kurar."},"yaprak":{"t":"Bir bütün, çok parça","adim":["Kâğıda bir 'bütün' yazın (örn. 18).","Çocuk onu farklı eşit parçalara böldürün (2×9, 3×6, 9×2).","Her birini çizimle göstersin."],"soyle":"«18'i kaç farklı eşit parçaya bölebilirsin? Hepsini çiz.»","isaret":"Aynı bütünü birden çok çarpımsal parçaya ayırdığını gösterir."}}]},"frac":{"code":"Y07","name":"Kesirler","strand":"islemler","levels":[{"order":1,"kazanim":"Oranı Sezen: Temeller","gunluk":{"t":"Adil pay sezgisi","adim":["Pizza, pasta ya da ekmeği keserken parçaları yan yana koyun.","Çocuğa iki parçayı gösterip elini 'daha büyük pay'ın üstüne koymasını isteyin.","İki bardağa farklı miktarda su koyup hangisinde daha çok olduğunu sorun."],"soyle":"«Bana çok, sana az olmasın; hangisi daha büyük pay?»","isaret":"Saymadan, gözüyle büyük payı/çok suyu doğru gösterir."},"oyun":{"t":"İki ayıya adil ikram","adim":["İki ayı/bebek ve bir avuç bisküvi alın.","Bisküvileri iki tabağa koyup 'ikisine de adil olalım' deyin.","Çocuk hangi tabağın daha dolu olduğunu göstersin; sonra büyük-küçük bardakları doldurup hangisinin çabuk dolduğuna bakın."],"soyle":"«İkisi de küsmesin; hangi tabak daha dolu?»","isaret":"Daha dolu tabağı/çabuk dolan bardağı gözüyle seçer."},"yaprak":{"t":"Az mı çok mu pay","adim":["İki resim çizin: birinde 1 kurabiye 1 çocuğa, diğerinde 1 kurabiye 4 çocuğa.","Çocuğa 'hangi çocuklar daha az kurabiye yer?' diye sorun.","Doğru tarafı işaretletip neden az olduğunu birlikte söyleyin."],"soyle":"«Kurabiye aynı; çok kişi paylaşınca herkese az mı çok mu düşer?»","isaret":"Kalabalık grubun daha az pay aldığını işaretler."}},{"order":2,"kazanim":"Şekli Eş Parçalara Bölen","gunluk":{"t":"Tıpatıp eşit kes","adim":["Sandviç, tost ya da peçeteyi keserken 'iki parça da tıpatıp aynı olsun' deyin.","Çocuğa nereden keseceğini gösterttirin.","Kestikten sonra iki parçayı üst üste koyup eşit olup olmadığına birlikte bakın."],"soyle":"«İki parça da tıpatıp aynı olsun; üst üste koyalım, çakıştı mı?»","isaret":"Parçaları çakıştırınca eşit kestiğini görür ve gerekirse düzeltir."},"oyun":{"t":"Eşit ikiye bölme yarışı","adim":["Bir A4 kâğıt ya da hamur verin.","'Bunu iki kardeşe eşit böl' deyin; katlayıp kessin.","İki parçayı üst üste koyarak eşitliği kontrol edin; en eşit bölen kazansın."],"soyle":"«Kim daha eşit ikiye bölecek? Üst üste koyup ölçelim.»","isaret":"Katlayıp böldüğünde iki yarı çakışır."},"yaprak":{"t":"Şekli ikiye bölen çizgi","adim":["Üzerinde dikdörtgen, daire ve kare olan bir kâğıt hazırlayın.","Çocuk her şekli iki eşit parçaya bölen bir çizgi çizsin.","Katladığında iki yarı çakışıyorsa 'tam eşit böldün' deyin."],"soyle":"«Bu çizgi şekli iki eşit parçaya bölüyor mu?»","isaret":"Çizdiği çizgi şekli çakışan iki eşit parçaya ayırır."}},{"order":3,"kazanim":"Yarımı Tanıyan","gunluk":{"t":"Bu yarım","adim":["Meyveyi, sandviçi ya da kurabiyeyi tam ortadan ikiye bölün.","'Bu yarım; iki yarım birleşince yine bütün olur' deyip kendi yarısını gösterttirin.","Bir bardağı 'yarıya kadar' doldurmasını isteyip 'işte yarım bardak' deyin."],"soyle":"«Bunun yarısı bu; iki yarım birleşince ne olur?»","isaret":"Bütünün yarısını gösterir ve iki yarımın bütün ettiğini söyler."},"oyun":{"t":"Yarımı bul","adim":["Mutfakta bir şeyi ikiye bölüp yarısını saklayın.","Çocuk 'bütünün yarısı nerede?' diye eşini bulsun.","Hamurdan top yapıp 'yarısını bana ver' deyin; ikiye bölüp eşit mi diye bakın."],"soyle":"«Bütünün öbür yarısı nerede saklı?»","isaret":"Saklı yarımı bulur ve hamuru iki eş parçaya böler."},"yaprak":{"t":"Gerçek yarımı boya","adim":["Birkaç şekil çizin: bazıları tam ortadan eşit, bazıları yamuk bölünmüş.","Çocuk yalnızca gerçekten yarıya (iki eşit) bölünmüş olanları seçsin.","Bunların bir yarısını renklendirsin."],"soyle":"«Hangileri tam yarıya bölünmüş? Sadece onların bir yarısını boya.»","isaret":"Eşit bölünmüşleri seçer, eşit olmayanları boyamaz."}},{"order":4,"kazanim":"Birim Kesri Tanıyan","gunluk":{"t":"Bir dilim: kaçta bir","adim":["Çikolatayı ya da pideyi 3-4 eşit parçaya bölün.","Tek bir parçayı gösterip 'bu bütünün dörtte biri' diye adlandırın.","'Kaç parçaya böldük? Sen bir parça aldın, bu kaçta bir?' diye sorun."],"soyle":"«Dört eşit parça; sen bir tane aldın, bu dörtte bir.»","isaret":"Kaça bölündüğüne bakıp tek parçayı 'üçte/dörtte bir' diye adlandırır."},"oyun":{"t":"Bir dilim ver","adim":["Kâğıt 'pizza'yı eşit dilimlere kesin.","Zar atıp 'bana üçte bir, yani bir dilim ver' gibi tek parça isteyin.","Gizlice 2/3/4 eşit parçaya bölüp 'bu bir parça kaçta bir?' diye sordurun."],"soyle":"«Bana bir dilim, yani kaçta bir verirsin?»","isaret":"Doğru büyüklükte tek dilimi verir ve adını söyler."},"yaprak":{"t":"Tek parçayı adlandır","adim":["Eşit parçalara bölünmüş daireler/dikdörtgenler çizin (yarım, üçte bir, dörtte bir).","Her şekilde tek bir parçayı boyatın.","Altına 'kaçta bir' olduğunu birlikte yazın."],"soyle":"«Boyadığın parça bütünün kaçta biri?»","isaret":"Boyalı tek parçayı doğru birim kesirle adlandırır."}},{"order":5,"kazanim":"Kesri Tanıyan","gunluk":{"t":"Kaçtan kaçı kaldı","adim":["Pizzayı 4 dilime bölüp 3'ünü tabağa koyun.","'Dörtte üç dilim var, biri yendi' deyip kaç parçadan kaçının durduğunu söyletin.","Bir kutu yumurtanın yarısı bitince 'yarısı kalmış' diyerek kesir dilini kullanın."],"soyle":"«Dört dilimden üçü duruyor: dörtte üç. Sen söyle bakalım.»","isaret":"'Kaçtan kaçı' diyerek hem paydayı hem payı söyler."},"oyun":{"t":"Kesir söyle","adim":["Kâğıt dilimleri tabağa dizin.","Çocuk 'burada dörtte üç var' gibi hem alttaki hem üstteki sayıyı söylesin.","Renkli bloklarla '5 bloktan 2'si mavi' deyip 'beşte iki mavi' diye adlandırsın."],"soyle":"«Tabakta kaçta kaç var? İki sayıyı da söyle.»","isaret":"Toplam parça ve boyalı/dolu parçayı birlikte 'beşte iki' gibi okur."},"yaprak":{"t":"Boyalıyı kesirle yaz","adim":["Bazı parçaları boyalı şekiller çizin.","Çocuk her şeklin altına 'boyalı / toplam' sayısını yazsın.","Kesri sesli adlandırsın (ör. üçte iki)."],"soyle":"«Boyalı parça ne kadar? Boyalıyı toplamla birlikte yaz.»","isaret":"Boyalı parçayı doğru kesir adıyla yazıp okur."}},{"order":6,"kazanim":"Birim Kesirlerden Kesir Oluşturan","gunluk":{"t":"Çeyrekleri biriktir","adim":["Pizzayı dörtte birlik dilimlerle servis edin.","'Bir dörtte bir, iki dörtte bir...' diye dilimleri sayarak biriktirin.","Bardağa çeyrek çeyrek su ekleyip 'şimdi üç çeyrek doldu' deyin."],"soyle":"«Bir çeyrek, iki çeyrek, üç çeyrek; bak dörtte üç oldu.»","isaret":"Birim dilimleri sayarak istenen kesre ulaşır."},"oyun":{"t":"Dilim biriktir","adim":["Hepsi dörtte bir olan eşit kâğıt dilimleri bir kutuya koyun.","'Dörtte üç yap' deyince çocuk üç parçayı yan yana dizsin.","Zar atıp her atışta bir birim dilim eklensin; hedef kesre ilk ulaşan kazansın."],"soyle":"«Dörtte üç yapmak için kaç tane dörtte bir gerek?»","isaret":"Birim dilimleri yan yana koyarak hedef kesri kurar."},"yaprak":{"t":"Dilimleyerek kesri kur","adim":["Boş, eşit parçalı şekiller verin.","'Dörtte üçü boya' gibi yönergeyle dilimleri tek tek boyasın.","Boyadığı dilimleri sayıp kesri söylesin."],"soyle":"«İstenen kesir kadar dilimi tek tek boya, sonra say.»","isaret":"Birim dilimleri sayarak istenen kesri doğru boyar."}},{"order":7,"kazanim":"Kesir Oluşturan","gunluk":{"t":"Hedef kesri kur","adim":["Sofrada 'bize beşte üç tabak lazım' gibi bir hedef verin.","Çocuk tam o kadar dilimi/parçayı sayarak oluştursun.","Çamaşır asarken 'mandalların dörtte üçü kırmızı olsun' deyip birlikte sayarak kurun."],"soyle":"«Beşte üç olması için kaç parça gerek? Tam onu hazırla.»","isaret":"Verilen kesri doğru sayıda parçayla oluşturur."},"oyun":{"t":"Sipariş kesir","adim":["Lego/blok tabanı seçin (ör. 6'lık).","'Altıda dördünü mavi yap' deyince doğru sayıda mavi blok koysun.","Kartta bir kesir yazılı olsun (ör. üçte iki); çocuk o kesri dilimlerle tabakta hazırlayıp servis etsin."],"soyle":"«Sipariş: altıda dört mavi. Tam o kadar blok koy.»","isaret":"İstenen kesri doğru sayıda parça/blokla hazırlar."},"yaprak":{"t":"Hedef kadar boya","adim":["Boş eşit-parçalı şekiller çizin.","Altlarına hedef kesirler yazın (ör. dörtte üç, beşte iki).","Çocuk her şekilde tam o kadar parçayı boyasın."],"soyle":"«Altında yazan kesir kadar parçayı boya.»","isaret":"Yazılı hedef kesir kadar parçayı doğru boyar."}},{"order":8,"kazanim":"Kesri Yineleyip Bütünü Aşan","gunluk":{"t":"Çeyrekler bütün yapar","adim":["Bardağı çeyrek çeyrek doldurun.","'Dört tane çeyrek koyduk, bak bardak tam doldu, bütün oldu' deyin.","Pizza dilimlerini tek tek geri koyarken 'dörtte bir, iki, üç, dört... yine bütün' diye sayın."],"soyle":"«Kaç tane çeyrek bir araya gelince bütün olur?»","isaret":"Birim kesri tekrarlayıp 'kaç tane bütünü yapar' sorusunu yanıtlar."},"oyun":{"t":"Bütünü tamamla","adim":["Tek tip dilimler kullanın (hepsi üçte bir, ya da hepsi dörtte bir).","Çocuk üçte birlerden 3, dörtte birlerden 4 koyarak tam daireyi kapatsın.","Zar atıp her atışta bir birim dilim eklensin; bütünü ilk tamamlayan kazansın."],"soyle":"«Bütünü kapatmak için bu dilimden kaç tane gerek?»","isaret":"Aynı birim dilimi tekrarlayarak bütünü eksiksiz kapatır."},"yaprak":{"t":"Kaç dilim bütün eder","adim":["Boş bir daire/çubuk ve yanında tek tip dilimler çizin.","'Kaç tane dörtte bir bütünü yapar?' diye sorun.","Çocuk dilimleri sayarak (4) boşluğu doldursun."],"soyle":"«Bu dilimden kaç tane koyunca tam bütün olur?»","isaret":"Birim dilimi sayarak bütünü kaç parçanın yaptığını bulur."}},{"order":9,"kazanim":"Kesirlerle Toplama-Çıkarma Yapan","gunluk":{"t":"Çeyrekleri topla","adim":["Pizzanın bir çeyreğini, sonra bir çeyrek daha yiyin.","'Bir çeyrek artı bir çeyrek, toplam yarım yedik' deyin.","İki çeyrek bardak suyu birleştirip 'ikisi yarım oldu' diyerek aynı paydada toplamayı gösterin."],"soyle":"«Bir çeyrek ve bir çeyrek; ikisi birleşince ne kadar oldu?»","isaret":"Aynı paydalı dilimleri birleştirip toplamı söyler (payda aynı kalır)."},"oyun":{"t":"Birleştir-çıkar dilim","adim":["Aynı boy kâğıt dilimler kullanın.","'Üçte bir + üçte bir kaç eder?' diye dilimleri yan yana koyup üçte iki bulun.","Zar/kart çekip aynı paydadan dilim ekleyin ya da tabaktan çıkarın; sonucu birlikte okuyun."],"soyle":"«Üçte bir ve üçte bir yan yana; kaç dilim, yani kaç oldu?»","isaret":"Dilimleri sayarak aynı paydalı toplama/çıkarmayı doğru bulur."},"yaprak":{"t":"Şeritle topla","adim":["Aynı paydalı kesir şeritleri verin (ör. beşte iki + beşte bir).","Çocuk dilimleri boyayıp birleştirsin.","Toplam boyalı dilimi sayıp sonucu yazsın."],"soyle":"«Boyalı dilimleri birleştir; toplam kaç dilim oldu?»","isaret":"Payları toplar, paydayı aynı tutarak doğru sonucu yazar."}},{"order":10,"kazanim":"Kesirlerle Çarpma-Bölme Yapan","gunluk":{"t":"Yarımın yarısı","adim":["Tarifte 'yarım bardağın yarısı kadar şeker' deyin.","'Yarımın yarısı çeyrek eder' diye çocukla ölçüp gösterin.","Bir çikolatanın yarısını iki kişiye bölüp 'herkese çeyrek düştü' deyin."],"soyle":"«Yarımı ikiye bölünce her parça ne kadar oldu?»","isaret":"Yarımı bölünce çeyrek elde ettiğini somut olarak görür."},"oyun":{"t":"Kesirin kesiri","adim":["Ölçü kabıyla yarım bardak suyu iki eşit kaba bölün.","'Yarımın yarısı çeyrek' sonucunu gözle bulun.","Bir yarım kâğıt dilimi tekrar ikiye katlayıp 'yarımın yarısı kaç oldu?' diye keşfettirin."],"soyle":"«Yarımı ikiye böldük; her parça bütünün ne kadarı?»","isaret":"Katlayarak/dökerek yarımın yarısının çeyrek olduğunu bulur."},"yaprak":{"t":"Katla ve böl","adim":["Görsel kesir şeritleri verin.","'Yarımın yarısını boya' ya da 'çeyreği ikiye böl' gibi adımlar yazın.","Çocuk katlayıp boyayarak sonucu görsün."],"soyle":"«Bu parçayı ikiye bölersek ne kadar olur? Katlayıp boya.»","isaret":"Katlayıp boyayarak bölme/çarpma sonucunu doğru gösterir."}},{"order":11,"kazanim":"Kesir ve Tam Sayıları Sıralayan","gunluk":{"t":"Azdan çoğa diz","adim":["Buzdolabındaki yarım, çeyrek ve dolu şişeleri çıkarın.","Çocuk bunları en azdan en çoğa sıralasın.","İki kardeş pizzanın yarısını, çeyreğini ve bütününü alınca 'kim en çok, kim en az aldı?' diye sıralatın."],"soyle":"«Çeyrek mi, yarım mı, bütün mü daha çok? Azdan çoğa diz.»","isaret":"Çeyrek<yarım<bütün sırasını doğru kurar."},"oyun":{"t":"Kartları sırala","adim":["Kesir ve tam sayı kartlarını karıştırın (çeyrek, yarım, 1 bütün, 2).","Çocuk bunları küçükten büyüğe sıralayıp en büyüğü bulsun.","Farklı dolulukta su bardaklarını sıraya dizip 'hangisi 1'e en yakın?' diye konuşun."],"soyle":"«Bu kartları küçükten büyüğe diz; en büyük hangisi?»","isaret":"Kesir ve tam sayıları büyüklükçe doğru sıraya koyar."},"yaprak":{"t":"Sayı doğrusuna yerleştir","adim":["Bir sayı doğrusu çizip 0, yarım, 1, 2 yerlerini işaretleyin.","Çocuk verilen kesir ve tam sayı kartlarını doğru yerlerine koysun.","Yerleştirdikçe büyüklükçe sıralasın."],"soyle":"«Bu sayı doğruda nereye düşer? 0 ile 1 arasında mı, sonra mı?»","isaret":"Kesirleri ve tam sayıları doğru üzerinde doğru konuma yerleştirir."}}]},"pattern":{"code":"Y08","name":"Örüntü, Yapı ve Cebirsel Düşünme","strand":"cebir","levels":[{"order":1,"kazanim":"Örüntüyü Sezen: Temeller","gunluk":{"t":"Düzeni hisset","adim":["Yemek hazırlarken bir tabağa kırmızı-yeşil-kırmızı-yeşil domates dizin.","Birlikte ritimle 'kırmızı, yeşil, kırmızı, yeşil' deyin.","Çocuk sadece keyifle izlesin ya da tekrar etsin; doğru-yanlış aramayın."],"soyle":"«Kırmızı, yeşil, kırmızı, yeşil... bak nasıl dönüp duruyor!»","isaret":"Düzenli diziye dikkatini verir, ritmi keyifle izler."},"oyun":{"t":"Tık-tak ritmi","adim":["İki renk Lego veya kapak alın.","'Tık-tak, tık-tak' diyerek mavi-sarı-mavi-sarı dizin, elinizle ritim tutun.","Çocuk bu düzenli ses-görseli sizinle birlikte hissetsin."],"soyle":"«Tık-tak, tık-tak; duydun mu, hep aynı şekilde gidiyor.»","isaret":"Düzenli sesli-görsel ritme eşlik eder ya da ilgiyle bakar."},"yaprak":{"t":"Sıra üstünde gez","adim":["Bir kâğıda iki kalıpla (yuvarlak-kare-yuvarlak-kare) damga/çıkartma yapın.","Çocuk parmağıyla soldan sağa üzerinden geçsin.","Amaç sıralı düzene dokunma ve göz alıştırması; sonuç beklemeyin."],"soyle":"«Parmağınla baştan sona gez: yuvarlak, kare, yuvarlak, kare.»","isaret":"Sıralı dizinin üstünden soldan sağa düzenli geçer."}},{"order":2,"kazanim":"Örüntüyü Fark Eden","gunluk":{"t":"Sıralı mı karışık mı","adim":["Sofrada çatal-kaşık-çatal-kaşık dizin.","'Burada bir tekrar var, bak nasıl dönüp duruyor!' deyin.","'Bu sıralı mı, karışık mı?' diye sorun."],"soyle":"«Bu diziliş sıralı mı, yoksa karışık mı?»","isaret":"Tekrar eden dizilişe 'sıralı' der, bir düzen olduğunu fark eder."},"oyun":{"t":"Sıralıyı yakala","adim":["Yastık-ayıcık-yastık-ayıcık gibi iki eşyayı yere sıralayın.","Bir köşeye de aynı eşyaları gelişigüzel yığın.","'Hangisi sıra sıra, hangisi karışık?' diye sorup tekrarlıyı birlikte gösterin."],"soyle":"«Hangisi sıra sıra gidiyor, hangisi karışık?»","isaret":"Düzenli sırayı karışık yığından ayırt eder."},"yaprak":{"t":"Tekrarlı şeridi seç","adim":["Kâğıda biri düzenli (●▲●▲●▲), biri rastgele iki şerit çizin.","Çocuk tekrar eden, sıralı şeridi parmağıyla işaretlesin.","Doğru bulunca 'evet, bu sıra sıra gidiyor' deyin."],"soyle":"«Hangi şerit tekrar ederek sıra sıra gidiyor?»","isaret":"Tekrarlı şeridi rastgele şeritten ayırıp işaretler."}},{"order":3,"kazanim":"AB Örüntüsü Kuran","gunluk":{"t":"Eksik olan ne","adim":["Çorapları çift-tek-çift-tek katlayın.","Ortadan bir tanesini gizleyip 'buraya hangisi gelmeliydi?' diye sorun.","Çocuk tekrara bakarak eksik olanı söyleyip yerine koysun."],"soyle":"«Sıra böyle gidiyordu; buraya hangisi gelmeliydi?»","isaret":"Tekrara bakıp boşluğa gelen öğeyi doğru söyler."},"oyun":{"t":"Ne eksildi","adim":["Kaşık-bardak-kaşık-bardak dizin.","'Hadi gözünü kapat!' deyip aradan bir öğeyi saklayın.","Gözünü açınca 'burada ne eksik?' diye sorun; boşluğu doğru eşyayla doldursun."],"soyle":"«Sıradan bir şey kayboldu; ne eksik, boşluğa ne gelmeli?»","isaret":"Örüntüye bakarak eksilen öğeyi bulup yerine koyar."},"yaprak":{"t":"Boşluğu tamamla","adim":["Kâğıda ●■●_●■ gibi bir şerit çizin, bir kutucuğu boş bırakın.","Çocuk iki yanına baksın.","Boşluğa gelen şekli çizsin veya çıkartmayla tamamlasın."],"soyle":"«İki yanına bak; boşluğa hangi şekil gelmeli?»","isaret":"Kurala göre boşluğa doğru şekli yerleştirir."}},{"order":4,"kazanim":"Çeşitli Örüntüler Kuran (AAB, ABC)","gunluk":{"t":"Aynısını diz","adim":["Bir kırmızı bir mavi toka takın: kırmızı-mavi-kırmızı-mavi.","'Ben böyle dizdim' deyin.","Çocuk kendi tokalarıyla tıpkı sizinki gibi aynı sırayla dizsin."],"soyle":"«Benimkine tıpatıp benzeyen bir sıra yap: kırmızı, mavi, kırmızı, mavi.»","isaret":"Verilen AB dizisini aynı sırayla birebir kopyalar."},"oyun":{"t":"Aynı kolyeyi yap","adim":["Boncuk/makarnayı kırmızı-yeşil-kırmızı-yeşil bir ipe dizin.","Çocuğa ikinci bir ip verin.","'Benimkine tıpatıp benzeyen bir kolye yap' deyip yan yana karşılaştırın."],"soyle":"«Benim kolyemin tıpkısını yap; yan yana koyalım, aynı mı?»","isaret":"İkinci ipe aynı renk sırasını birebir dizer."},"yaprak":{"t":"Alt satıra kopyala","adim":["Üst satıra mavi-sarı-mavi-sarı bir örüntü hazırlayın.","Çocuk hemen alttaki boş satıra baksın.","Aynı renkleri aynı sırayla boyayarak bire bir kopyalasın."],"soyle":"«Üstteki sırayı alta tıpatıp aynı boya.»","isaret":"Alt satırı üstteki örüntüyle aynı sırada doldurur."}},{"order":5,"kazanim":"Örüntüyü Aktaran ve Birimini Bulan","gunluk":{"t":"Ritmi sürdür","adim":["Merdiven çıkarken 'iki ayak sağ, iki ayak sol' ya da 'büyük-büyük-küçük adım' ritmi tutturun.","Birkaç tur birlikte yapın.","Çocuk bu kalıbı bozmadan birkaç tur daha uzatsın."],"soyle":"«Büyük, büyük, küçük... şimdi sen aynı şekilde devam ettir.»","isaret":"AABB/ABC ritmini bozmadan birkaç tur sürdürür."},"oyun":{"t":"Sen devam ettir","adim":["El çırpma-el çırpma-diz vurma (AAB) gibi bir ses örüntüsü başlatın.","Siz iki tur yapın.","'Sen devam ettir!' deyip çocuk kalıbı koparmadan birkaç kez sürdürsün."],"soyle":"«Çırp, çırp, diz... ben başladım, sen aynı şekilde sürdür.»","isaret":"Çok öğeli birimi koruyarak örüntüyü devam ettirir."},"yaprak":{"t":"Satırı uzat","adim":["Kâğıda AABB/ABC örüntüsünün ilk birkaç öğesini çizin (●●▲▲●●▲▲...).","Satırın sonunu boş bırakın.","Çocuk kuralı koruyarak satırı sonuna kadar uzatsın."],"soyle":"«Bu sıra nasıl gidiyorsa, sonuna kadar aynı kuralla uzat.»","isaret":"Tekrar birimini doğru kesip örüntüyü doğru uzatır."}},{"order":6,"kazanim":"Sayı Örüntüsü Kuran","gunluk":{"t":"Aynı kural başka hareket","adim":["Bir kalıp kurun: 'alkış-alkış-ıslık'.","'Şimdi bunu zıplamayla anlatalım: zıpla-zıpla-dön' deyip aynı kuralı başka harekete çevirin.","Çocuk tekrar eden parçanın (birim) ne olduğunu söylesin."],"soyle":"«Hep tekrar eden parça hangisi? Onu zıplamayla anlatalım.»","isaret":"Tekrar birimini bulur ve aynı kuralı başka harekete çevirir."},"oyun":{"t":"Malzemeyi değiştir","adim":["Boncukla kırmızı-kırmızı-mavi örüntüsü dizin.","'Bunu kapaklarla yapsak nasıl olurdu?' deyip aynı kuralı farklı malzemeyle kurun.","'Hep tekrar eden parça hangisi?' diye çekirdek birimi buldurun."],"soyle":"«Aynı kuralı kapaklarla kuralım; tekrar eden parça neydi?»","isaret":"Aynı kuralı yeni malzemeyle kurar, çekirdek birimi gösterir."},"yaprak":{"t":"Şekle çevir","adim":["Üstte renkli bir örüntü olsun (sarı-sarı-yeşil).","Altta çocuk aynı kuralı şekillerle (●●▲) yeniden çizsin.","Tekrar eden çekirdek birimin altını birlikte çizin."],"soyle":"«Üstteki renk kuralını altta şekillerle anlat; tekrar eden parça hangisi?»","isaret":"Renk kuralını şekle çevirir ve tekrar birimini işaretler."}},{"order":7,"kazanim":"İşlem Örüntülerini Fark Eden","gunluk":{"t":"Sıradaki sayı","adim":["Merdiven sayarken '2, 4, 6, 8...' ya da kapı numaralarını söyleyin.","'Sıradaki sayı kaç olur dersin?' diye sorun.","Çocuk sayısal sırayı bir-iki adım daha sürdürsün."],"soyle":"«2, 4, 6, 8... sıradaki sayı kaç olur dersin?»","isaret":"Sayısal diziyi bir-iki adım doğru ilerletir."},"oyun":{"t":"İkişer büyüt","adim":["Zar atıp her turda 2 düğme/fasulye ekleyin.","'Şimdi kaç oldu?' diyerek yığını 2, 4, 6, 8 diye büyütün.","Çocuk bir sonraki turda kaç olacağını tahmin edip kontrol etsin."],"soyle":"«Her turda 2 ekliyoruz; bir sonraki sefer kaç olacak?»","isaret":"Sonraki sayıyı tahmin edip nesneyle doğrular."},"yaprak":{"t":"Sayı dizisini tamamla","adim":["Kâğıda '5, 10, 15, __, __' ya da '1, 3, 5, __' yazın.","Çocuk boşlukları bularak diziyi tamamlasın.","Rakamı yazamıyorsa o kadar nesne çizsin."],"soyle":"«Bu sayılar nasıl gidiyor? Boşlukları doldur.»","isaret":"Sayısal örüntüyü kuralına uygun tamamlar."}},{"order":8,"kazanim":"İlişkisel Düşünen (+/−)","gunluk":{"t":"İki taraf eşit","adim":["İki tabağa eşit kurabiye koyun: 'bu tarafta 3, bu tarafta da 3, eşit'.","Birinden bir tane alın: 'eşitlik bozuldu' deyin.","'Dengelemek için ne yapmalı?' diye konuşun."],"soyle":"«İki taraf eşitti; birini aldım, dengeyi nasıl kurarız?»","isaret":"Eşitliği bozulan tarafı doğru sayıda ekleyip/çıkarıp dengeler."},"oyun":{"t":"Terazi dengesi","adim":["İki kaba (ya da teraziye) aynı sayıda kapak koyup dengeyi gösterin.","Bir tarafa 1 ekleyin.","Çocuk öbür tarafı eşitlemek için kaç eklemesi gerektiğini bulup dengeyi kursun."],"soyle":"«Bir tarafa 1 ekledim; diğer tarafa kaç eklersek eşit olur?»","isaret":"İki tarafı eşit sayıya getirerek dengeyi kurar."},"yaprak":{"t":"Eşitliği kur","adim":["Kâğıda iki kutu çizip ortasına '=' koyun, soluna 5 nesne çizin.","Çocuk sağ kutuya da aynı sayıda çizerek eşitliği kursun.","'Soldan 2 alırsam sağdan kaç almalıyım?' sorusunu çizerek çözsün."],"soyle":"«İki taraf eşit olmalı; sağa kaç çizersen eşit olur?»","isaret":"İki tarafı eşitleyecek sayıyı çizer, '=' işaretini denge olarak kullanır."}},{"order":9,"kazanim":"Sembollerle İlişkisel Düşünen (+/−)","gunluk":{"t":"Eşittir denge demek","adim":["Kâğıda '3 + 2 = 2 + __' yazın.","'İki taraf da eşit olmalı, boşluğa ne gelir?' diye sorun.","Çocuk '=' işaretinin 'iki taraf aynı' demek olduğunu kullanarak doldursun."],"soyle":"«Eşittir iki tarafın aynı olması demek; boşluğa ne gelir?»","isaret":"'=' işaretini denge olarak yorumlayıp doğru sayıyı yazar."},"oyun":{"t":"Eksik kartı bul","adim":["Rakam kartları ve '+', '=' kartlarıyla yere '4 + __ = 6' kurun.","Çocuk eksik kartı seçip koyarak doğru kartı bulsun.","Sonra nesnelerle doğrulayın."],"soyle":"«İki tarafı eşit yapan kart hangisi? Onu koy.»","isaret":"Eşitliği sağlayan kartı seçer ve nesneyle doğrular."},"yaprak":{"t":"Eşitlikleri doldur","adim":["'5 + 3 = 8 + __', '7 = 4 + __', '6 − 2 = __ + 1' yazın.","Çocuk her satırda iki tarafı denkleştiren sayıyı bulsun.","Boşlukları doldursun."],"soyle":"«Her satırda iki tarafı denk yapan sayıyı yaz.»","isaret":"Her sembolik eşitlikte iki tarafı eşitleyen sayıyı bulur."}},{"order":10,"kazanim":"Çarpmayla İlişkisel Düşünen","gunluk":{"t":"Her kişiye ikişer","adim":["Sofrayı kurarken 'her tabağa 2 çatal koyacağız' deyin.","'3 tabak olursa kaç çatal lazım?' diye sorup ikişer ikişer sayın.","Çocuk 'her kişi için 2' ilişkisini kullanarak toplamı bulsun."],"soyle":"«Her tabağa 2 çatal; 3 tabakta kaç çatal eder?»","isaret":"'Her birine bu kadar' ilişkisini kullanarak toplamı bulur."},"oyun":{"t":"Her kutuya üçer","adim":["Zar atıp çıkan sayı kadar 'kutu' çizin.","Her kutuya hep 3 düğme koyun.","'Her seferinde 3'er gidiyor, 4 kutuda kaç eder?' diye çarpımsal hesaplatın."],"soyle":"«Her kutuda 3 düğme; 4 kutuda toplam kaç olur?»","isaret":"Sabit grup büyüklüğünü kullanarak toplamı çarpımsal bulur."},"yaprak":{"t":"Çarpım tablosunu doldur","adim":["Bir tablo çizin: 1 paket=2 kalem, 2 paket=4, 3 paket=__, 4 paket=__.","Çocuk 'her pakette 2' kuralını görsün.","Tabloyu çarpımsal ilişkiyle tamamlasın."],"soyle":"«Her pakette 2 kalem; bu kuralla tabloyu doldur.»","isaret":"Çarpımsal kuralı görüp tabloyu doğru tamamlar (sabit ekleme yapmaz)."}},{"order":11,"kazanim":"Kuralı Bulup Genelleyen","gunluk":{"t":"Sayı makinesi","adim":["'Sihirli makine' oyunu kurun: 'Ben hep 2 fazlasını söylüyorum'.","'3 dersem 5, 5 dersem 7' diye birkaç örnek verin.","'Ben 10 dersem sen ne dersin?' deyip girdi-çıktı ilişkisini yakalayın."],"soyle":"«Bu makine hep 2 fazlasını verir; 10 girince ne çıkar?»","isaret":"Girdi-çıktı kuralını yeni bir girdiye doğru uygular."},"oyun":{"t":"Gizli kuralı bul","adim":["Bir kutuyu 'sihirli makine' yapın.","İçine konan her sayıya aynı işlemi uygulayın (×2 veya +3).","Birkaç örnekten sonra çocuk gizli kuralı bulup yeni girdilere çıktı söylesin."],"soyle":"«Makinenin gizli kuralı ne? Yeni sayı girince ne çıkar?»","isaret":"Birkaç örnekten kuralı çıkarır ve yeni girdiye uygular."},"yaprak":{"t":"Girdi-Çıktı tablosu","adim":["İki sütunlu 'Girdi / Çıktı' tablosu verin (1→4, 2→5, 3→6, 4→__).","Çocuk değişkenler arasındaki kuralı (çıktı = girdi + 3) bulsun.","Hem boşlukları doldursun hem kuralı kendi cümlesiyle yazsın."],"soyle":"«Girdiyle çıktı arasındaki kural ne? Boşluğu doldurup kuralı yaz.»","isaret":"İşlev kuralını bulur, boşluğu doldurur ve kuralı ifade eder."}}]},"shape2d":{"code":"Y09","name":"İki Boyutlu Şekiller","strand":"geometri","levels":[{"order":1,"kazanim":"Benzerini Fark Eden: Temeller","gunluk":{"t":"Mutfakta aynı mı başka mı","adim":["İki özdeş kaşığı yan yana koyup 'Bunlar aynı mı, başka mı?' diye sorun.","Sonra bir kaşık bir çatal gösterip 'Peki şimdi?' deyin.","Çocuk cevap verirken siz acele etmeyin, düşünmesine zaman tanıyın."],"soyle":"«İkisi de kaşık, demek ki aynı; bu çatal başka.»","isaret":"Çocuk renkten/boyuttan değil 'aynı eşya mı' diye bakıp seçer."},"oyun":{"t":"İkiz mi değil mi oyunu","adim":["Evdeki çiftleri toplayın: iki ayakkabı, iki çorap, bir ayakkabı bir çorap.","Her turda bir ikili gösterip 'İkiz mi, değil mi?' diye sorun.","Doğru her sezişte birlikte el çırpın."],"soyle":"«İkisi de çorap, bunlar ikiz! Bu ise farklı.»","isaret":"Çocuk eşli olanlara 'ikiz', karışık olana 'değil' der."},"yaprak":{"t":"Kardeşler hangi tabakta","adim":["Bir tabağa iki özdeş düğme (ya da iki üzüm) koyun.","Öteki tabağa bir düğme bir fasulye koyun.","'Kardeşler hangi tabakta?' diye sorup eşli tabağı buldurun."],"soyle":"«Bu tabaktakiler birbirinin aynısı, kardeş gibi.»","isaret":"Çocuk parmağıyla iki aynı nesneli tabağı gösterir."}},{"order":2,"kazanim":"Şekil Eşleyen: Aynısı, Döndürülmüşü, Büyüğü-Küçüğü","gunluk":{"t":"Yan dönmüş aynı eşya","adim":["Bir bardağı dik tutun, aynısını yatık çevirin.","'Yine aynı bardak değil mi, sadece yan dönmüş' deyin.","Büyük ve küçük aynı kupayı yan yana koyup 'biri kocaman ama yine aynı şekil' deyin."],"soyle":"«Döndü ama yine aynı şey, şekli değişmedi.»","isaret":"Çocuk döndürülmüş/boyutu değişmiş eşyayı 'yine aynı' diye tanır."},"oyun":{"t":"Gözünü aç bul","adim":["İki özdeş oyuncak alın; birini ters ya da yan çevirin.","Biri büyük biri küçük olacak şekilde de deneyin.","Çocuk gözünü kapatıp açınca 'Bunlar yine aynı mı?' desin."],"soyle":"«Ters durdu, büyüdü ama yine aynı oyuncak.»","isaret":"Çocuk yön/boyut değişse de iki oyuncağı 'aynı' eşler."},"yaprak":{"t":"Kalıp döndü yine aynı","adim":["Aynı kurabiye kalıbını bir düz, bir yan çevirerek hamura basın.","İki izi yan yana koyup gösterin.","Çocuk 'İkisi de aynı şekil' diye eşleştirsin."],"soyle":"«Kalıbı çevirdim ama çıkan şekil yine aynı.»","isaret":"Çocuk farklı yöndeki iki özdeş izi eşleştirir."}},{"order":3,"kazanim":"Tanıdık Şekilleri Tanıyan","gunluk":{"t":"Bu daire bu kare","adim":["Sofrada yuvarlak tabağı gösterip 'Bu daire' deyin.","Kare peçeteyi gösterip 'Bu kare' deyin.","Gün içinde 'Şu daireye benziyor' demesi için fırsat verin."],"soyle":"«Tabak yuvarlak, ona daire diyoruz.»","isaret":"Çocuk adını söylemese de tipik daire/kareyi tanıyıp gösterir."},"oyun":{"t":"Ben bir daire görüyorum","adim":["'Odada bir daire görüyorum' deyin.","Çocuk saat, tabak ya da topu bulsun.","Bulduğu her şekli birlikte alkışlayın, sonra kare/üçgenle sürdürün."],"soyle":"«Sen de bir daire bulabilir misin?»","isaret":"Çocuk söylenen tipik şekle uyan bir nesneyi bulur."},"yaprak":{"t":"Topa benzeyeni göster","adim":["Bir kâğıda büyük bir daire, bir kare, bir üçgen çizin.","'Topa benzeyeni göster' deyin.","Doğru seçimi sevinçle onaylayın."],"soyle":"«Top yuvarlak, ona benzeyen hangisi?»","isaret":"Çocuk tipik daireyi diğer şekiller arasından gösterir."}},{"order":4,"kazanim":"Şekil Eşleyen: Yeni Şekiller ve Bileşimler","gunluk":{"t":"Büyük küçük yine kutu","adim":["Markette farklı boylarda kutular alırken gösterin.","'Bu da kutu, şu da kutu ama biri büyük' deyin.","İnce uzun kraker kutusuyla kare bisküvi kutusunu 'ikisi de köşeli' diye eşleştirin."],"soyle":"«Boyu farklı ama ikisi de aynı köşeli şekil.»","isaret":"Çocuk boyu/yönü değişse de aynı şekli eşler."},"oyun":{"t":"Torbadan yuvarlağı bul","adim":["Bir torbaya farklı boy ve yöndeki kapaklar ile bloklar koyun.","Çocuk elini sokup 'Yuvarlağı bul' desin.","Çıkarıp baksın; büyük-küçük fark etmeden eşini bulmayı kutlayın."],"soyle":"«Küçüğü de büyüğü de olsa hepsi yuvarlak.»","isaret":"Çocuk farklı boyutlardaki aynı şekilleri bir araya getirir."},"yaprak":{"t":"Aynı aileyi topla","adim":["Aynı şekli üç farklı boyda kesip karıştırın.","'Aynı aileyi bir araya getir' deyin.","Üç öbeği birlikte sayın."],"soyle":"«Küçüğü, ortancası, büyüğü; hepsi aynı aile.»","isaret":"Çocuk boy/yön farkına rağmen aynı şekilleri gruplar."}},{"order":5,"kazanim":"Daire, Kare ve Üçgeni Tanıyan","gunluk":{"t":"Daire kare üçgen avı","adim":["Yürüyüşte tabela ve tekerlek görünce 'daire!' diye bağırın.","Pencere için 'kare!', yol levhası için 'üçgen!' deyin.","Çocuk gördükçe şeklin adını kendisi bağırsın."],"soyle":"«Bak, tekerlek daire; o levha üçgen!»","isaret":"Çocuk daire, kare ve üçgeni günlük nesnelerde adlandırır."},"oyun":{"t":"Doğru kutuya at","adim":["Üç kâğıt kutuya daire, kare, üçgen çizin.","Çocuk evdeki eşyaları 'top buraya, peçete buraya' diye doğru kutuya atsın.","Her doğru atışta 'sayı!' deyin."],"soyle":"«Yuvarlak olan daire kutusuna gider.»","isaret":"Çocuk nesneyi şekline göre doğru kutuya ayırır."},"yaprak":{"t":"Hangisi üçgen","adim":["Daire, kare, üçgen çizip altlarına adlarını yazın.","'Hangisi üçgen?' diye sorun.","Çocuk parmağıyla doğru şekle dokunsun."],"soyle":"«Üç kenarı olan üçgendir, hangisi?»","isaret":"Çocuk üç temel şekli adıyla ayırt eder."}},{"order":6,"kazanim":"Parçalardan “Benzerini” Kuran","gunluk":{"t":"İki üçgen bir kare","adim":["Sandviç yaparken ekmeği köşeden köşeye kesin.","'İki üçgen oldu, birleşince yine kare' deyin.","İki çubuk krakeri 'V' yapıp 'üçgenin tepesi gibi' diye gösterin."],"soyle":"«Parçaları birleştirince tanıdık bir şekil çıkıyor.»","isaret":"Çocuk parçaları birleştirip bir şekle benzetir."},"oyun":{"t":"Çubukla şekil kur","adim":["Üç kürdanla üçgen, dört kürdanla kare yapın.","Çocuk 'sana benzeyeni' kursun.","Tam düzgün olmasa da 'üçgene benziyor' deyip kutlayın."],"soyle":"«Üç çubuk bir üçgen yapar, dene bakalım.»","isaret":"Çocuk çubukları birleştirip hedef şekli oluşturur."},"yaprak":{"t":"İki parçadan kare","adim":["İki üçgen kâğıt parçası verin.","Çocuk bunları birleştirip kareye ya da baklavaya benzetsin.","Çıkan şekli birlikte adlandırın."],"soyle":"«İki üçgeni birleştirince ne oldu, bak!»","isaret":"Çocuk parçalardan tanıdık bir şekil oluşturur."}},{"order":7,"kazanim":"Her Tür Dikdörtgeni Tanıyan","gunluk":{"t":"Hepsi dikdörtgen ailesi","adim":["Kapı, kitap, telefon, halı için 'bunların hepsi dikdörtgen' deyin.","Kare peçeteyi de 'bu da dikdörtgen ailesinden, ama dört kenarı eşit' diye gösterin.","Uzun-kısa tüm dört köşelileri 'dikdörtgen' diye toplayın."],"soyle":"«Dört köşesi olan, karşılıklı kenarları düz; bu da dikdörtgen.»","isaret":"Çocuk dik duran ve kare olanlar dâhil tümünü dikdörtgen sayar."},"oyun":{"t":"Dikdörtgen avı","adim":["Mutfakta 5 dikdörtgen bulma yarışı yapın (kutu, kapak, defter...).","İnce uzun olanı da, kare olanı da kabul edin.","Bulduğunuz her birini birlikte sayın."],"soyle":"«Bu da dört köşeli, o da; ikisi de dikdörtgen sayılır.»","isaret":"Çocuk farklı oranlardaki dört köşelileri toplar."},"yaprak":{"t":"Dört köşeliyi işaretle","adim":["Kâğıda dar, geniş ve kare birkaç dört köşeli çizin.","Araya bir üçgen ve daire de serpiştirin.","Çocuk 'dört köşesi olan hepsini' işaretlesin."],"soyle":"«Dört köşesi olan her şey dikdörtgen ailesinden.»","isaret":"Çocuk tüm dikdörtgenleri seçer, üçgen/daireyi bırakır."}},{"order":8,"kazanim":"Kenar Tanıyan","gunluk":{"t":"Kenarları parmakla say","adim":["Kitabın etrafından parmak gezdirip 'bir, iki, üç, dört kenar' deyin.","Üçgen pizza diliminde 'bunun üç kenarı var' diye sayın.","Her gün bir eşyanın düz kenarlarını birlikte sayın."],"soyle":"«Şu düz çizgilere kenar diyoruz, sayalım.»","isaret":"Çocuk bir şeklin kenarlarını tek tek dokunup sayar."},"oyun":{"t":"Kürdanla kenar diz","adim":["Bir şekil kartı çekin.","Çocuk kenarlarının üstüne kürdan dizsin.","Kaç kürdan dizdiğini yüksek sesle saysın."],"soyle":"«Her kenara bir kürdan; kaç tane oldu?»","isaret":"Çocuk kenar sayısı kadar kürdan dizer ve doğru sayar."},"yaprak":{"t":"Noktalı kenarları say","adim":["Üçgen, kare, dikdörtgen resimlerinin her kenarına nokta koyun.","Çocuk noktalara dokunarak kenarları saysın.","Sayıyı kâğıda yazsın ya da söylesin."],"soyle":"«Her noktaya dokun, kaç kenar olduğunu bul.»","isaret":"Çocuk köşeyle karıştırmadan kenar sayısını bulur."}},{"order":9,"kazanim":"Birçok Yönden Karşılaştıran","gunluk":{"t":"Çok yönlü karşılaştırma","adim":["İki kutuyu yan yana koyun.","'Hangisi daha köşeli? Hangisinin kenarı uzun? Hangisi yuvarlanır?' diye sırayla sorun.","Tek bir 'doğru' aramadan farklılıkları birlikte fark edin."],"soyle":"«Bunu kenarına, köşesine, yuvarlanışına göre karşılaştıralım.»","isaret":"Çocuk iki şekli birden fazla özellik üzerinden kıyaslar."},"oyun":{"t":"Aynısı ne farkı ne","adim":["İki şekil seçin.","Kenar sayısı, köşesi, yuvarlak mı düz mü diye eşleştirip ayrıştırın.","Her bulunan ortak ve fark için bir alkış."],"soyle":"«İkisinin de köşesi var ama kenar sayıları farklı.»","isaret":"Çocuk iki şekil için hem benzerlik hem fark söyler."},"yaprak":{"t":"Daire kare farkları","adim":["Yan yana bir daire bir kare çizin.","'Köşesi olan / yuvarlanan / kenarı çok olan hangisi?' diye sorun.","Çocuk farkları söyleyip işaretlesin."],"soyle":"«Kareyle daireyi birçok yönden ayıralım.»","isaret":"Çocuk birden çok özellikte iki şekli ayırt eder."}},{"order":10,"kazanim":"Köşe (Açı) Tanıyan","gunluk":{"t":"Sivri köşeyi bul","adim":["Masanın köşesini tutup 'işte burası köşe, sivri yer' deyin.","Üçgen dilimde 'üç sivri köşesi var' deyip köşelere dokunun.","Her gün bir eşyanın köşelerini birlikte gösterin."],"soyle":"«Kenarların birleştiği sivri yere köşe diyoruz.»","isaret":"Çocuk şeklin köşelerine dokunup tek tek sayar."},"oyun":{"t":"Köşe yakala","adim":["Odada gezip kare ve üçgen eşyalar bulun.","Her birinin köşelerine dokunup sayma oyunu oynayın.","Doğru bulup saydıkça 'köşe ustası!' deyin."],"soyle":"«Bu şeklin kaç köşesi var, dokunarak sayalım.»","isaret":"Çocuk farklı eşyalarda köşeleri bulup sayar."},"yaprak":{"t":"Köşeleri renkle say","adim":["Çeşitli şekiller çizin.","Çocuk her köşeye renkli bir nokta koysun.","Her şeklin kaç köşesi olduğunu söylesin."],"soyle":"«Her köşeye bir nokta koy, sonra say.»","isaret":"Çocuk köşe sayısını doğru belirler."}},{"order":11,"kazanim":"Daha Çok Şekil Tanıyan","gunluk":{"t":"Az bilinen şekiller","adim":["Trafik levhasında altıgeni gösterin.","Yıldız çıkartmasında yıldızı, baklava dilimde eşkenar dörtgeni gösterin.","'Bu da bir şekil, adı...' diye adını söyleyin."],"soyle":"«Buna altıgen diyoruz, altı kenarı var.»","isaret":"Çocuk altıgen, yıldız gibi şekilleri günlük nesnelerde fark eder."},"oyun":{"t":"Yeni şekil eşi","adim":["Altıgen, beşgen, yıldız, kalp kartları yapın.","Çocuk evde benzerini arasın (vida başı = altıgen gibi).","Yeni adı her hatırlayışını kutlayın."],"soyle":"«Vida başı altıgene benziyor, bulabilir misin?»","isaret":"Çocuk az bilinen şekli evdeki bir nesneyle eşler."},"yaprak":{"t":"Altıgeni göster","adim":["Altıgen, beşgen, yıldız çizip adlarını yanlarına yazın.","'Altıgeni göster' deyin.","Çocuk doğru şekle dokunsun."],"soyle":"«Altı kenarlı olan altıgen, hangisi?»","isaret":"Çocuk daha az bilinen şekli adıyla tanır."}},{"order":12,"kazanim":"Şekilleri Doğru Adlandıran","gunluk":{"t":"Özellikten şekli bul","adim":["'Üç kenarı, üç köşesi olan ne olur?' diye bilmece sorun.","Çocuk 'üçgen!' desin.","Sofrada 'dört eşit kenarı olanı bana ver' deyip kareyi seçtirin."],"soyle":"«Adını söylemeden, özelliğinden bul: dört eşit kenar kimde?»","isaret":"Çocuk şekli görünüşten değil özelliklerinden belirler."},"oyun":{"t":"Kim benim","adim":["'Yuvarlağım, köşem yok, kim benim?' gibi ipuçları verin.","Çocuk anlatılan şekli bulsun.","Doğru tahmini 'dedektif gibisin!' diye kutlayın."],"soyle":"«Dört kenarım eşit, dört köşem var; ben kimim?»","isaret":"Çocuk verilen özelliklere uyan şekli seçer."},"yaprak":{"t":"İpucunu şekle bağla","adim":["Bir tarafa 'dört eşit kenar', 'üç köşe' gibi ipuçları yazın.","Diğer tarafa şekilleri çizin.","Çocuk her ipucunu doğru şekle çizgiyle bağlasın."],"soyle":"«Bu ipucu hangi şekli anlatıyor, bağla.»","isaret":"Çocuk özellik ile şekli doğru eşleştirir."}},{"order":13,"kazanim":"Açıyı Farklı Yerlerde Tanıyan","gunluk":{"t":"Açıyı her yerde gör","adim":["Açık kitabın, yarım açık kapının, saat ibrelerinin köşesini gösterin.","'İşte burada bir açı var' deyin.","Açının sadece üçgende değil, açılıp kapanan her yerde olduğunu fark ettirin."],"soyle":"«İki çizgi bir noktada buluşunca açı oluşur, bak.»","isaret":"Çocuk açıyı üçgen dışında farklı yerlerde de tanır."},"oyun":{"t":"Aç kapa açı","adim":["İki kürdanı bir uçtan birleştirin.","Açıp kapatarak 'şimdi açı küçük, şimdi büyük' deyin.","Çocuk makas ya da mandalla aynısını yapsın."],"soyle":"«Kollarını açınca açı büyür, kapatınca küçülür.»","isaret":"Çocuk geniş ve dar açıyı kendisi oluşturup gösterir."},"yaprak":{"t":"Açıyı yuvarlak içine al","adim":["Farklı yerlerde açılar çizin (kapı köşesi, 'L' harfi, saat).","'Burada da açı var' diye gösterin.","Çocuk her açıyı yuvarlak içine alsın."],"soyle":"«Bu köşede de bir açı saklı, bulabilir misin?»","isaret":"Çocuk açıyı değişik bağlamlarda işaretler."}},{"order":14,"kazanim":"Şekli Parçalarıyla Tanımlayan","gunluk":{"t":"Kenar mı köşe mi","adim":["Bir şekle bakıp 'kenarları nerede, köşeleri nerede?' diye sorun.","Parçaları ayrı ayrı gösterin.","Pencere için 'kenarı pervaz, köşesi şurası' deyin."],"soyle":"«Bu şeklin kenarı düz çizgi, köşesi sivri yer.»","isaret":"Çocuk kenar, köşe ve yüzeyi ayrı ayrı adlandırır."},"oyun":{"t":"İki renkli parça","adim":["Şekil kartı verin.","'Kenarlarını mavi, köşelerini kırmızı işaretle' deyin.","Parçaları doğru ayırmasını 'parça ustası!' diye kutlayın."],"soyle":"«Kenarlar mavi, köşeler kırmızı; karıştırma.»","isaret":"Çocuk kenar ve köşeyi farklı renklerle doğru ayırır."},"yaprak":{"t":"Parçayı işaretle","adim":["Bir kare resmine ok çizip 'kenar' ve 'köşe' diye yazın.","İstediğiniz parçayı söyleyin.","Çocuk doğru yeri işaretlesin."],"soyle":"«Şimdi bir köşe göster, sonra bir kenar.»","isaret":"Çocuk şeklin parçalarını tek tek belirler."}},{"order":15,"kazanim":"Üst Üste Koyup Eşliğini Gösteren","gunluk":{"t":"Üst üste tam oturdu mu","adim":["İki özdeş peçeteyi üst üste koyun.","'Tam oturdu mu, taştı mı?' diye baktırın.","İki bardağı dipleri üst üste tutup 'aynı mı' diye kontrol ettirin."],"soyle":"«Üst üste koyunca tıpatıp oturuyorsa aynılar demektir.»","isaret":"Çocuk üst üste koyarak iki şeklin çakışıp çakışmadığını söyler."},"oyun":{"t":"Kardeş mi farklı mı","adim":["İki şekil kesin.","Üst üste koyun; tam örtüşürse 'kardeş', taşarsa 'farklı'.","Çocuk üst üste koyup karar verdikçe kutlayın."],"soyle":"«Kenarları taşmadan oturdu mu? O zaman kardeşler.»","isaret":"Çocuk örtüşmeye bakarak aynı/farklı kararı verir."},"yaprak":{"t":"Şeffaf kâğıtla çakıştır","adim":["Şeffaf kâğıda bir şekil çizin.","Asıl şeklin üstüne koydurun.","Çocuk 'tam çakıştı mı?' diye kontrol etsin."],"soyle":"«Çizgiler tam üst üste geldi mi, bak.»","isaret":"Çocuk üst üste koyarak çakışıklığı bulur."}},{"order":16,"kazanim":"Parçalardan Şekli Tam Kuran","gunluk":{"t":"Köşesi köşesine otursun","adim":["Yapboz yaparken 'bu parçayı tam yerine, köşesi köşesine otursun' deyin.","İki üçgen ekmekle düzgün bir kare oluşturmasını isteyin.","Boşluk ya da taşma kalmamasına birlikte bakın."],"soyle":"«Köşeler birbirine değsin, arada boşluk kalmasın.»","isaret":"Çocuk parçaları boşluksuz, taşmasız birleştirir."},"oyun":{"t":"Tangram doldur","adim":["Kâğıttan üçgen ve kare parçalar kesin.","Verilen bir şekli tam dolduracak biçimde dizdirin.","Boşluksuz ve taşmasız tamamlamasını kutlayın."],"soyle":"«Parçaları öyle yerleştir ki şekil tam dolsun.»","isaret":"Çocuk hedef şekli parçalarla eksiksiz kurar."},"yaprak":{"t":"İçini parçalarla kapla","adim":["Bir şeklin içini boş çizin.","Verdiğiniz küçük parçalarla boşluk kalmadan kaplatın.","Çocuk parçaları tam yerine yerleştirsin."],"soyle":"«İçinde hiç boşluk kalmasın, hepsini doldur.»","isaret":"Çocuk şekli kusursuz, üst üste bindirmeden kurar."}},{"order":17,"kazanim":"Açıyı Temsil Eden","gunluk":{"t":"Kollarla açıyı göster","adim":["Kollarınızı az/çok açıp 'şimdi açım küçük, şimdi büyük' deyin.","Çocuk da kollarıyla aynı açıyı yapsın.","Kapı ve makasla da açının büyüklüğünü temsil edin."],"soyle":"«Kollarımı bu kadar açtım, sen de aynısını yap.»","isaret":"Çocuk istenen büyüklükte bir açıyı vücuduyla temsil eder."},"oyun":{"t":"Açı saati","adim":["İki karton şeridi bir uçtan raptiyeyle birleştirip 'açı saati' yapın.","Siz bir açı söyleyin (küçük/büyük).","Çocuk şeritleri açıp o açıyı göstersin."],"soyle":"«Bana küçük bir açı göster, şimdi büyük bir açı.»","isaret":"Çocuk istenen açıyı araçla kurar."},"yaprak":{"t":"İstenen açıyı çiz","adim":["Bir nokta koyup oradan iki çizgi çizilebileceğini gösterin.","'Küçük açı' ya da 'büyük açı' söyleyin.","Çocuk istediğiniz açıyı çizsin."],"soyle":"«Çizgileri az aç, küçük bir açı olsun.»","isaret":"Çocuk açıyı kendisi çizerek temsil eder."}},{"order":18,"kazanim":"Eşliği Açıklayan","gunluk":{"t":"Tıpatıp aynısını çiz","adim":["Bir şekli kâğıda çizin.","'Bunun tıpatıp aynısını yanına çiz' deyin.","Üst üste koyunca çakışıp çakışmadığını birlikte kontrol edin."],"soyle":"«Aynısını çiz ki üst üste koyunca tam otursun.»","isaret":"Çocuk çakışan bir eş çizip oluşturur."},"oyun":{"t":"İkizini üret","adim":["Bir şekil verin.","'Bunun ikizini çiz ya da kes; üst üste koyunca tam otursun' deyin.","Ürettiği eşin çakıştığını birlikte test edip kutlayın."],"soyle":"«Bir ikiz yap, sonra üst üste koyup deneyelim.»","isaret":"Çocuk çakışacak bir eş üretir."},"yaprak":{"t":"Kareli kâğıtta kopyala","adim":["Kareli kâğıtta bir şekil verin.","Çocuk aynısını başka bir yere kopyalasın.","Sonra çakıştırarak kontrol edin."],"soyle":"«Kareleri sayarak birebir aynısını çiz.»","isaret":"Çocuk çakışan eşi doğru üretir."}},{"order":19,"kazanim":"Şekil Ailelerini Ayırt Eden","gunluk":{"t":"Şekilleri ailelere ayır","adim":["Eşyaları toplarken 'köşesi olanlar bir tarafa, yuvarlaklar bir tarafa' deyin.","'Kare ve dikdörtgen aslında dört köşeliler ailesinden' diye sınıflandırın.","Her aileye birlikte bir ad verin."],"soyle":"«Bunların hepsi dört köşeli, hepsi aynı aileden.»","isaret":"Çocuk şekilleri sınıflarına (aile) göre ayırır."},"oyun":{"t":"Aile kutuları","adim":["'Üçgenler', 'dört köşeliler', 'yuvarlaklar' diye kutular hazırlayın.","Şekil kartlarını doğru kutuya ayırma yarışı yapın.","Her doğru yerleştirmeyi 'sınıflandırma ustası!' diye kutlayın."],"soyle":"«Bu üçgen, üçgenler kutusuna gider.»","isaret":"Çocuk her şekli ait olduğu sınıfa koyar."},"yaprak":{"t":"Aynı aileyi yuvarla","adim":["Karışık şekiller çizin.","'Aynı aileye girenleri yuvarlak içine al' deyin (tüm dört köşeliler bir grup).","Her aile için ayrı bir renk kullansın."],"soyle":"«Dört köşeli olanların hepsini bir yuvarlağa al.»","isaret":"Çocuk şekilleri sınıfına göre gruplar."}},{"order":20,"kazanim":"Özellikleriyle Tanımlayan","gunluk":{"t":"Tüm özelliklerini say","adim":["Bir şekle bakıp 'kaç kenarı, kaç köşesi, kenarlar eşit mi?' diye sorun.","Tüm özelliklerini sırayla saydırın.","Kareyle dikdörtgeni 'farkı ne?' diye özellik özellik karşılaştırın."],"soyle":"«Dört kenarı var, dört köşesi var, kenarları eşit mi bakalım.»","isaret":"Çocuk bir şeklin özelliklerini eksiksiz sıralar."},"oyun":{"t":"Özellik dedektifi","adim":["Çocuk bir şekil kartı alsın.","Kenar sayısı, köşe sayısı, eşit kenarı var mı diye tüm özelliklerini söylesin.","Eksiksiz özellik saymayı kutlayın."],"soyle":"«Bu şeklin bütün özelliklerini bana anlat.»","isaret":"Çocuk bir şekli tüm özellikleriyle tanımlar."},"yaprak":{"t":"Özellik tablosu doldur","adim":["Bir şekil tablosu çizin.","Her şekil için 'kenar sayısı / köşe sayısı / eşit mi' kutucukları olsun.","Çocuk her kutucuğu doldursun."],"soyle":"«Her şeklin kenarını, köşesini tek tek yaz.»","isaret":"Çocuk her şeklin özelliklerini tek tek belirler."}},{"order":21,"kazanim":"Özelliklere Göre Sınıflayan","gunluk":{"t":"Özelliğe göre kümele","adim":["'Hangi şekillerin köşesi var, hangilerinin yok?' diye iki gruba ayırın.","'Eşit kenarlılar' ve 'eşit olmayanlar' diye ayrıştırın.","Şekilleri ortak özelliğe göre kümeleyin."],"soyle":"«Köşesi olanları bir araya, köşesizleri ayrı koy.»","isaret":"Çocuk şekilleri seçilen ortak özelliğe göre kümeler."},"oyun":{"t":"Özelliğe göre tasnif","adim":["'Köşesi olanlar buraya, dört kenarı eşit olanlar şuraya' kutuları kurun.","Bir şekil iki özelliğe de girebileceğini hatırlatın.","Ortak özelliğe göre gruplamayı kutlayın."],"soyle":"«Bu hem köşeli hem eşit kenarlı; iki gruba da girer.»","isaret":"Çocuk şekilleri özellik ölçütüne göre tasnif eder."},"yaprak":{"t":"Başlık altına yerleştir","adim":["'Üç kenarlılar' / 'köşesizler' / 'tüm kenarları eşit olanlar' başlıkları yazın.","Karışık şekiller verin.","Çocuk her şekli doğru başlık altına yerleştirsin."],"soyle":"«Üç kenarı olanları 'üç kenarlılar'a koy.»","isaret":"Çocuk şekilleri özellik sınıfına ayırır."}},{"order":22,"kazanim":"Açı Kavramını Bütünleştiren","gunluk":{"t":"Açıları tek fikirde topla","adim":["Açılıp kapanan her şeyde (makas, kapı, kitap, kollar) 'açı büyüdü mü küçüldü mü?' diye konuşun.","Farklı açıları tek bir 'açı' fikrinde toplayın.","Dik köşeyi 'tam köşe', daha açığını 'geniş' diye adlandırın."],"soyle":"«Hepsi açı; biri dar, biri tam köşe, biri geniş.»","isaret":"Çocuk farklı açıları tek bir 'açı' kavramında birleştirir."},"oyun":{"t":"Açı turu","adim":["Evde dar, dik ve geniş açılar bulun.","'Bu küçük, bu tam köşe, bu geniş' diye sıralama oyunu oynayın.","Açı saatiyle karşılaştırıp sıralamasını kutlayın."],"soyle":"«Bu açı dar, şu tam köşe; küçükten büyüğe dizelim.»","isaret":"Çocuk açıları karşılaştırıp küçükten büyüğe sıralar."},"yaprak":{"t":"Küçükten büyüğe sırala","adim":["Farklı büyüklükte açılar çizin.","Çocuk küçükten büyüğe sıralasın.","'Dik köşeyi' (tam köşeyi) işaretlesin."],"soyle":"«En küçük açıdan başla, sıraya diz; tam köşeyi işaretle.»","isaret":"Çocuk açı kavramlarını birleştirip kıyaslar ve sıralar."}}]},"comp2d":{"code":"Y10","name":"Şekil Birleştirme (İki Boyutlu)","strand":"geometri","levels":[{"order":1,"kazanim":"Şekillerle Tek Tek Oynayan: Temeller","gunluk":{"t":"Şekilleri tanıyalım","adim":["Çocuğa birkaç farklı şekilli nesne verin (kare peçete, üçgen peynir, yuvarlak kapak).","'Bu üçgen, üç köşesi var' deyip parmağıyla kenarlarını birlikte izleyin.","Henüz birleştirmesini beklemeyin; her şekli ayrı ayrı tanısın."],"soyle":"«Bak, bu üçgenin üç köşesi var; hadi kenarlarını izleyelim.»","isaret":"Kare, üçgen ve daireyi ayrı ayrı tanıyıp köşeli ile yuvarlağı ayırt ediyor."},"oyun":{"t":"Şekil kutusu","adim":["Bir kutuya farklı biçimli eşyalar koyun (ekmek tahtası, bardak altlığı, mendil).","Çocuk tek tek çıkarıp evirip çevirsin.","'Bu yuvarlak mı, köşeli mi?' diye sorun."],"soyle":"«Bu yuvarlak mı, yoksa köşeli mi?»","isaret":"Nesneleri elleyerek yuvarlak ve köşeli diye doğru ayırabiliyor."},"yaprak":{"t":"Köşeleri say boya","adim":["Kâğıda büyük bir üçgen, bir kare ve bir daire çizin.","Çocuk her birinin köşelerini parmağıyla saysın.","Sonra her şeklin üstünden boyasın."],"soyle":"«Bu şeklin kaç köşesi var, sayalım ve boyayalım.»","isaret":"Köşeleri olan şekilleri yuvarlaktan ayırıp köşe sayısını söyleyebiliyor."}},{"order":2,"kazanim":"Parçaları Bir Araya Getiren","gunluk":{"t":"Kenarlar öpüşsün","adim":["İki bisküvi ya da iki peçeteyi yan yana getirin.","'Kenarları öpüşsün, birbirine değsin' deyin.","Çocuk iki parçayı kenar kenara dokunduruyorsa başarmıştır; resim olması gerekmez."],"soyle":"«Bu iki parçanın kenarları birbirine değsin, öpüşsün.»","isaret":"İki parçayı boşluksuz, kenar kenara getirip birleştirebiliyor."},"oyun":{"t":"Yan yana koy","adim":["Bir tepside iki kibrit kutusu/kare verin.","'Birbirine yapıştır gibi yan yana koy' deyin; boşluk kalırsa birlikte yaklaştırın.","Sonra üçüncü bir parçayı 'buna da değdir' diye ekleyin."],"soyle":"«Aralarında boşluk kalmasın; birbirine değdirelim.»","isaret":"Parçaları boşluk bırakmadan yan yana dizip üçüncü parçayı da ekliyor."},"yaprak":{"t":"İki kareyi birleştir","adim":["Kâğıda iki kare çizin, aralarında küçük boşluk bırakın.","Çocuk ikisini birleştiren çizgiyi çizip 'değdirsin'.","Düz, uzun kenarlı parçalarla başlayın; hizalaması en kolayıdır."],"soyle":"«İki kareyi birbirine değecek şekilde birleştirelim.»","isaret":"İki şekli kenarlarından birleştirip aralarındaki boşluğu kapatıyor."}},{"order":3,"kazanim":"Resim Yapan","gunluk":{"t":"Şekillerle ev","adim":["Kahvaltıda peynir ve ekmekle 'ev yapalım' deyin.","Kare ekmek duvar, üçgen peynir çatı olsun.","Çocuk her parçaya bir görev versin ('bu çatı, bu kapı') ve size anlatsın."],"soyle":"«Hangi şekil çatı olsun, hangisi duvar; bana evini anlat.»","isaret":"Farklı şekilleri birleştirip tanınır bir resim (ev) kuruyor ve parçaları adlandırıyor."},"oyun":{"t":"Bana bir balık yap","adim":["Birkaç farklı şekilli karton verin.","'Bana bir balık (ya da çiçek) yap' deyin; çocuk parçaları seçip dizsin.","Önce bir örnek gösterip kopyalatın, sonra yalnız sözle isteyin."],"soyle":"«Bu parçalarla bana bir balık yapabilir misin?»","isaret":"Şekilleri seçip dizerek istenen resmi oluşturup parçaları adlandırıyor."},"yaprak":{"t":"Şekillerden resim","adim":["Kâğıttan bir kare, bir üçgen, bir daire kesip verin.","Çocuk bunları yapıştırarak tanınır bir resim kursun (ev, insan, kayık).","Altına ne yaptığını çizsin ya da söylesin."],"soyle":"«Bu şekilleri birleştirip ne yapabilirsin?»","isaret":"Birkaç şekli birleştirerek anlamlı, tanınır bir resim oluşturuyor."}},{"order":4,"kazanim":"Basit Şekilleri Parçalarına Ayıran","gunluk":{"t":"Kareden iki üçgen","adim":["Bir dilim ekmeği/tostu köşegeninden ikiye kesin.","'Bak, bir kareden iki üçgen çıktı' deyin.","Sandviç/pizzayı belirgin çizgisinden böldürüp 'kaç parça oldu?' diye sorun."],"soyle":"«Bak, bir kareyi kesince iki üçgen oldu!»","isaret":"Bir bütün şeklin kesilince hangi parçalara ayrıldığını söyleyebiliyor."},"oyun":{"t":"Çizgiyi kes","adim":["Bir kâğıda kalın bir çizgiyle ortadan bölünmüş bir kare ya da ev çizin.","Çocuk çizgiyi parmağıyla izleyip 'içinde hangi parçalar var' desin.","Sonra makasla o çizgiden kessin."],"soyle":"«Bu çizgiyi kesersek içinden hangi parçalar çıkar?»","isaret":"Belirgin çizgiyi takip ederek şeklin hangi parçalardan oluştuğunu görüp kesiyor."},"yaprak":{"t":"Kaç parça var","adim":["Üstünde tek kalın çizgi olan basit şekiller verin (ikiye bölünmüş dikdörtgen).","Çocuk her şeklin kaç parçadan yapıldığını çizgiyi takip ederek söylesin.","Çizgi belirgin olduğu için her seferinde başarsın."],"soyle":"«Bu çizgiye bakınca şekil kaç parçaya ayrılmış?»","isaret":"Belirgin çizgiye bakarak şeklin kaç parçaya ayrıldığını söyleyebiliyor."}},{"order":5,"kazanim":"Şekil Oluşturan","gunluk":{"t":"Hangi parça oturur","adim":["Pizza/poğaça paylaşırken 'bu boşluğa hangi parça tam oturur?' diye sorun.","Çocuk parçayı koymadan ÖNCE tahmin etsin.","Oturmazsa 'çevirsek olur mu?' deyip döndürmeyi hatırlatın, sonra deneyip doğrulasın."],"soyle":"«Koymadan önce düşün: bu boşluğa hangi parça tam oturur?»","isaret":"Hedef boşluğa hangi parçanın uyacağını önceden tahmin edip gerekirse döndürerek yerleştiriyor."},"oyun":{"t":"Boşluğu doldur","adim":["Kâğıda boş bir altıgen (ya da yıldız) anahattı çizin.","Çocuk onu üçgen/kare kâğıt parçalarıyla doldursun.","Her parçadan önce 'sence sığar mı, neden?' diye tahmin etsin; sonra aynı boşluğu farklı parçalarla da doldursun."],"soyle":"«Bu boşluğa hangi parçalar sığar, önce tahmin edelim.»","isaret":"Hedef şekli parçalarla, önceden düşünüp tahmin ederek tam dolduruyor."},"yaprak":{"t":"Önce düşün yerleştir","adim":["İçi boş bir şekil şablonu verin.","'Koymadan önce düşün: hangisi sığar?' deyin; çocuk parmağıyla nereye ne geleceğini göstersin.","Sonra parçayı yerleştirsin; tıkanırsa içine parça sınırlarını hafifçe çizip ipucu verin."],"soyle":"«Önce parmağınla göster, sonra parçayı yerine koy.»","isaret":"Hedef şekli, parçaları önce zihinde eşleştirip sonra yerleştirerek oluşturuyor."}},{"order":6,"kazanim":"Parça Değiştirerek Oluşturan","gunluk":{"t":"Yerine ne koyabilirim","adim":["Sofrada 'şu iki üçgen peyniri birleştirsem hangi şekil olur?' diye sorun.","'Bir karenin yerine kaç üçgen koyabilirim?' diye düşündürün.","Çocuk bir parça takımını, aynı yeri kaplayan başka takımla değiştirebildiğini fark etsin."],"soyle":"«Bir karenin yerine kaç üçgen koyarsak aynı yeri kaplar?»","isaret":"Bir parça grubunu, aynı alanı kaplayan başka parçalarla değiştirebiliyor."},"oyun":{"t":"Değiş tokuş","adim":["İki üçgen kâğıdı birleştirip bir kare yapın.","'Bu karenin yerine başka ne koyabiliriz, yine aynı yeri kaplar mı?' diye sorun.","Bir parçayı çıkarıp yerine eşit parçalar koydurun."],"soyle":"«Bu karenin yerine başka parçalar koysak yine aynı yeri kaplar mı?»","isaret":"Bir şeklin yerine, aynı yeri kaplayan eşdeğer parçaları koyabiliyor."},"yaprak":{"t":"Aynı yeri kapla","adim":["Kâğıtta bir kare ve iki üçgen verin.","Çocuk iki üçgeni üst üste koyarak karenin yerini tam kapladığını göstersin.","'Aynı şekli daha az ya da daha çok parçayla yapabilir misin?' diye sorun."],"soyle":"«İki üçgen, karenin yerini tam kaplıyor mu bakalım.»","isaret":"Bir şekli farklı sayıda eşdeğer parçayla yerine koyarak oluşturabiliyor."}},{"order":7,"kazanim":"Yardımla Şekli Parçalarına Ayıran","gunluk":{"t":"Gizli şekli bul","adim":["Çocuğa çizgisiz bir bileşik şekil gösterin (masadaki bir desen).","'Bunun içinde tanıdık bir şekil gizli mi, bir kare görebilir misin?' diye sorun.","İpucu vererek gizli parçaları buldurun."],"soyle":"«Bunun içinde gizli bir kare görebilir misin?»","isaret":"Çizgisiz bir bileşik şeklin içinde gizli tanıdık şekilleri (yardımla) bulabiliyor."},"oyun":{"t":"Köşedeki üçgen","adim":["Birkaç parçadan oluşmuş çizgisiz bir figür kurun.","Zorlanırsa 'şu köşede bir üçgen var mı?' diye yol gösterin, bulduğu parçanın sınırını birlikte çizin.","Sonra desteği azaltıp kalanları kendi bulsun."],"soyle":"«Şu köşede gizli bir üçgen var mı, birlikte bakalım.»","isaret":"İpucuyla başlayıp giderek tek başına bileşik şeklin parçalarını ayırabiliyor."},"yaprak":{"t":"Sınırları çiz","adim":["Çizgisi olmayan, içinde 2-3 tanıdık şekil gizli basit bir bileşik resim verin.","Çocuk silinebilir kalemle gizli şekillerin sınırlarını çizerek ayırsın.","İlk parçayı siz gösterin, gerisini bırakın."],"soyle":"«Gizli şekillerin sınırlarını çizerek onları ayıralım.»","isaret":"Çizgisiz bileşik bir resimde gizli şekillerin sınırlarını çizip (yardımla) ayırabiliyor."}},{"order":8,"kazanim":"Kurduğu Birimi Tekrarlayan","gunluk":{"t":"Tekrar eden kalıp","adim":["Karo/fayans ya da battaniye desenini gösterin.","'Şu küçük şekil tekrar tekrar yapılmış; hangi parça birim olmuş?' diye sorun.","Çocuk bir parça-grubunu tek bir 'kalıp' gibi görüp tekrarını fark etsin."],"soyle":"«Bu desende tekrar eden kalıp hangisi, bulabilir misin?»","isaret":"Bir desende tekrar eden bileşik birimi (kalıbı) tek bir blok olarak görebiliyor."},"oyun":{"t":"Kalıbı çoğalt","adim":["İki kâğıt parçasından bir 'kalıp' yapın (kare + üçgen = ok).","'Bunu tek bir blok gibi düşün, aynısından bir tane daha yap' deyin.","Çocuk kalıbı yineleyerek bir şerit/desen oluştursun, kaç kalıp kullandığını saysın."],"soyle":"«Bu kalıbı tek blok gibi düşün; aynısından yan yana yapalım.»","isaret":"Bileşik bir birimi tek blok gibi alıp tekrarlayarak desen kuruyor ve birimleri sayıyor."},"yaprak":{"t":"Bordür yap","adim":["Bir bileşik birim çizin (iki üçgen bir baklava).","'Bunu yan yana tekrar ederek bir bordür yap' deyin.","'Kaç tane kalıp kullandın?' diye birimleri saydırın."],"soyle":"«Bu kalıbı yan yana tekrar edip bir bordür yapalım.»","isaret":"Bileşik bir birimi yan yana tekrarlayarak bordür/desen kuruyor ve birim sayısını söylüyor."}},{"order":9,"kazanim":"İmgelemle Şekli Parçalarına Ayıran","gunluk":{"t":"Gözünde ayır","adim":["Eline hiçbir şey vermeden 'gözünü kapat' deyin.","'Bir altıgeni kafanda parçalara ayır; kaç farklı yol buldun?' diye sorun.","Çocuk şekli zihninde, ellemeden, birden çok şekilde bölebilsin."],"soyle":"«Gözünü kapat; bu altıgeni kafanda kaç farklı parçaya ayırabilirsin?»","isaret":"Bir şekli zihinde, dokunmadan, birden çok farklı yolla parçalara ayırabiliyor."},"oyun":{"t":"Elleme yok ayır","adim":["Çizgisiz bir şekil kartı gösterip 'bunu kafanda hangi parçalara ayırırsın, elleme yok' deyin.","Çocuk önce sözle anlatsın ('iki yamuk' ya da 'altı üçgen'); en az iki yol istesin.","Sonra gerçek parçalarla doğrulasın."],"soyle":"«Ellemeden anlat: bu şekli kaç farklı yolla parçalara bölebilirsin?»","isaret":"Bir şekli ellemeden, en az iki farklı yolla zihinde ayırıp sözle anlatabiliyor."},"yaprak":{"t":"Düşün sonra kontrol et","adim":["Tanıdık bir şekil çizin.","'Koymadan, dokunmadan: bunu kaç farklı şekilde parçalara ayırabilirsin?' diye sorun.","Çocuk yolları söyleyip ya da çizip sonra gerçek parçalarla kontrol etsin."],"soyle":"«Önce kafanda ayır, sonra parçalarla kontrol et.»","isaret":"Şekli önce zihinde farklı yollarla ayırıp sonra parçalarla doğrulayabiliyor."}},{"order":10,"kazanim":"Birimden Birim Kuran","gunluk":{"t":"Birimden desene","adim":["Bal peteği, örme atkı ya da fayans desenini gösterin.","'Önce küçük birimini kuralım, sonra o birimlerden koca deseni yapalım' deyin.","Küçük parça → birim → birimlerden desen sırasını birlikte fark edin."],"soyle":"«Önce küçük birimi kuralım, sonra birimlerden koca deseni yapalım.»","isaret":"Küçük parçaların önce bir birim, sonra o birimlerin büyük bir deseni oluşturduğunu görüyor."},"oyun":{"t":"Altıgenlerden döşeme","adim":["Önce 6 üçgen kâğıttan bir altıgen kurdurun.","'Şimdi bu altıgenlerden birkaç tane yapıp yan yana getir' deyin.","'Kaç üçgen bir altıgen, kaç altıgen tüm desen?' diye katmanları ilişkilendirin."],"soyle":"«6 üçgen bir altıgen yaptı; şimdi altıgenlerden koca bir döşeme yapalım.»","isaret":"Önce parçalardan birim, sonra birimlerden büyük desen kurup iki katmanı ilişkilendiriyor."},"yaprak":{"t":"Birimleri çoğalt","adim":["Bol özdeş parçayla çocuk önce tek bir birim kursun (bir altıgen).","Sonra o birimi tekrarlayarak büyük bir desen oluştursun.","Altına 'bir birimde kaç parça var, kaç birim kullandım?' yazsın."],"soyle":"«Bir birimde kaç parça var, kaç birim kullandın; yazalım.»","isaret":"Parçalardan bir birim kurup onu çoğaltarak desen yapıyor ve iki katmanı sayıyor."}},{"order":11,"kazanim":"Katman Katman Parçalara Ayıran","gunluk":{"t":"Önce büyük sonra küçük","adim":["Karmaşık bir fayans/örgü desenine bakın.","'Önce büyük parçaları gör (bunlar altıgen), sonra her birinin içine bak (her biri altı üçgenden)' deyin.","Toplam küçük parçayı 'kaç altıgen × kaç üçgen' diye birlikte hesaplayın."],"soyle":"«Önce büyük altıgenleri sayalım, sonra her birinin içindeki üçgenleri.»","isaret":"Deseni önce büyük birimlere, sonra içindeki küçük parçalara ayırıp çarpımla toplamı buluyor."},"oyun":{"t":"İki renkli işaretle","adim":["Kurulu karmaşık bir deseni gösterin.","Çocuk önce ÜST birimleri (büyük parçaları) bir renkle işaretlesin.","Sonra 'her büyük parça içinde nelerden yapılmış?' diye başka renkle alt-parçaları çizip çarpımla toplamı bulsun."],"soyle":"«Büyük parçaları bir renge, içlerindeki küçükleri başka renge boyayalım.»","isaret":"Büyük birimleri ve içlerindeki alt-parçaları ayrı renklerle ayırıp çarparak toplamı buluyor."},"yaprak":{"t":"Çarp da bul","adim":["Düzenli bir döşeme resmi verin.","Çocuk önce büyük birimlerin sayısını, sonra her birimdeki küçük parça sayısını yazsın.","İkisini çarparak toplam küçük parçayı bulsun."],"soyle":"«Kaç büyük birim, her birinde kaç küçük parça; çarpıp toplamı bulalım.»","isaret":"Büyük birim sayısı ile birim başına parça sayısını çarparak toplam parçayı buluyor (tek tek saymadan)."}}]},"disembed":{"code":"Y11","name":"Gömülü Şekilleri Ayırt Etme","strand":"geometri","levels":[{"order":1,"kazanim":"Saklı Şekli Sezen: Temeller","gunluk":{"t":"Zeminden tek nesne","adim":["Mutfakta tek bir nesneyi fondan ayırt ettirin.","'Bu kırmızı bardağı masanın üstünde bulup parmağınla göster' deyin.","Tabağın içindeki tek bir bezelyeyi de işaret ettirerek aynı 'şekli-zeminden-ayırma' kasını çalıştırın."],"soyle":"«Bu kırmızı bardağı masada bulup parmağınla gösterir misin?»","isaret":"Kalabalık bir zemin içinden tek bir bütünü seçip parmağıyla gösterebiliyor."},"oyun":{"t":"Battaniyenin altında ne var","adim":["Bir oyuncağın yarısını yastıkla/örtüyle örtün.","Görünen kısımdan oyuncağı bildirsin.","Sonra tamamen çıkarıp doğrulayın; her turda farklı nesneyi yarı gizleyin."],"soyle":"«Yarısı görünüyor; sence bu hangi oyuncak?»","isaret":"Bir nesnenin yalnızca görünen kısmından onun ne olduğunu söyleyebiliyor."},"yaprak":{"t":"İçindeki noktayı bul","adim":["Kâğıda iri, tek bir şekil çizin (büyük bir daire) ve içine kalın bir nokta koyun.","'Dairenin içindeki noktayı parmağınla bul' deyin.","Tek hedefli olduğu için her seferinde başarsın."],"soyle":"«Dairenin içindeki noktayı parmağınla bulabilir misin?»","isaret":"Büyük bir bütünün içindeki tek bir detayı seçip gösterebiliyor."}},{"order":2,"kazanim":"Üst Üste Şekilleri Ayırt Eden","gunluk":{"t":"Öndeki ile arkadaki","adim":["Çamaşır asarken üst üste binmiş iki çorabı gösterin.","'Hangisi önde, hangisi arkada?' diye sorun.","'Alttakini tek başına çekip çıkar' deyin."],"soyle":"«Hangisi önde, hangisi arkada; alttakini tek başına çekebilir misin?»","isaret":"Üst üste binen iki nesneyi ön/arka diye ayırıp alttakini tek başına çekebiliyor."},"oyun":{"t":"Çatal kaşık yığını","adim":["3-4 çatal kaşığı hafifçe üst üste atın.","'En üstteki hangisi, en alttaki hangisi?' diye sorun.","Sırayla teker teker ayırttırın; her turda farklı şekilde üst üste bindirin."],"soyle":"«En üstteki hangisi, en alttaki hangisi; tek tek ayıralım.»","isaret":"Üst üste binen birkaç nesneyi en üstten en alta doğru tek tek ayırabiliyor."},"yaprak":{"t":"Kesişen iki şekil","adim":["Kâğıda birbirini kesen iki büyük şekil çizin (bir daire ile bir üçgen kesişsin).","Daireyi mavi, üçgeni kırmızı parmakla (veya boyayla) tek tek dolaştırın.","Çizgiler kesişse de her şeklin kendi yolu olduğunu görsün."],"soyle":"«Çizgiler kesişse de daireyi mavi, üçgeni kırmızı dolaşalım.»","isaret":"Birbiriyle örtüşen iki şeklin sınırlarını ayrı ayrı izleyebiliyor."}},{"order":3,"kazanim":"Şekil İçinde Şekil Bulan","gunluk":{"t":"İç içe kâseler","adim":["Sofrada iç içe geçmiş kapları gösterin.","'Büyük kâsenin içinde küçük kâse var; küçüğü çıkar' deyin.","'Sonra ortancayı bul' diyerek katman katman ayırttırın."],"soyle":"«Büyük kâsenin içinde küçük kâse var; küçüğü çıkarabilir misin?»","isaret":"İç içe geçmiş kapları en içtekinden başlayarak tek tek ayırabiliyor."},"oyun":{"t":"Kutu içinde kutu","adim":["Farklı boy 3 kutuyu iç içe yerleştirin.","Çocuk en içtekinden başlasın.","'Bu kaçıncı, içinde daha var mı?' diyerek katman katman ayırsın."],"soyle":"«En içteki kutuyu bul; içinde daha var mı?»","isaret":"İç içe kutuları katman katman, en içten dışa doğru ayırabiliyor."},"yaprak":{"t":"İçteki kareyi boya","adim":["Kâğıda bir kare çizin, tam ortasına daha küçük bir kare çizin (çerçeve gibi).","'İçteki kareyi yeşile, dıştakini sarıya boya' deyin.","İç içe iki sınırı ayrı ayrı görüp boyasın."],"soyle":"«İçteki kareyi yeşile, dıştakini sarıya boyayalım.»","isaret":"Şekil-içinde-şekil olan iki sınırı ayrı ayrı görüp farklı boyayabiliyor."}},{"order":4,"kazanim":"Gizlenmiş Düzenleri Bulan","gunluk":{"t":"Desende saklı şekil","adim":["Çiçekli/dolaplı bir desen gösterin (örtü, perde).","'Şu desenin içinde bir kalp/üçgen görebiliyor musun?' deyin.","Bulduğu şekli birlikte parmakla çizin."],"soyle":"«Bu desenin içinde gizli bir kalp görebiliyor musun?»","isaret":"Kalabalık bir arka plandan tek bir gizli şekli sıyırıp parmakla izleyebiliyor."},"oyun":{"t":"Çizgide saklı kare","adim":["Kareli/çizgili bir kâğıt ya da fayans alın.","Kalemle, var olan çizgileri paylaşan gizli bir kare oluşturun.","'Bu çizgilerin içinde benim sakladığım şekli bulabilir misin?' diye arattırın."],"soyle":"«Bu çizgilerin içinde sakladığım şekli bulabilir misin?»","isaret":"Var olan çizgileri paylaşan, arka plana karışmış gizli şekli bulabiliyor."},"yaprak":{"t":"Çizgi paylaşan üçgen","adim":["Birkaç çizginin kesiştiği karışık bir taslak çizin.","İçine kenarları başka çizgilerle paylaşımlı bir üçgen gizleyin.","Çocuk gizli üçgeni renkli kalemle dolaşıp çıkarsın."],"soyle":"«Kenarları başka çizgilerle paylaşan gizli üçgeni bulup dolaşalım.»","isaret":"Kenarlarını başka çizgilerle paylaşan gömülü bir şekli ayırıp işaretleyebiliyor."}},{"order":5,"kazanim":"Tüm Saklı Şekilleri Bulan","gunluk":{"t":"Çok katmanlı şekil avı","adim":["Karmaşık bir görsel önünde durun (halı deseni, tuğla duvar, market rafı).","'İçinde kaç tane dikdörtgen, kaç tane üçgen saklı?' diye sorun.","'Hepsini sırayla göster' deyip tek tek sıyırttırın."],"soyle":"«Bu desende kaç dikdörtgen, kaç üçgen saklı; hepsini sırayla göster.»","isaret":"Çok sayıda örtüşen yapıyı tek tek ayırıp tür tür sayabiliyor."},"oyun":{"t":"Saklı şekil şampiyonası","adim":["Kâğıda çok sayıda çizgiyle iç içe, üst üste birkaç şekil çizin (üçgen + kare + daire).","Süre tutarak çocuk her şekli bulup farklı renkle işaretlesin.","Sonra 'kim daha çok buldu' diye birlikte sayın."],"soyle":"«Süre başladı; her gizli şekli bulup farklı renkle işaretle!»","isaret":"Yoğun, çok katmanlı bir çizimde gizli şekillerin hepsini bulup ayrı renklerle ayırabiliyor."},"yaprak":{"t":"Gizli şekiller tablosu","adim":["Birkaç şeklin kenarlarını paylaşarak iç içe geçtiği yoğun bir çizim verin.","Altına '3 üçgen, 2 kare bul' yazın.","Çocuk her birini ayrı renkle dolaşarak çok katmanlı yapıyı tam çözsün."],"soyle":"«Bu yoğun çizimde 3 üçgen ve 2 kareyi ayrı renklerle bulalım.»","isaret":"Kenarlarını paylaşan çok katmanlı şekillerin tümünü eksiksiz bulup ayırabiliyor."}}]},"shape3d":{"code":"Y12","name":"Üç Boyutlu Şekiller","strand":"geometri","levels":[{"order":1,"kazanim":"Cisimleri Algılayan: Temeller","gunluk":{"t":"Evir çevir keşfet","adim":["Elinize geçen top, kutu, konserve kutusu, dondurma külahı gibi nesneleri çocuğa verin.","Evirip çevirmesine, yuvarlamasına, üst üste koymasına izin verin.","Siz de 'bak, bu yuvarlanıyor', 'bu duruyor, köşesi var' diye eşlik edin; amaç ad öğretmek değil, nasıl davrandığını elle keşfettirmek."],"soyle":"«Bunu yuvarla bakalım; bu duruyor mu, yoksa yuvarlanıyor mu?»","isaret":"Çocuk nesneleri elleyip hangisinin yuvarlandığını, hangisinin durduğunu fark ediyor."},"oyun":{"t":"Rampadan bırak","adim":["Bir kitabı ya da tepsiyi hafifçe eğip rampa yapın.","Topu, kutuyu, salça kutusunu sırayla bırakın.","'Hangisi kaydı, hangisi durdu?' diye birlikte izleyip her seferinde gülüşün."],"soyle":"«Hadi bunu rampadan bırakalım; kayacak mı, duracak mı?»","isaret":"Çocuk hangi nesnenin yuvarlanıp hangisinin durduğunu izleyerek görüyor."},"yaprak":{"t":"Yuvarlananı ver","adim":["Bir sepete üç dört farklı biçimli nesne koyun (top/misket, kutu, külah).","'Yuvarlananı bana ver' deyin, sonra 'üst üste konanı ver' deyin.","Yanlış-doğru yok; her doğru hareketi 'evet, bu yuvarlandı!' diye sevinçle adlandırın."],"soyle":"«Bana yuvarlanan bir şey ver; şimdi de üst üste konabilen bir şey.»","isaret":"Çocuk nesneleri davranışına göre (yuvarlanan/duran) seçip verebiliyor."}},{"order":2,"kazanim":"Tanıdık Cisimleri Tanıyan","gunluk":{"t":"Topu bul, kutuyu bul","adim":["Market poşetini birlikte boşaltırken 'topu bul' (portakal), 'kutuyu bul' (kraker kutusu) diye seçtirin.","Çocuk günlük adıyla (top, kutu) söylesin.","Yanına matematiksel adını sıkıştırmadan ekleyin: 'evet, top; buna küre de denir, her yeri yuvarlak.'"],"soyle":"«Poşetten topu çıkarır mısın? Aynen, buna küre de denir.»","isaret":"Çocuk tipik 3B nesneleri (top, kutu) adıyla tanıyıp seçebiliyor."},"oyun":{"t":"Torbadan çıkar","adim":["Bir torbaya top, küp/zar, kutu, salça kutusu koyun.","'Bana yuvarlağı/topu çıkar', 'şimdi kutuyu çıkar' diye sırayla istetin.","Aynı şeklin farklı boyunu kullanın (misket ile portakal, zar ile tahta küp) ki tanıma görünüşe değil biçime bağlansın."],"soyle":"«Torbadan bana bir top çıkar; şimdi de bir kutu çıkar.»","isaret":"Çocuk farklı boylardaki aynı tip cismi biçimine göre tanıyabiliyor."},"yaprak":{"t":"Top gibi / kutu gibi","adim":["Sofrada ya da oyuncak köşesinde nesneleri ayırttırın.","'Top gibi olanları' bir tabağa, 'kutu gibi olanları' başka tabağa koysun.","Her ayırdığında 'bu nasıl, sivri mi yuvarlak mı?' diye günlük bir nitelikle betimletin; iki şekille başlayıp başarıyı garantileyin."],"soyle":"«Top gibi olanları buraya, kutu gibi olanları şuraya ayıralım.»","isaret":"Çocuk nesneleri 'top gibi' ve 'kutu gibi' diye iki gruba ayırabiliyor."}},{"order":3,"kazanim":"Üç Boyutlu Cisimleri Tanıyan","gunluk":{"t":"Bu cismin yüzü ne?","adim":["Bir konserve kutusunu (silindir) ya da külahı eline verip 'bu hangi cisim?' diye sorun.","Parmağıyla altını gösterip 'peki bu yüzü hangi düz şekil?' deyin (silindir tabanı → daire).","'Silindir bir cisim; yüzlerinden biri daire' diyerek düz şekil ile cisim ayrımını sesli yapın."],"soyle":"«Bu silindir bir cisim; alt yüzü hangi düz şekle benziyor?»","isaret":"Çocuk bir cismin adını söyleyip yüzlerinin hangi düz şekil olduğunu eşleyebiliyor."},"oyun":{"t":"Yüzü kare olan hangisi?","adim":["Birkaç katıyı masaya dizin (kutu, salça kutusu, külah, zar).","Siz bir yüz şekli söyleyin ('yüzü kare olan hangisi?', 'tabanı daire olan hangisi?').","Çocuk doğru cismi elde döndürerek bulsun; sonra sıra ona geçsin, o tarif etsin siz bulun."],"soyle":"«Yüzü kare olan cismi bulabilir misin? Şimdi sen bir yüz tarif et.»","isaret":"Çocuk verilen bir yüz şekline göre doğru 3B cismi bulabiliyor."},"yaprak":{"t":"Yüzü eşleştir","adim":["Bir kâğıda büyük bir daire, bir kare, bir üçgen çizin.","Çocuk evden bulduğu cisimleri (kutu → kare, konserve → daire) bu şekillerin yanına götürüp yüzünü eşleştirsin.","'Silindiri bul, koniyi bul' küçük oyunuyla bitirip en az bir cismi matematiksel adıyla söylemesini kutlayın."],"soyle":"«Bu cismin yüzü hangi şekle uyuyor? Yanına götürüp eşleştir.»","isaret":"Çocuk bir cismin yüzünü doğru düz şekille eşleştirebiliyor."}},{"order":4,"kazanim":"Cisimlerin Yüzlerini Sayan","gunluk":{"t":"Yüzleri say","adim":["Eline bir mukavva kutu (kraker/diş macunu kutusu) verin.","'Kaç yüzü var, her yüze bir kez dokunarak say' deyin.","Kutuyu birlikte sistemli çevirin: 'üst-alt, ön-arka, sağ-sol'; arka yüzler atlanmasın, hiçbir yüz iki kez sayılmasın."],"soyle":"«Her yüze bir kez dokunarak sayalım; arka tarafı da unutma.»","isaret":"Çocuk bir kutunun tüm yüzlerini tekrarsız ve eksiksiz sayabiliyor."},"oyun":{"t":"İşaretle ve say","adim":["Saydığınız her yüze küçük bir çıkartma ya da renkli bant yapıştırın.","'İşaretlediğin yüzü bir daha sayamazsın' deyin.","Sonunda çıkartmaları sayıp doğrulayın ('altı yüz, hepsi dikdörtgen'); küp/zarla ve farklı bir kutuyla tekrarlayın."],"soyle":"«Saydığın her yüze bir bant yapıştır; sonunda kaç bant var sayalım.»","isaret":"Çocuk yüzleri işaretleyerek her birini tam bir kez sayabiliyor."},"yaprak":{"t":"Açıp say, katla","adim":["Bir kâğıt kutuyu açıp (açınımını çıkarıp) düz serin.","Yüzleri birlikte sayın, sonra tekrar katlayıp 'kapalıyken de aynı altı yüz var' diye gösterin.","Kolaylaştırmak için önce sadece üst-alt, sonra yan yüzleri ayrı saydırın; her yüzü tam bir kez saymayı övün."],"soyle":"«Kutuyu açtık, yüzleri sayalım; katlayınca da aynı yüzler var.»","isaret":"Çocuk bir katının yüz sayısını (yüz-katı ilişkisi) doğru söyleyebiliyor."}},{"order":5,"kazanim":"Parçalardan Üç Boyutlu Şekil Kuran","gunluk":{"t":"Önce kestir, sonra kur","adim":["Boşalan kibrit/ilaç kutularını, pipet ya da kürdanları kullanın.","'Bir küp yapacağız, sence kaç tane kare yüz gerekir?' diye ÖNCE sayıyı kestirtin (6).","Sonra birlikte kurun; köşeler dik mi, her yüz birleşti mi, boşluk kaldı mı diye çocuğa denetletin."],"soyle":"«Küp için kaç kare yüz gerekir dersin? Hadi kurup kontrol et.»","isaret":"Çocuk bir cismin kaç yüzü olacağını önceden kestirip kurarak doğruluyor."},"oyun":{"t":"Modelden kur","adim":["Karton kareleri bantla ya da geçmeli oyuncak parçalarını kullanarak kapalı bir küp/kutu kurun.","Modeli (gerçek bir kutu) yanına koyup 'kaç yüz, nasıl birleşmiş?' diye inceletin, sonra modelsiz kurdurun.","Bir küpün haç biçimli açınımını kesip katlatarak 'bu katlanınca küp olur mu?' diye sınatın."],"soyle":"«Bu açınım katlanınca küp olur mu? Hadi katlayıp görelim.»","isaret":"Çocuk bir 3B şekli modelden ya da açınımdan kurabiliyor/belirleyebiliyor."},"yaprak":{"t":"Özellikleri yaz","adim":["Bir cismi (kutu/küp) verip 'adı ne, kaç yüzü, kaç köşesi var?' diye birden çok özelliğini saydırın.","Küçük bir kâğıda yazdırın (yüz / kenar / köşe).","Birkaç açınım kartı gösterip 'hangisi katlanınca küp olur?' diye seçtirin; 'bu özelliklerle bu hangi cisim?' diye doğrulatın."],"soyle":"«Bu cismin adı, yüz sayısı, köşe sayısı ne? Hepsini yazalım.»","isaret":"Çocuk bir cismi yüz/kenar/köşe gibi birden çok özelliğiyle belirleyebiliyor."}},{"order":6,"kazanim":"Cisimleri Adlandırıp Tanımlayan","gunluk":{"t":"Ortak özelliği bul","adim":["Evdeki katıları masaya toplayın.","Özellikten cisme gidin: 'bütün yüzleri kare olan hangisi?' (küp), 'hiç düz yüzü olmayan, sadece yuvarlanan hangisi?' (top/küre).","Tek bir nesneyi değil ortak özelliği soruyorsunuz; çocuk gerekçesini söylesin: 'neye göre buldun?'"],"soyle":"«Bütün yüzleri kare olan cisimleri bulabilir misin? Neye göre buldun?»","isaret":"Çocuk cisimleri ortak bir özelliğe göre belirleyip gerekçelendirebiliyor."},"oyun":{"t":"Kurala göre ayır","adim":["Cisimleri tabaklara ya da iplerle ayırttırın: 'prizma gibi olanları bir kenara ayır; neden prizma?' (iki ucu aynı, yanları dikdörtgen).","Ölçütü değiştirin: 'şimdi yuvarlananları ayır', 'şimdi sivri tepesi olanları (piramit/koni) ayır.'","Aynı cisimleri farklı kurallarla yeniden gruplatın."],"soyle":"«Şimdi prizma gibi olanları ayır; sonra yuvarlananları ayıralım.»","isaret":"Çocuk cisimleri farklı sınıf ölçütlerine göre yeniden gruplayabiliyor."},"yaprak":{"t":"Kuralım ne?","adim":["Çocuğa bir sınıflama kuralı koydurun ('ben düz yüzlüleri/yuvarlananları seçiyorum, bil bakalım kuralım ne?') ve siz tahmin edin; sonra rolleri değiştirin.","'Küp aynı zamanda bir prizma mı, neden?' gibi bir soruyla sınıfların iç içe geçebileceğini fark ettirin.","Tek bir doğru ayrım olmadığını birlikte keşfedin."],"soyle":"«Sen bir kurala göre ayır, ben kuralını tahmin edeyim.»","isaret":"Çocuk bir 3B sınıf kuralı kurabiliyor ve sınıfların iç içe geçebildiğini fark ediyor."}},{"n":"Cisim Ailelerini Ayırt Eden","gunluk":{"t":"Prizma avı","adim":["Evdeki kutu, konserve, top gibi cisimleri toplayın.","\"Prizma olanları ayır\" deyin; her seçim için \"neden prizma?\" diye sorun.","Cevapta özellik arayın: iki özdeş paralel yüz, dikdörtgen yan yüzler."],"soyle":"\"Neden prizma? Hangi özelliğinden anladın?\"","isaret":"Çocuk seçimini görünüşe değil özelliğe dayandırıyor."},"oyun":{"t":"Özellik bilmecesi","adim":["Bir cisim tutun, göstermeden özelliklerini söyleyin: \"Bütün yüzleri kare.\"","Çocuk cismi tahmin etsin; sonra roller değişsin.","Zorlaştırın: \"Hiç düz yüzü yok\" (küre), \"iki yüzü daire\" (silindir)."],"soyle":"\"Özelliklerini say, ben bileyim!\"","isaret":"Özellikten cisme, cisimden özelliğe iki yönde de gidebiliyor."},"yaprak":{"t":"ABMATO cisim aileleri yaprağı","adim":["ABMATO şekil/cisim sınıflama yapraklarından bir set yazdırın.","Çocuk her cismi ailesine eşlesin ve bir özelliğini yazsın/söylesin."],"soyle":"\"Bu aileye girmesinin kanıtı ne?\"","isaret":"Sınıflama kararlarını özellik cümlesiyle savunuyor."},"kazanim":"Cisim Ailelerini Ayırt Eden","order":7}]},"comp3d":{"code":"Y13","name":"Yapı Kurma (Üç Boyutlu)","strand":"geometri","levels":[{"order":1,"kazanim":"Blokları Tek Tek Kullanan: Temeller","gunluk":{"t":"Bu kutu mu, top mu?","adim":["Toplarken kibrit kutusu, top, bardak gibi nesneleri tek tek eline verin.","Her birini ayrı ayrı incelesin; 'Bu kutu mu, top mu?' diye dokunup tanısın.","Henüz üst üste koymak yok; her parçayı tek başına tutup tanımak yeter."],"soyle":"«Bunu bir incele bakalım: kutu mu, top mu? Tek tek tutalım.»","isaret":"Her parçayı ayrı bir nesne olarak eline alıp tanır."},"oyun":{"t":"Tek Tek Sepet","adim":["Yere 5-6 farklı blok/kutu dağıtın.","Siz bir parça gösterin; çocuk aynısını sepetten alıp masaya tek başına koysun.","Amaç birleştirmek değil, her parçayı ayrı fark etmek."],"soyle":"«Şunun aynısını sepetten bul ve masaya tek başına koy.»","isaret":"İstenen tek parçayı bulup ayrı olarak yerleştirir."},"yaprak":{"t":"Tepside tek tek","adim":["Bir tepsiye 4-5 ayrı blok dizin.","Çocuk her birini parmağıyla işaret edip 'bir... bir... bir...' diye saysın.","Sonra istediği birini seçip eline alsın."],"soyle":"«Hepsi ayrı duruyor; tek tek dokun, sonra bir tanesini seç.»","isaret":"Parçaları tek tek işaretleyip ayrı nesneler olarak ayırt eder."}},{"order":2,"kazanim":"Üst Üste Dizen","gunluk":{"t":"Üst üste koyalım","adim":["'Bakalım kaç kutuyu üst üste koyabiliyoruz?' deyin.","Çocuk bardakları, kibrit kutularını, blokları sırayla üst üste koysun.","Devrilince gülün, tekrar deneyin; yıkılmak oyunun parçası."],"soyle":"«Üstüne, üstüne... bakalım devrilmeden kaç tane koyabiliyoruz?»","isaret":"Nesneleri dengede tutarak üst üste koyabilir."},"oyun":{"t":"Kule Yarışı (yıkmaca)","adim":["Sırayla blok ekleyip kuleyi yükseltin.","Kim koyarken kule devrilirse alkışla yeniden başlayın.","Yarış değil, üst üste dengede tutmayı keşfetme oyunu."],"soyle":"«Sıra sende, bir blok ekle; devrilirse hep beraber yeniden kurarız.»","isaret":"Sırayla blok ekleyerek kuleyi birkaç kat yükseltir."},"yaprak":{"t":"İki katlı kule","adim":["3 bloktan bir kule kurun.","Çocuk yanına aynı yükseklikte bir kule daha diksin.","'Üstüne, üstüne, üstüne' diyerek tek tek koyması yeterli."],"soyle":"«Benim kulem gibi sen de üç bloğu üst üste koy; aynı boyda olsun.»","isaret":"2-3 katlı dengeli bir kule kurar."}},{"order":3,"kazanim":"Sıra Yapan","gunluk":{"t":"Tren gibi yan yana","adim":["Ayakkabıları kapı önüne, kaşıkları masaya dizerken konuşun.","'Hadi bunları bir tren gibi yan yana dizelim' deyin.","Çocuk blokları üst üste değil, yere uç uca bir sıra hâlinde dizsin."],"soyle":"«Üst üste değil; tren gibi arka arkaya, yan yana dizelim.»","isaret":"Nesneleri düz bir hat boyunca yan yana dizer."},"oyun":{"t":"Blok Treni","adim":["Blokları yere uzun bir hat boyunca arka arkaya ekleyin.","'Çuf çuf' diyerek vagon ekleyin.","En uzun treni birlikte sayarak ne kadar uzadığını fark edin."],"soyle":"«Çuf çuf! Bir vagon daha ekle; bakalım trenimiz ne kadar uzayacak.»","isaret":"Blokları bitişik, düz bir sıra olarak uzatır."},"yaprak":{"t":"Çizgiden başla diz","adim":["Masaya bir başlangıç çizgisi koyun.","Çocuk blokları o çizgiden başlayıp düz bir sıra olarak yan yana dizsin.","Sıra düz ve bitişik olunca kaç blok olduğunu birlikte sayın."],"soyle":"«Çizgiden başla, blokları düz bir sıra yap; aralarında boşluk kalmasın.»","isaret":"Çizgiden başlayarak düzgün, bitişik bir sıra oluşturur."}},{"order":4,"kazanim":"Aynı Şekli Üst Üste Dizen","gunluk":{"t":"Hep aynı şekilden","adim":["Toplarken 'Önce tüm küpleri bir araya, sonra üst üste koyalım' deyin.","Çocuk aynı türden parçaları (hep küp ya da hep kibrit kutusu) seçsin.","Karışık değil, hep aynı şekilden bir kule yapsın."],"soyle":"«Sadece küpleri seç; hepsi aynı olsun, sonra üst üste koyalım.»","isaret":"Aynı şekilleri ayırıp yalnız onlardan kule yapar."},"oyun":{"t":"Aynı Aileden Kule","adim":["Blokları şekline göre ayırın.","Çocuk yalnızca bir aileyi (örneğin tüm silindir bardaklar) üst üste koysun.","Aynı şekilleri seçip istiflemek oyunun özü."],"soyle":"«Bu kule sadece silindirlerden olacak; aynı aileyi seç ve üst üste koy.»","isaret":"Tek tür şekli seçip onlardan istif kurar."},"yaprak":{"t":"Önce ayır, sonra istifle","adim":["Önüne iki tür blok karışık koyun.","Çocuk önce aynı olanları ayırsın.","Sonra o aynılardan düzgün bir kule kursun."],"soyle":"«Önce aynıları bir kenara ayır; sonra sadece onlardan kule yap.»","isaret":"Karışıktan aynı şekilleri ayırıp onlardan kule kurar."}},{"order":5,"kazanim":"Zemin ve Duvar Yapan","gunluk":{"t":"İki parça bir olur","adim":["Tost yaparken 'Ekmek-peynir-ekmek, parçaları birleştirdik!' deyin.","Aynı mantıkla iki üçgen bloğu birleştirince kare olduğunu gösterin.","İki yarım bloğu birleştirince bütün olduğunu oyuncaklarla deneyin."],"soyle":"«İki üçgeni birleştirince ne çıktı? Bak, koca bir kare oldu!»","isaret":"İki parçayı birleştirip yeni bir bütün şekil oluşturur."},"oyun":{"t":"Birleşince ne oldu?","adim":["İki üçgen prizmayı birleştirip kutu yapın.","İki yarım silindiri birleştirip tam silindir yapın.","Çocuk parçaları birleştirip oluşan yeni bütünü birlikte adlandırın."],"soyle":"«İki yarımı birleştir; bak şimdi tam bir silindir oldu, adı ne?»","isaret":"Parçaları doğru birleştirip oluşan bütünü adlandırır."},"yaprak":{"t":"Bütünü geri kur","adim":["Bir küp bloğu ya da köpük şekli ikiye bölün (ya da iki yarım verin).","Çocuk iki parçayı birleştirip baştaki bütünü geri oluştursun.","Parçalar birleşip bütün çıkınca etkinlik başarılı."],"soyle":"«Bu iki parça aslında bir bütündü; birleştir de eski hâline getir.»","isaret":"İki parçayı birleştirerek baştaki bütünü yeniden oluşturur."}},{"order":6,"kazanim":"Kemer ve Köşeleri Deneyerek Kuran","gunluk":{"t":"Bloklardan ev","adim":["'Hadi bloklardan bir ev (ya da araba) yapalım' deyin.","Çocuk farklı blokları birleştirip tanınır bir yapı kursun.","Duvar için kutular, çatı için üçgen, baca için küçük blok kullansın."],"soyle":"«Duvar için kutuları, çatı için üçgeni koy; bak, eve benzedi!»","isaret":"Farklı blokları birleştirip tanınır bir yapı oluşturur."},"oyun":{"t":"Ne Yapalım?","adim":["Bir kâğıda ev, kamyon, robot gibi basit bir nesne çizin.","Çocuk bloklardan o nesneyi serbestçe inşa etsin.","Birebir aynı olması değil, 'neye benzediği' önemli."],"soyle":"«Bu resimdeki kamyonu bloklardan yapabilir misin? Birebir olması şart değil.»","isaret":"Bloklarla, hedef nesneye benzeyen bir yapı kurar."},"yaprak":{"t":"Bana bir köprü yap","adim":["Çocuğa bir avuç karışık blok verin.","'Bana bir köprü/kule/ev yap' deyin.","Ne yaptığını size anlatsın."],"soyle":"«Bu bloklardan bir köprü kur; bittiğinde bana neresi ne, anlat.»","isaret":"Bloklar akılda bir yapıya dönüşür ve çocuk onu anlatabilir."}},{"order":7,"kazanim":"Yapıyı Planlayarak Kuran","gunluk":{"t":"Aynısını yap","adim":["Bir oyuncak kutusunun ya da kibrit kutusunun kapağını gösterin.","'Aynısını bloklardan yapabilir misin?' deyin.","Çocuk gördüğü belirli 3B şekli (kutu, basamak, piramit) bloklarla birebir oluştursun."],"soyle":"«Şu şeklin tıpatıp aynısını bloklardan kurabilir misin?»","isaret":"Verilen hedef 3B şekli bloklarla birebir oluşturur."},"oyun":{"t":"Modeli Yakala","adim":["Kapalı bir engel arkasında 4-6 bloktan belli bir yapı (örn. L şeklinde basamak) kurun.","Sonra gösterin; çocuk aynı hedef şekli kendi bloklarıyla kopyalasın.","Sonunda kim daha çok benzetti diye birlikte bakın."],"soyle":"«İşte modelim; sen de kendi bloklarınla aynısını kur, sonra karşılaştıralım.»","isaret":"Gösterilen modeli kendi bloklarıyla doğru kopyalar."},"yaprak":{"t":"3 bloklu merdiven","adim":["Bir kâğıda hedef 3B şekil çizin ya da fotoğrafını gösterin (örnek: 3 bloklu merdiven).","Çocuk tam o şekli bloklarla oluştursun.","Hedefe ulaşan yapı çıkınca etkinlik başarılı."],"soyle":"«Resimdeki merdivene bak; aynısını bloklarla yap, basamak basamak.»","isaret":"Resimdeki hedef şekli doğru oranlarla bloklarla kurar."}},{"order":8,"kazanim":"Parça Değiştirip Karmaşık Yapılar Kuran","gunluk":{"t":"Deseni devam ettir","adim":["Yemek dizerken 'Şu deseni devam ettirelim: kutu-top-kutu-top...' deyin.","Çocuk parçaları belli bir düzene göre yerine koysun.","Aynı 3B birimi tekrarlayarak diziyi uzatsın."],"soyle":"«Kutu-top-kutu-top... sıradaki ne olmalı? Düzeni bozma.»","isaret":"Tekrar eden birimi doğru sırayla yerine koyarak uzatır."},"oyun":{"t":"Tekrarla ve Uzat","adim":["2-3 bloktan bir birim yapın (örn. küp + üçgen çatı = bir ev birimi).","Çocuk aynı birimi yan yana tekrarlayıp bir sokak/sıra kursun.","Her tekrarda 'bir ev daha, iki ev...' diye sayın."],"soyle":"«Bu ev birimini al ve yan yana tekrarla; bir sokak dolusu ev olsun.»","isaret":"Çok parçalı birimi bozmadan, yan yana tekrarlayarak çoğaltır."},"yaprak":{"t":"Birimi 3-4 kez tekrarla","adim":["Çocuğa bir desen birimi gösterin (örn. iki küp + bir köprü).","Çocuk bu birimi 3-4 kez tekrarlayarak aynı yapıyı uzatsın.","Birim doğru yerlere konup düzenli tekrarlanınca iş tamam."],"soyle":"«İki küp + bir köprü bizim birimimiz; bunu üç-dört kez aynen tekrarla.»","isaret":"Birimi düzenli ve aynı sırayla birkaç kez tekrarlar."}},{"order":9,"kazanim":"Katlı ve Çatılı Yapılar Kuran","gunluk":{"t":"Küçük gruplardan büyük yapı","adim":["Yumurta viyolünü ya da koli içindeki kutuları gösterin.","'Bir kutu birçok şeyden yapılı; biz de küçük gruplardan büyük bir şey kuralım' deyin.","Çocuk önce 2-3 bloktan küçük bir birim, sonra o birimlerden büyük bir yapı oluştursun."],"soyle":"«Önce küçük paketler yapalım, sonra paketlerden kocaman bir şey kuralım.»","isaret":"Küçük birimleri kurup onları daha büyük bir bütünde birleştirir."},"oyun":{"t":"Birimden Büyük Yapı","adim":["Önce her biri 4 bloktan eş 'tuğla paketleri' yapın.","Çocuk bu paketleri bir araya getirip büyük bir duvar/kale kursun.","'Kaç paket kullandık, her pakette kaç blok var?' diye konuşun."],"soyle":"«Her paket 4 blok; bu paketlerden koca bir kale kuralım, kaç paket gerekti?»","isaret":"Eş birimleri sayıp birim-üstü birimlerle büyük yapı kurar."},"yaprak":{"t":"Kaç birim, kaç blok?","adim":["Çocuk önce 2'şer bloktan birkaç eş birim kursun.","Sonra bu birimleri üst üste/yan yana koyup tek büyük yapı oluştursun.","Sonunda 'kaç birim, toplam kaç blok' diye birlikte sayın."],"soyle":"«İkişer bloktan birimler yap; sonra birleştir. Kaç birim oldu, toplam kaç blok?»","isaret":"Eş birimlerden büyük bütünü kurar ve birim/blok sayısını ilişkilendirir."}}]},"spviz":{"code":"Y14","name":"Uzamsal Görselleştirme ve İmgelem","strand":"uzamsal","levels":[{"order":1,"kazanim":"Sezgisel Hareket Ettiren: Temeller","gunluk":{"t":"Buraya kaydıralım","adim":["Oyuncak toplarken nesneleri birlikte yerlerine yerleştirin.","Arabayı kutuya itin, ayıyı rafa kaldırın.","'Hadi bunu buraya kaydıralım' diyerek her nesneyi elle hareket ettirsin."],"soyle":"«Arabayı kutuya doğru kaydır; ayıyı da rafa kaldır bakalım.»","isaret":"Nesneleri eliyle iterek/çekerek istenen yere getirir."},"oyun":{"t":"Bana doğru, benden uzağa","adim":["Yere bir battaniye serin, üstüne oyuncaklar koyun.","'Topu sana doğru getir, sonra benden uzağa götür' deyin.","Çocuk nesneyi iterek, çekerek özgürce hareket ettirsin."],"soyle":"«Topu önce kendine çek, sonra benden uzağa it; sen yönetiyorsun.»","isaret":"Nesneyi kendine doğru ve uzağa bilinçli olarak hareket ettirir."},"yaprak":{"t":"Kaptan kaba taşı","adim":["Masaya 3-4 küçük kap koyun.","Çocuktan bir fasulyeyi/makarnayı kaptan kaba taşımasını isteyin.","Başardığında 'tam yerine koydun' deyin; gezdirmek serbest."],"soyle":"«Bu fasulyeyi şu kaba taşı; nasıl götürürsen götür, yeter ki oraya koy.»","isaret":"Küçük nesneyi bir yerden alıp hedef kaba taşır."}},{"order":2,"kazanim":"Deneye Deneye Yerleştiren","gunluk":{"t":"Kaydır, çevir, döndür","adim":["Bir bardağı masada kaydırın, sonra ters çevirin (yansıtın), sonra döndürün.","Çocuğa aynısını yaptırın.","'Sen de kaydır, sen de çevir, sen de döndür' deyin; üç hareketi de denesin."],"soyle":"«Önce kaydır, sonra ters çevir, bir de döndür; üçünü de yap bakalım.»","isaret":"Kaydırma, yansıtma ve döndürmeyi somut nesneyle ayrı ayrı yapar."},"oyun":{"t":"Beni taklit et","adim":["Bir oyuncak araba/kaşık alın: önce ileri kaydırın.","Sonra aynaya bakar gibi ters yatırın (yansıtın), sonra masada döndürün.","Çocuk her seferinde sizi taklit etsin."],"soyle":"«Ben ne yaptıysam aynısını yap: kaydırdım, ters yatırdım, döndürdüm.»","isaret":"Gösterilen üç hareketi sırayla taklit eder."},"yaprak":{"t":"El şeklini çevir","adim":["Bir el ayası şeklini kâğıda çizip kesin.","Çocuk onu masada kaydırsın, ters çevirsin (sağ-sol değişsin), bir de döndürsün.","Hangi hareketin neyi değiştirdiğini birlikte fark edin."],"soyle":"«Ters çevirince el değişti, gördün mü? Şimdi bir de döndür.»","isaret":"Kâğıt şekli üç dönüşümle hareket ettirir, farkı sezer."}},{"order":3,"kazanim":"Basit Kaydırma ve Döndürme Yapan","gunluk":{"t":"Kaydır ya da döndür","adim":["Bir oyuncağı 'şuradan şuraya kaydır' (yerini değiştir) diye yönlendirin.","Ya da 'olduğu yerde çevir' (döndür) deyin.","Sadece bu iki basit hareketi günlük objelerle tekrar ettirin."],"soyle":"«Bunu ya başka yere kaydır ya da olduğu yerde döndür; hangisi olsun?»","isaret":"Kaydırma ile döndürmeyi ayırt edip istenenini yapar."},"oyun":{"t":"Altlığı kaydır-döndür","adim":["Bir bardak altlığını/küçük tabağı masada bir noktadan diğerine kaydırın.","Sonra olduğu yerde yavaşça döndürün.","'Sıra sende: önce kaydır, şimdi döndür' deyin."],"soyle":"«Önce şuraya kaydır; şimdi de yerinde döndür. İki ayrı hareket.»","isaret":"Aynı nesneyle önce kaydırma sonra döndürme yapar."},"yaprak":{"t":"Oku kaydır ve döndür","adim":["Kâğıda bir ok çizip kesin.","Çocuktan oku masada sağa doğru kaydırmasını isteyin.","Sonra ucu yukarı bakacak şekilde döndürmesini isteyin."],"soyle":"«Oku sağa kaydır; sonra ucu yukarı baksın diye döndür.»","isaret":"Oku kaydırır ve istenen yöne döndürür."}},{"order":4,"kazanim":"Doğru Hareketi Seçen (yönü şaşabilir)","gunluk":{"t":"Peçeteyle üç hareket","adim":["Sofra kurarken peçeteyi çocuğa verin.","'Tabağın yanına kaydır', 'ikiye katla gibi ters çevir', 'köşesini döndür' deyin.","Üç hareketi de yavaşça, adım adım deneyin."],"soyle":"«Peçeteyi kaydır, sonra ters çevir, bir de köşesinden döndür; acele yok.»","isaret":"Üç dönüşümü tek nesneyle, başlangıç düzeyinde uygular."},"oyun":{"t":"Aynı hâle getir","adim":["İki özdeş oyuncak/blok alın.","Birini siz bir konuma getirin (kaydırıp, çevirip ya da döndürüp).","Çocuk diğerini aynı hâle getirmeye çalışsın; üç hareketi de sırayla deneyin."],"soyle":"«Benimkini şöyle yaptım; seninkini de aynı hâle getir, hangi hareket gerekiyor?»","isaret":"Hedef konuma ulaşmak için doğru dönüşümü seçip uygular."},"yaprak":{"t":"L şeklini dönüştür","adim":["Bir 'L' ya da bot şeklini kâğıttan kesin (sağ-sol farkı belli olsun).","Çocuk onu kaydırsın, aynadaki gibi ters çevirsin, bir de çeyrek döndürsün.","Üçünü de denemesi başarı sayılır; doğruluk zamanla gelir."],"soyle":"«L'yi kaydır, sonra aynadaki gibi ters çevir, bir de çeyrek döndür.»","isaret":"Yön farkı belli şekilde üç dönüşümü ayırt ederek dener."}},{"order":5,"kazanim":"Zihninde Canlandırıp Hareket Ettiren","gunluk":{"t":"İpucusuz üç hareket","adim":["Bulaşıkları yerleştirirken bir kabı belli bir yere 'kaydırmasını' isteyin.","Diğerini 'ters çevirmesini', bir başkasını 'döndürerek' yerleştirmesini isteyin.","Artık ipucu vermeden üç hareketi de rahatça yapabilsin."],"soyle":"«Bunu kaydır, şunu ters çevir, ötekini döndürerek yerine koy.»","isaret":"Üç dönüşümü ipucu almadan, güvenle ve doğru uygular."},"oyun":{"t":"Kâğıt Tetris","adim":["Kâğıttan birkaç farklı şekil kesin, bir 'çerçeve' çizin.","Çocuk şekilleri kaydırıp, çevirip, döndürerek çerçeveye sığdırsın.","Boşluk kalmayacak şekilde yerleştirmeye çalışsın."],"soyle":"«Şekli çevirip döndürerek boşluğa tam otursun; Tetris gibi düşün.»","isaret":"Şekilleri uygun dönüşümle çevirip çerçeveye boşluksuz yerleştirir."},"yaprak":{"t":"Hangi hareket yapıldı?","adim":["İki sütunlu sayfa hazırlayın: solda bir şekil, sağda kaydırılmış/yansıtılmış/döndürülmüş hâli.","Çocuk her satırda hangi hareketin yapıldığını söylesin.","Elindeki kâğıt şekille o hareketi göstererek doğrulasın."],"soyle":"«Soldaki şekil sağda ne olmuş: kaymış mı, çevrilmiş mi, dönmüş mü?»","isaret":"Yapılan dönüşümü doğru adlandırır ve şekille gösterir."}},{"order":6,"kazanim":"Çapraz Eksende de Hareket Ettiren","gunluk":{"t":"Köşeden köşeye çapraz","adim":["Çamaşır asarken/kitap yerleştirirken bir nesneyi köşeden köşeye çapraz kaydırsın.","'Şu üst köşeden alt köşeye çapraz götür' deyin.","Düz değil, çapraz yönü vurgulayın."],"soyle":"«Düz değil; üst köşeden alt köşeye çapraz götür bakalım.»","isaret":"Nesneyi yatay/dikey değil, çapraz yönde hareket ettirir."},"oyun":{"t":"Çapraz ilerle","adim":["Dama tahtası ya da kareli kâğıt çizin.","Bir pulu çaprazlamasına (köşegen boyunca) hareket ettirme oyunu oynayın.","'Bir kare çapraz ilerle' deyin."],"soyle":"«Pulu bir kare çapraz ilerlet; köşegen boyunca gidiyoruz.»","isaret":"Pulu köşegen boyunca, çapraz adımlarla ilerletir."},"yaprak":{"t":"İki nokta arası köşegen","adim":["Kareli kâğıtta iki nokta işaretleyin (biri sol-üst, biri sağ-alt).","Çocuk bir nesneyi ya da kalemini çapraz çizgi boyunca iki nokta arasında götürsün.","Köşegen hareketi hissetmesi yeterli."],"soyle":"«Sol üstteki noktadan sağ alttakine çapraz bir çizgi çek; işte köşegen.»","isaret":"İki noktayı köşegen (çapraz) bir yolla birleştirir."}},{"order":7,"kazanim":"Tamamen Zihinden Hareket Ettiren","gunluk":{"t":"Kafanda çevir","adim":["Bir nesne gösterip 'Bunu kafanda çevirsen ne olurdu, hangi yüzü görünürdü?' diye sorun.","Önce gözünü kapatıp hayal etsin.","Sonra gerçekten çevirip kontrol edin; tahmin tutmasa da merakı kutlayın."],"soyle":"«Gözünü kapat; bunu kafanda çevir, sence hangi yüzü görünürdü?»","isaret":"Bir dönüşümün sonucunu çevirmeden önce zihinde tahmin eder."},"oyun":{"t":"Ters çevirsem nasıl?","adim":["Bir resimli kart/oyuncak gösterip saklayın.","'Bunu ters çevirsem nasıl görünür, çiz/anlat' deyin.","Çocuk zihninde döndürüp tarif etsin, sonra birlikte bakıp karşılaştırın."],"soyle":"«Bu kartı ters çevirsem ne görünürdü? Önce hayal et, sonra bakalım.»","isaret":"Görmeden, zihinde döndürüp sonucu tarif edebilir."},"yaprak":{"t":"Döndürülmüşünü çiz","adim":["Kâğıda basit bir şekil çizin.","Çocuktan onu zihninde döndürünce/yansıtınca nasıl olacağını yandaki boşluğa çizmesini isteyin.","Sonra kâğıdı gerçekten çevirip karşılaştırın; yaklaştıysa büyük başarı."],"soyle":"«Bu şekli kafanda döndür; yan tarafa öyle çiz, sonra gerçeğiyle karşılaştıralım.»","isaret":"Şeklin zihinde döndürülmüş hâlini kâğıda yaklaşık çizer."}}]},"sporient":{"code":"Y15","name":"Uzamsal Yönelim","strand":"uzamsal","levels":[{"order":1,"kazanim":"Uzamsal Yönelim: Temeller","gunluk":{"t":"Hep aynı köşe","adim":["Sandalye, oyuncak sepeti ve uyku köşesini her gün TAM aynı yerde tutun.","Acıkınca ya da oyuncak isteyince siz işaret etmeden 'Mama nerede?' deyip bekleyin.","Çocuk o sabit köşeye kendi bedeniyle döndüğünde sevinin."],"soyle":"«Mama her zaman şu köşede; bak, sen biliyorsun nereye dönmek lazım.»","isaret":"Siz göstermeden tanıdık köşeye doğru kendi başına döner."},"oyun":{"t":"Hep Orada oyunu","adim":["En sevdiği oyuncağı birkaç gün üst üste hep aynı dolabın/koltuğun önüne koyun.","Sonra 'Hadi onu bulalım' deyip o tanıdık noktaya yönelmesini bekleyin.","Doğru köşeye gidince birlikte alkışlayın."],"soyle":"«Oyuncağın hep aynı yerde uyuyor; vücudun yolu hatırlıyor mu?»","isaret":"Oyuncağın sabit yerine doğru tereddütsüz yönelir."},"yaprak":{"t":"Tanıdık köşe rutini","adim":["Uyku ve mama gibi anları hep aynı köşede, kısa bir rutinle yapın.","Rutin bitince sıcak bir kucaklama verin.","Aynı yer + aynı duyguyu günlerce tekrarlayın."],"soyle":"«Burası bizim sakin köşemiz; buraya gelince ne yapacağımızı biliyorsun.»","isaret":"Belli köşeye gelince hangi rutinin geldiğini bekler gibi davranır."}},{"order":2,"kazanim":"Kendi Yolunu Hatırlayan","gunluk":{"t":"Sen götür beni","adim":["Kapıdan oyuncak sepetine bir-iki dönüşlü kısa bir yolu birlikte yürüyün.","Biraz sonra 'Hadi yine oyuncaklara gidelim, bu sefer sen götür' deyin.","Aynı dönüşleri ve mesafeyi kendi üretince doğrulayın."],"soyle":"«Az önce gittiğimiz yolu hatırlıyor musun? Beni sen götür bakalım.»","isaret":"Aynı yolun dönüşlerini kabaca doğru sırayla tekrar eder."},"oyun":{"t":"Sen Kılavuz Ol","adim":["Mutfaktan çocuğun odasına birlikte yürüyün.","Elini tutup 'Beni geri götür' deyin.","Doğru dönüşleri yaptıkça her dönüşte alkışlayın."],"soyle":"«Geldiğimiz yolu tersten yürüyebilir misin? Sağa mı dönmüştük, sola mı?»","isaret":"Gittiği yolu tersten, dönüşleri ters çevirerek yürüyebilir."},"yaprak":{"t":"Kısa yolu tek başına","adim":["Yatak-çekmece arası gibi 3-4 adımlık çok kısa bir yol seçin.","Birlikte bir kez yürüyün, kısa bir oyalamadan sonra tek başına yürümesini isteyin.","Başardıkça yolu azar azar uzatın."],"soyle":"«Şu kısa yolu bir kere yürüdük; şimdi tek başına aynısını yapabilir misin?»","isaret":"Kısa yolu yardımsız, aynı rotayla tamamlar."}},{"order":3,"kazanim":"Yerleri Aklında Tutan","gunluk":{"t":"İçine, üstüne, altına","adim":["Çocuk bakarken oyuncağı tanıdık bir yere saklayın: 'Topu koltuğun ALTINA koyuyorum'.","Birkaç dakika sonra 'Topun nerede?' diye sorun.","Saklarken 'içine, üstüne, altına' sözcüklerini bolca kullanın."],"soyle":"«Topu koltuğun altına koydum; altına bakarsan bulursun.»","isaret":"Konum sözcüğünü duyup doğru yere (alt/üst/iç) gider."},"oyun":{"t":"Nerede Saklı?","adim":["Oyuncağı 'kutunun içine', 'sandalyenin altına', 'masanın üstüne' gibi yerlere saklayın.","Çocuk her seferinde konum sözcüğünü duyup yeri bulsun.","Sonra sırayı ona verin: 'Sen ayıyı kutunun içine koy.'"],"soyle":"«Ayı sandalyenin altında mı, masanın üstünde mi saklı? Sözcüğü dinle.»","isaret":"Yer sözcüğüne göre doğru yeri bulur ve kendisi de doğru yere koyar."},"yaprak":{"t":"Her oyuncağın evi","adim":["Akşam toplanırken her oyuncağa 'evini' söyleyerek yerleştirin.","'Bloklar sepetin içine, kitaplar rafın üstüne' deyin.","Çocuk eşyaları yer sözcükleriyle yerine koysun."],"soyle":"«Blokların evi sepetin içi; kitapların evi rafın üstü. Hadi yerlerine.»","isaret":"Eşyaları doğru yere, konum sözcüğüyle eşleştirerek yerleştirir."}},{"order":4,"kazanim":"Yer İmlerini Kullanmaya Başlayan","gunluk":{"t":"Önceden söyledim","adim":["Bir şeyi nereye koyduğunuzu ÖNCEDEN söyleyin: 'Topu sandalyenin yanına koyuyorum'.","Çocuğu odanın başka bir köşesine götürüp oradan 'Hadi bul' deyin.","Kendi yeri değişse de sabit eşyaya gidip bulmasını övün."],"soyle":"«Sen şimdi başka köşedesin ama top hâlâ sandalyenin yanında; oraya yürü.»","isaret":"Kendi konumu değişse de uzaktaki sabit ipucuna gidip bulur."},"oyun":{"t":"Yanında ve arasında","adim":["Oyuncağı belli bir eşyanın yanına koyduğunuzu duyurun.","Çocuğu birkaç adım yürütüp döndürün, sonra bulmaya gönderin.","'Ayıyı iki yastığın ARASINA koy' diyerek 'arasında/yanında' sözcüklerini ekleyin."],"soyle":"«Ayıyı iki yastığın arasına sakladım; sen döndün ama ayı yerinde, bul bakalım.»","isaret":"'Yanında' ve 'arasında' yön sözcüklerine göre yeri bulur."},"yaprak":{"t":"Sofrada yön yerleştirme","adim":["'Çatalı tabağın yanına koy' yönergesini verin.","'Peçeteyi iki bardağın arasına koy' deyin.","Kendi yeri değişse de sabit eşyalara göre doğru yerleştirsin."],"soyle":"«Çatal tabağın yanına, peçete iki bardağın arasına; sen nereden bakarsan bak yer aynı.»","isaret":"Eşyaları sabit referanslara göre 'yan/ara' ilişkisiyle doğru koyar."}},{"order":5,"kazanim":"Yakın Çevresinde Yön Bulan","gunluk":{"t":"Halıda düzenli arama","adim":["Çocuk başka yöne bakarken oyuncağı küçük bir halının bir yerine saklayın.","'Oyuncak bu halıda bir yerde, bul bakalım' deyin.","Bir kenardan başlayıp dolanarak düzenli taradığında fark edip övün."],"soyle":"«Bir köşeden başla, hiçbir yeri atlama; halıyı sırayla tara.»","isaret":"Alanı rastgele değil, bir örüntüyle (kenardan kenara) tarar."},"oyun":{"t":"Sistemli Dedektif","adim":["Küçük bir kilime birkaç eşya saklayın.","'Her köşeye sırayla bak, hiçbir yeri atlama' ipucunu bir kez verin.","'Ayının önüne bir blok, arkasına bir blok koy' diyerek 'ön/arka, sağ/sol' çalıştırın."],"soyle":"«Dedektif gibi sırayla bak: önce şu kenar, sonra öteki; bir de ayının önüne-arkasına bak.»","isaret":"Önü/arkayı, sağ/solu ayırt eder ve alanı sistemli tarar."},"yaprak":{"t":"Bölge bölge ara","adim":["Kaybolan bir eşyayı (terlik, kumanda) birlikte ararken alanı bölgelere ayırın.","'Önce şu köşeden başlayalım, sonra şuraya bakalım' deyin.","Aramayı bir plana bağlayarak ilerleyin."],"soyle":"«Odayı parçalara bölelim: bu köşe, sonra şu köşe; böyle hiçbir yer atlanmaz.»","isaret":"Aramayı bölgelere ayırıp kapsamlı, atlamasız tarar."}},{"order":6,"kazanim":"Tanıdık Mekânda Yön Bulan","gunluk":{"t":"Tam ortasında","adim":["Bir şeyin yerini iki yer imiyle birden tarif edin: 'Kumanda, televizyon ile koltuğun tam ortasında'.","Çocuktan da bir eşyanın yerini 'neyin ile neyin arasında/ortasında' diye anlatmasını isteyin.","İki referansa göre konum belirtmesini destekleyin."],"soyle":"«Kumanda televizyonla koltuğun tam ortasında; sen de bir şeyi iki şeye göre anlat.»","isaret":"Bir nesnenin yerini iki yer imine göre tarif edebilir."},"oyun":{"t":"Ortada hazine + tablo","adim":["Odaya 3-4 nesne dizin; çocuk baktıktan sonra bir nesneyi odanın öbür ucuna geçirin.","'Ayı neredeydi?' deyip 'masayla kapının ortasında' gibi tarif bekleyin.","Sonra satır-sütun etiketli basit tabloda 'B-2'deki kartı aç' deyin."],"soyle":"«Ayı masayla kapının ortasındaydı; şimdi tablodaki B-2 kutusunu bul.»","isaret":"Konumu iki yer imiyle söyler; tabloda satır-sütunla tek kareyi bulur."},"yaprak":{"t":"3'e 3 ilk koordinat","adim":["Mukavvaya 3'e 3 kareli tablo çizin; satırları 1-2-3, sütunları A-B-C etiketleyin.","Çocuk 'B-2' kutusuna bir çıkartma yapıştırsın.","Birkaç farklı kareyi iki etiketle söyleyip buldurun."],"soyle":"«B sütunu ile 2. satır nerede kesişiyor? İşte oraya çıkartmayı koy.»","isaret":"Tek bir kareyi satır + sütun etiketiyle doğru bulur."}},{"order":7,"kazanim":"Harita Kullanan","gunluk":{"t":"Bu kâğıt bizim oda","adim":["Odanın çok basit resimli krokisini çizin (kapı, yatak, masa).","Bir noktaya çıkartma koyup 'Çıkartmanın olduğu yere git, orada sürpriz var' deyin.","Kâğıttaki simgeyi gerçek eşyayla eşleyip doğru köşeye gitmesini bekleyin."],"soyle":"«Bu kâğıt bizim odamız; haritadaki çıkartma nerede, gerçekte oraya yürü.»","isaret":"Haritadaki bir noktayı gerçek mekânda doğru yere eşler."},"oyun":{"t":"Resimli Hazine Haritası","adim":["Evin bir bölümünün basit krokisini çizin.","Hazinenin yerini bir çarpı/çıkartmayla işaretleyin.","Simgeleri birlikte adlandırın (yatak resmi = gerçek yatak), çocuk hazineyi bulsun."],"soyle":"«Haritadaki yatak resmi gerçek yatağımız; çarpı işareti nerede, hazine orada.»","isaret":"Harita simgelerini gerçek eşyalarla eşleyip hazineyi bulur."},"yaprak":{"t":"Mutfak krokisi","adim":["Birlikte mutfağın küçük krokisini çizin; buzdolabını, masayı, lavaboyu basit şekillerle gösterin.","Siz krokide bir yeri işaretleyin.","Çocuk oraya gidip o gerçek eşyaya dokunsun."],"soyle":"«Krokide işaretlediğim yer gerçek mutfakta neresi? Oraya git ve dokun.»","isaret":"Küçük tanıdık krokiyi okuyup işaretli eşyaya gider."}},{"order":8,"kazanim":"Koordinat Okuyup İşaretleyen","gunluk":{"t":"C-4'te ne var?","adim":["Kareli kâğıda satırları 1-2-3-4, sütunları A-B-C-D etiketleyin.","Gün içinde 'C-4'te ne var?' diye sorun.","Sonra 'B-2'ye bir çarpı koy' deyin; hem bulsun hem yerleştirsin."],"soyle":"«C sütunu ile 4. satırın kesiştiği kareyi bul; bir de B-2'ye çarpı koy.»","isaret":"Verilen koordinatı bulur ve bir kareyi koordinatla adlandırır."},"oyun":{"t":"Amiral Battı (ev sürümü)","adim":["Kareli kâğıda küçük gemiler/şekiller çizin.","Çocuk 'D-3' deyip kareyi yoklasın; isabet edince sevinin.","Rolleri değiştirin: kareyi söyleme ve gösterilen kareyi adlandırma sırayla dönsün."],"soyle":"«D-3'ü söyle ve oraya bak; sonra ben bir kare göstereceğim, sen adını söyle.»","isaret":"Koordinatı söyleyerek atış yapar ve gösterilen kareyi doğru adlandırır."},"yaprak":{"t":"4'e 4 ızgara","adim":["Kareli deftere 4'e 4 bir ızgara çizin.","Birkaç kareye küçük resim koyun; çocuk her resmin koordinatını yazsın.","Sonra sizin söylediğiniz koordinatlara yeni işaretler koysun."],"soyle":"«Bu resim hangi karede? Koordinatını yaz; sonra söylediğim koordinata sen işaret koy.»","isaret":"Resimlerin koordinatını yazar ve verilen koordinatları işaretler."}},{"order":9,"kazanim":"Rota Haritasını İzleyen","gunluk":{"t":"Duraklı rota yürüyüşü","adim":["Eve/bahçeye 3-4 dönüşlü kısa bir rota çizin (başla, dur, dur, hedef).","'Bu haritadaki yolu yürü, duraklarda dur' deyin.","Dönüşleri doğru yapıp duraklarda yaklaşık doğru yerde durmasını izleyin."],"soyle":"«Haritadaki yolu takip et; her durakta dur, sonra bir sonraki dönüşe geç.»","isaret":"Çizili rotanın dönüşlerini ve duraklarını sırayla izler."},"oyun":{"t":"Harita Yürüyüşü","adim":["Yere yastık/koni ile birkaç durak koyun.","Krokide yolu oklarla çizin.","Çocuk haritaya bakıp duraklara sırayla uğrasın; her durakta küçük görev (zıpla, alkışla) ekleyin."],"soyle":"«Oklar nereye gidiyor? Sırayla her durağa uğra; o durakta bir zıpla.»","isaret":"Ok-haritasını izleyerek durakları doğru sırayla geçer."},"yaprak":{"t":"Ok-harita hazinesi","adim":["Bir köşeden başka köşeye giden ok-haritası çizin (kapıdan çık, sağa dön, masaya yürü, sola dön, sepete var).","Çocuk haritayı izleyerek hazineye ulaşsın.","Rotayı kısa ve net tutarak her dönüşü başarmasını sağlayın."],"soyle":"«Önce sağa, sonra masaya, sonra sola; okları takip et, hazine sepette.»","isaret":"Ok dizisini adım adım izleyip hedefe doğru rotayla ulaşır."}},{"order":10,"kazanim":"Haritayı Her Durumda Kullanan","gunluk":{"t":"Dönük harita","adim":["Krokiyi bilerek ters/yan çevirip verin: 'Bu harita biraz dönük ama hazineyi bulabilir misin?'","Harita ile odanın yönü uyuşmasa da hedefe gitmeyi denesin.","Sonra 'Sen de odamızın haritasını çiz, oyuncağın yerini işaretle' deyin."],"soyle":"«Harita dönük olsa da gerçek oda aynı; kafanda çevir ve hazineyi bul.»","isaret":"Döndürülmüş haritayı zihninde hizalayıp doğru yere gider."},"oyun":{"t":"Dönük Harita meydan okuması","adim":["Bildiği bir mekânın krokisini 90-180 derece çevirip verin.","Hazineyi bulmasını isteyin.","Rolleri değiştirin: o size bir harita çizsin, siz onun haritasıyla arayın."],"soyle":"«Haritayı çevirdim; yine de gerçek yeri bulabilir misin? Sonra sen bana harita çiz.»","isaret":"Döndürülmüş haritayı okur ve başkasının kullanabileceği harita çizer."},"yaprak":{"t":"Kendi oda haritan","adim":["Çocuk boş kâğıda kendi odasının haritasını çizsin: yatak, kapı, masa.","Sakladığı bir oyuncağı haritada işaretlesin.","Siz o haritaya bakarak oyuncağı bulun."],"soyle":"«Odanı kâğıda çiz, oyuncağını işaretle; ben senin haritanla bulacağım.»","isaret":"Başkasının izleyip yer bulabileceği doğru bir harita üretir."}}]},"mlen":{"code":"Y16","name":"Ölçme: Uzunluk","strand":"olcme","levels":[{"order":1,"kazanim":"Uzunluk Duyarlılığı: Temeller","gunluk":{"t":"Uzun mu, kısa mı","adim":["Giydirirken iki kıyafeti yan yana tutun (uzun kollu, kısa kollu).","Elinizle havada kolun boyunu çizerek 'bu uuuzun', 'bu kısacık' deyin.","Çocuktan da elleriyle uzunu ve kısayı havada göstermesini isteyin."],"soyle":"«Bak, bu kol ne kadar uuuzun, bu ise kısacık!»","isaret":"Uzun olanı kollarını açarak, kısa olanı parmaklarını yaklaştırarak gösteriyor."},"oyun":{"t":"Uzun yılan kısa solucan","adim":["İki yün/ip parçası alın; birini iyice gerip 'koca uzun yılan' yapın.","Ötekini kısacık tutup 'minik solucan' deyin.","'Hangisi uzun yılan?' diye sorun; sonra sıra çocukta, o yapsın."],"soyle":"«Hangisi koskocaman uzun yılan, hangisi minik solucan?»","isaret":"Gergin uzun ipi 'yılan', kısa ipi 'solucan' diye doğru gösterip kıkırdıyor."},"yaprak":{"t":"Evde uzun-kısa avı","adim":["Ev içinde dolaşıp 'en uzun' ve 'en kısa' eşyaları birlikte avlayın.","Uzun bir şey bulunca (süpürge sapı) kollarınızı açıp 'uzuuun!' deyin.","Kısa bir şey bulunca (kaşık) iki parmağınızı yaklaştırıp 'kısa' deyin."],"soyle":"«Hadi evdeki en uzun ve en kısa şeyi bulalım!»","isaret":"Doğru-yanlış aramadan uzun ve kısa nesneleri kendiliğinden fark edip gösteriyor."}},{"order":2,"kazanim":"Uzunluğu Fark Eden","gunluk":{"t":"Bunun uzunluğu ne kadar","adim":["Mutfakta/markette bir nesneyi gösterip 'bunun uzunluğu ne kadar?' deyin.","Çocuk iki eliyle 'şu kadar' diye boyu göstersin.","'Evet, işte onun uzunluğu bu kadar' diyerek uzunluğu bir özellik olarak adlandırın."],"soyle":"«Bu kaşığın uzunluğu ne kadar, elinle gösterir misin?»","isaret":"Nesnenin boyunu iki eli arasında açıp 'bu kadar uzun' diyebiliyor."},"oyun":{"t":"Elde taşınan uzunluk","adim":["Bir oyuncağı ortaya koyun; çocuk iki avucunu oyuncağın boyu kadar açsın.","Ellerini hiç bozmadan başka bir yere götürmesini isteyin.","'Bak, hâlâ bu kadar uzun!' diyerek uzunluğun sabit kaldığını fark ettirin."],"soyle":"«Ellerini bozmadan götür; uzunluğu hâlâ aynı mı?»","isaret":"Elleri arasındaki açıklığı koruyup uzunluğun nesneye ait, sabit bir miktar olduğunu görüyor."},"yaprak":{"t":"El uzun, el kısa","adim":["Kâğıda çocuğun elini parmaklar bitişikken bir kez koyup çizin (kısa).","Sonra elini kol gibi açıkken tekrar koyup çizin (uzun).","'Hangisi daha uzun yer kapladı?' diye sorup uzunluğu bir 'miktar' gibi konuşun."],"soyle":"«Hangi el daha uzun bir yer kapladı?»","isaret":"Açık elin izini 'daha uzun' gösterip uzunluğu kaplanan yerle ilişkilendiriyor."}},{"order":3,"kazanim":"Uzunluğu Doğrudan Karşılaştıran","gunluk":{"t":"Uçları aynı çizgiye","adim":["İki kaşığı (ya da iki kalemi) bir uçlarını aynı hizadan başlatarak yan yana koyun.","'Alttan eşitledik, şimdi tepeye bakalım' deyin.","Öteki uca bakıp hangisinin daha uzun olduğunu birlikte söyleyin."],"soyle":"«Önce ayaklarını aynı çizgiye koyalım, sonra tepeye bakalım: hangisi uzun?»","isaret":"Alt uçları hizaladıktan sonra üstten bakarak uzun olanı doğru seçiyor."},"oyun":{"t":"Çubuk düellosu","adim":["Kuru makarna/pipet/çöp şişten ikişer tane çekin.","'Önce ayaklar aynı çizgiye' deyip alt uçlarını masada eşitleyin.","'Uzun olan kazanır!' deyip öteki uca bakarak galibi bulun."],"soyle":"«Ayaklarını eşitlemeden kıyaslamak yok; uzun olan kazanır!»","isaret":"Kıyaslamadan önce alt uçları kendiliğinden aynı çizgiye getiriyor."},"yaprak":{"t":"Hizala da öyle bak","adim":["İki ip/şerit kesip masaya koyun, alt uçlarını tek bir çizgiye dayayın.","Çocuk parmağıyla daha uzun olanı göstersin.","İpleri kaydırıp uçları bozun; 'şimdi de doğru mu?' diye eşitlemenin gerekliliğini fark ettirin."],"soyle":"«Uçlar bozulunca hâlâ doğru görebilir miyiz?»","isaret":"Uçlar bozulduğunda kıyaslamanın yanıltıcı olduğunu görüp yeniden hizalıyor."}},{"order":4,"kazanim":"Uzunluğu Dolaylı Karşılaştıran","gunluk":{"t":"İple taşınan ölçü","adim":["Yan yana getiremediğiniz iki şeyi seçin (kapı boşluğu ile halı).","Bir ipi birine göre uzunluğunu işaretleyip 'bu ip bizim ölçümüz' deyin.","Aynı ipi ötekine götürüp 'uzun mu, kısa mı kaldı?' diye karşılaştırın."],"soyle":"«Taşıyamayınca araya bir yardımcı ip koyuyoruz; bakalım hangisi uzun?»","isaret":"İki nesneyi taşımadan, aradaki ip aracılığıyla hangisinin uzun olduğunu söyleyebiliyor."},"oyun":{"t":"Casus ip","adim":["Bir rafın/masanın boyunu ip ile alıp parmakla işaretleyin.","İpi bozmadan evde dolaşıp 'bununla aynı boyda ne var?' diye arayın.","Bulduğunuz nesneyi iple karşılaştırıp eşit/uzun/kısa diye söyleyin."],"soyle":"«Bu casus ip kadar olan başka ne var, hadi bulalım!»","isaret":"Üçüncü nesneyi (ip) ölçü kabul edip birbirine götüremediği şeyleri kıyaslıyor."},"yaprak":{"t":"Kurdele ölçü olsun","adim":["Bir kurdele kesip çocuğun bir oyuncağının boyuna denkleştirin, ucunu işaretleyin.","Bu kurdeleyle başka oyuncakları ölçtürün.","Her biri için 'kurdeleden uzun mu, kısa mı?' diye ayırsın."],"soyle":"«Oyuncakları taşımadan, kurdelemizle karşılaştıralım.»","isaret":"Nesneyi taşımadan kurdele aracılığıyla uzun/kısa kararını veriyor."}},{"order":5,"kazanim":"Boy Sırasına Dizen (5’e kadar)","gunluk":{"t":"Kaşık merdiveni","adim":["Sofra kurarken 4-5 kaşığı çıkarın.","'En minikten dev kaşığa doğru sırala' deyin.","Her kaşığı bir öncekinin yanına alttan hizalayarak dizmesine yardım edin."],"soyle":"«En minik kaşıktan en uzun kaşığa doğru bir merdiven yapalım.»","isaret":"5 kaşığı alt uçları hizalı, en kısadan en uzuna sırayla diziyor."},"oyun":{"t":"Boy sırası fotoğrafı","adim":["5 farklı uzunlukta pipet/çubuk verin.","'Oyuncaklar en kısadan en uzuna fotoğraf çektiriyor' deyip sıraya dizdirin.","Bitince 'şimdi en uzundan en kısaya da diz' deyin."],"soyle":"«En kısadan en uzuna dizilip fotoğraf çektirelim!»","isaret":"5 çubuğu iki yönde de (kısa→uzun, uzun→kısa) doğru sıralayabiliyor."},"yaprak":{"t":"Şerit merdiveni","adim":["5 farklı uzunlukta kâğıt şerit kesip karışık verin.","Bir zemine alt uçlarını hizalayıp kısa→uzun merdiven yapsın.","Olmazsa 'şimdi en uzunu bul, en başa al' diye adım adım yönlendirin."],"soyle":"«Hepsini aynı çizgiden başlatıp kısadan uzuna dizelim.»","isaret":"5 şeridi tek bir hizadan başlatıp doğru boy sırasına koyuyor."}},{"order":6,"kazanim":"Uç Uca Dizerek Ölçen","gunluk":{"t":"Boşluksuz birimler","adim":["Masanın boyunu ölçmek için aynı boy şeyler toplayın (ataç, kibrit, küp).","Bunları BOŞLUK BIRAKMADAN ve ÜST ÜSTE BİNDİRMEDEN uç uca dizin.","Kaç tane ettiğini birlikte sayın."],"soyle":"«Aralarında boşluk kalmadan dizelim, yoksa yanlış sayarız.»","isaret":"Birimleri bitişik ve hizalı dizip 'masa kaç ataç' diye sayabiliyor."},"oyun":{"t":"Köprü kurma","adim":["Bir oyuncak arabanın gideceği yolu eş boy küp/lego ile uç uca döşeyin.","Parçalar arasında boşluk ya da çakışma olmamasına dikkat edin.","'Köprü kaç parça?' diye sayıp arabayı geçirin."],"soyle":"«Parçalar arasında boşluk kalırsa köprü çöker; bitişik dizelim.»","isaret":"Eş birimleri boşluksuz uç uca dizip köprünün kaç parça olduğunu sayıyor."},"yaprak":{"t":"Kalem kaç ataç","adim":["Bir kalemin boyunu aynı boy fasulye/ataçla uç uca dizerek ölçtürün.","Birimleri düzgün, bitişik ve hizalı koymasına dikkat edin.","Kaç tane olduğunu yazsın/söylesin."],"soyle":"«İşte kalem 6 ataç uzunluğunda; birimleri bitişik dizdik.»","isaret":"Birimleri boşluksuz dizip 'kalem ... ataç uzunluğunda' sonucunu söylüyor."}},{"order":7,"kazanim":"Boy Sırasına Dizen (6 ve üzeri)","gunluk":{"t":"Sıraya yeni giren","adim":["Ayakkabıları ya da kitapları dizerken 6+ nesneyi çıkarın.","En kısadan en uzuna sıralamasını isteyin.","Kalabalıkta 'önce en uzunu bul, sonra kalanların en uzununu' diye birer birer seçtirin."],"soyle":"«Önce en uzunu bulalım, sonra geri kalanların en uzununu.»","isaret":"6 veya daha çok nesneyi tek tek seçerek doğru boy sırasına diziyor."},"oyun":{"t":"Sinema kuyruğu","adim":["6+ çubuğu/kaşığı 'sinemaya boy sırasıyla giriyorlar' deyip sıraya dizdirin.","Sonra araya yeni bir çubuk verin.","'Bu nereye girmeli?' diye doğru yere yerleştirmesini isteyin."],"soyle":"«Yeni gelen çubuk kuyrukta nereye girmeli?»","isaret":"Sıralı diziye yeni elemanı boyuna göre doğru yere ekliyor."},"yaprak":{"t":"Çok şeritli sıra","adim":["7-8 farklı uzunlukta şerit kesip karışık verin.","Hepsini tek bir hizadan başlatıp kısa→uzun dizsin.","Bir şeridi çekip karıştırın, 'doğru yerine geri koy' deyin."],"soyle":"«Bu kadar çok şeridi de aynı çizgiden başlatıp dizebilir misin?»","isaret":"Çok sayıda şeridi sıralayıp çekilen birini doğru yerine geri koyabiliyor."}},{"order":8,"kazanim":"Tek Birimi Tekrarlayarak Ölçen","gunluk":{"t":"Tek birim kaydır","adim":["TEK bir birim seçin (bir ataç ya da çocuğun başparmağı).","Bir nesneyi bu tek birimi kaydırarak ölçün; her seferinde tam bittiği yerden devam edin.","Bıraktığınız yeri parmakla tutup 'bir... iki... üç' diye sayın."],"soyle":"«Aynı tek birimi kaydıra kaydıra, tam bittiği yerden devam edelim.»","isaret":"Tek birimi her adımda tam önceki izden başlatarak kaç birim olduğunu buluyor."},"oyun":{"t":"Tırtıl adımı","adim":["Tek bir lego/silgiyi 'tırtıl' yapın.","Masanın kenarında her seferinde tam önceki izden başlayarak adım adım yürütün.","Adımları sayın; tırtıl boşluk atlar ya da geri kayarsa baştan alın."],"soyle":"«Tırtıl boşluk atlarsa sayım bozulur; tam izden devam!»","isaret":"Tek birimi boşluk/çakışma olmadan ardışık taşıyıp adımları doğru sayıyor."},"yaprak":{"t":"Tek ataçla ölç","adim":["Çocuğa tek bir ataç verin.","Bir defterin boyunu bu tek ataçla, parmağıyla yerini tutarak art arda taşıyıp ölçtürün.","Sonucu söyletin: 'defter kaç ataç?'"],"soyle":"«Aynı tek ataçla tekrar tekrar taşıyarak da ölçebiliriz.»","isaret":"Tek birimi yerini kaybetmeden tekrarlayarak nesnenin uzunluğunu söylüyor."}},{"order":9,"kazanim":"Uzunluk Ölçen","gunluk":{"t":"Sıfırdan başla","adim":["Cetveli çıkarın; ölçülecek şeyin bir ucunu cetvelin SIFIR çizgisine dayayın.","Öteki ucun denk geldiği santimi birlikte okuyun.","'Bir'den başlatırsa nazikçe 'önce sıfırı bulalım' deyin."],"soyle":"«Önce ucu sıfıra dayayalım, sonra öteki uçtaki sayıyı okuyalım.»","isaret":"Nesnenin ucunu sıfıra hizalayıp doğru santim değerini okuyabiliyor."},"oyun":{"t":"Hazine cetveli","adim":["'Tam 10 cm olan bir şey bul', '5 cm'den kısa bir şey getir' gibi görevler verin.","Çocuk nesneyi cetvelle ölçsün; ucu sıfıra dayamayı hatırlatın.","Doğru ölçüp getirdiğinde birlikte sevinin."],"soyle":"«Tam 10 santim olan bir hazine bul; ucunu sıfıra dayamayı unutma!»","isaret":"Görev verilen uzunluğu sıfırdan hizalayıp cetvelle doğru ölçüp buluyor."},"yaprak":{"t":"Ölç ve yaz","adim":["Birkaç kısa nesne seçin (silgi, kalem, kaşık).","Çocuk her birini cetvelle, ucu sıfırda olacak şekilde ölçsün.","Yanına santimini yazsın."],"soyle":"«Her birini sıfırdan ölçüp kaç santim olduğunu yazalım.»","isaret":"Nesneleri sıfır noktasından hizalayıp santim değerlerini doğru yazıyor."}},{"order":10,"kazanim":"Kavramsal Cetvelle Ölçen","gunluk":{"t":"Önce tahmin et","adim":["Cetvel yokken bir nesne gösterip 'sence kaç santim?' diye tahmin ettirin.","Sonra birlikte ölçüp tahminine ne kadar yaklaştığına bakın.","'Bir santim aşağı yukarı şu kadar' diye 1 cm'lik aralığı parmakla gösterin."],"soyle":"«Cetvelsiz tahmin et: bu kalem sence kaç santim?»","isaret":"Zihninde 1 cm'lik aralığı taşıyıp makul bir santim tahmini yapabiliyor."},"oyun":{"t":"Tahmin düellosu","adim":["Bir nesne seçin; ikiniz de kaç cm olduğunu söyleyin.","Sonra cetvelle ölçün.","Tahmini en yakın olan puan alsın."],"soyle":"«İkimiz de tahmin edelim, sonra ölçüp en yakını puan alsın!»","isaret":"Cetvel olmadan gerçeğe yakın santim tahminleri yapıp düelloyu sürdürüyor."},"yaprak":{"t":"Tahminim - ölçtüm","adim":["Bir listeye 4-5 nesne yazın.","Her biri için önce 'tahminim ___ cm' yazsın.","Sonra ölçüp 'ölçtüm ___ cm' yazsın ve ikisini karşılaştırsın."],"soyle":"«Önce tahminini yaz, sonra ölç; ne kadar yakınmışsın bakalım.»","isaret":"Tahmin ve ölçüm sütunlarını dolduruyor ve tahminleri ölçüme yaklaşıyor."}},{"order":11,"kazanim":"Çevre Uzunluğunu Hesaplayan","gunluk":{"t":"Köşeli yolu topla","adim":["Odada/yürüyüşte 'kapıdan pencereye kaç adım?' diye düz olmayan bir yol seçin.","Köşeli yolda 'şuraya kadar, sonra şuradan şuraya' diye parça parça ölçün.","Parçaları toplayıp toplam uzunluğu birlikte bulun."],"soyle":"«Yol düz değil; parça parça ölçüp sonra toplayalım.»","isaret":"Dönüşlü bir yolu parçalara bölüp her parçayı ölçerek toplam uzunluğu buluyor."},"oyun":{"t":"Patika kâşifi","adim":["Yere iple kıvrımlı bir 'patika' kurun.","Çocuk bu yolu ayak boyu/karış ya da iple ölçsün.","Parçaları toplayıp toplam uzunluğu bulsun; istersen bir kutunun dört kenarını toplayıp 'çevresi' fikrini katın."],"soyle":"«Bu kıvrımlı patika baştan sona kaç karış, parçaları toplayalım.»","isaret":"Kıvrımlı yolu parçalarına bölüp ölçerek ve toplayarak toplam uzunluğu buluyor."},"yaprak":{"t":"Oda planı yolu","adim":["Kareli bir kâğıda 'oda planı' çizin.","Kapıdan yatağa kıvrımlı bir yol işaretleyin.","Çocuk yolu parçalara bölüp her parçayı sayıp toplasın; bir dikdörtgenin kenarlarını toplayıp 'çevresi'ni de bulabilir."],"soyle":"«Kıvrımlı yolu parçalara bölüp her parçayı toplayalım.»","isaret":"Düz olmayan yolu parçalayıp uzunlukları toplayarak toplam yolu/çevreyi buluyor."}},{"order":12,"kazanim":"Türetilmiş Birimlerle Ölçen","gunluk":{"t":"Birimi santime çevir","adim":["Standart olmayan bir birimle ölçtüğünüz şeyi seçin (masa 20 ataç çıktı).","'Bir ataç yaklaşık 3 cm' deyip birlikte çarpın: 20 × 3.","'Birim küçülürse sayı büyür' fikrini sesli düşünün."],"soyle":"«Masa 20 ataç; bir ataç 3 cm ise masa kaç santim eder?»","isaret":"Birim sayısını birim boyuyla çarparak standart olmayan ölçüyü santime çeviriyor."},"oyun":{"t":"Büyük adım küçük karış","adim":["Bir mesafeyi önce büyük adımla ölçtürün.","Aynı mesafeyi küçük karışla yeniden ölçtürün.","'Aynı yol neden büyük adımda az, küçük karışta çok çıktı?' diye konuşun."],"soyle":"«Aynı yol neden büyük adımda az, küçük karışta çok çıktı?»","isaret":"Birim küçüldükçe sonucun büyüdüğünü (ters orantı) örnekle açıklayabiliyor."},"yaprak":{"t":"Ataç kaç santim","adim":["Bir nesneyi ataçla ölçtürün (ör. 8 ataç).","'Bir ataç 3 cm ise toplam kaç cm?' diye hesaplatın.","Ataç sayısı sabitken 'birim 2 cm olsaydı kaç çıkardı?' diye karşılaştırsın."],"soyle":"«8 ataç ve her ataç 3 cm ise toplam kaç santim?»","isaret":"Birim sayısı ile birim değerini çarpıp birim değiştiğinde sonucun nasıl değiştiğini açıklıyor."}}]},"marea":{"code":"Y17","name":"Ölçme: Alan","strand":"olcme","levels":[{"order":1,"kazanim":"Alan Duyarlılığı: Temeller","gunluk":{"t":"Hangisi daha geniş?","adim":["Sofra kurarken iki farklı boy tabağı ya da iki peçeteyi masaya yan yana koyun.","Çocuğa 'Hangisi masada daha çok yer kaplıyor?' diye sorun ve birlikte bakın.","Doğru-yanlış aramadan, geniş olanı parmağınızla çevreleyip 'evet, bu daha geniş' deyin."],"soyle":"«Şuna bak, bu tabak masada daha çok yer kaplıyor değil mi?»","isaret":"Çocuk iki yüzeyden hangisinin daha geniş olduğunu gözüyle gösterebiliyor."},"oyun":{"t":"Battaniye kaplama oyunu","adim":["İki farklı büyüklükte battaniyeyi yere serin.","Çocuk sırayla üstlerine uzanıp 'Hangisi beni daha çok kaplıyor?' diye denesin.","Geniş battaniyeyi kollarını iki yana açarak 'bu daha çok yer kaplıyor' diye göstersin."],"soyle":"«Hangi battaniyenin üstünde sana daha çok yer var?»","isaret":"Çocuk daha geniş battaniyeyi seçip 'daha çok yer kaplıyor' diyebiliyor."},"yaprak":{"t":"Geniş mi dar mı?","adim":["İki farklı boy kâğıdı (ya da iki kitap kapağını) masaya koyun.","Çocuk büyük olanı 'daha geniş', küçük olanı 'daha dar' diye ayırsın.","Üst üste koyup hangisinin taştığını birlikte görün; ölçmeye gerek yok, göz kararı yeterli."],"soyle":"«Hangisi daha geniş, hangisi daha dar? Üst üste koyup bakalım.»","isaret":"Çocuk iki kâğıdı 'geniş' ve 'dar' diye doğru ayırabiliyor."}},{"order":2,"kazanim":"Alanı Fark Eden","gunluk":{"t":"Kaplamak için ne kadar gerek?","adim":["Evde iki yüzey gösterin: bir halı ile bir kilim, ya da bir masa ile bir sehpa.","'Bunu örtmek için daha çok mu örtü gerekir, az mı?' diye sorun.","Çocuk 'şu daha geniş çünkü onu örtmek daha çok şey ister' gibi düşünsün; alanı bir 'çokluk' gibi konuşun."],"soyle":"«Bu masayı örtmek mi daha çok örtü ister, şu sehpayı mı?»","isaret":"Çocuk geniş yüzeyin daha çok örtü/kaplama gerektireceğini söyleyebiliyor."},"oyun":{"t":"Kaç havlu tahmini","adim":["Aynı boy birkaç havlu hazırlayın.","'Bu masayı örtmek kaç havlu, şu sehpayı kaç havlu ister?' diye önce tahmin ettirin.","Sonra havluları birlikte yan yana dizip gerçekten kaç tane gittiğini görün."],"soyle":"«Sence bu masa kaç havlu ister? Hadi dizip bakalım.»","isaret":"Çocuk büyük yüzeyin daha çok havlu istediğini tahmin edip deneyle görüyor."},"yaprak":{"t":"Genişten dara sırala","adim":["Üç farklı boy kâğıt hazırlayın.","Çocuk en çok yer kaplayanı başa, en az yer kaplayanı sona koysun.","İkişer ikişer üst üste koyup sıralamanın doğruluğunu birlikte kontrol edin."],"soyle":"«En çok yer kaplayandan en aza doğru dizebilir misin?»","isaret":"Çocuk üç yüzeyi genişten dara doğru sıralayabiliyor."}},{"order":3,"kazanim":"Kaplayıp Sayan","gunluk":{"t":"Tepsiyi döşe ve say","adim":["Bir tepsi ya da kitabın üstünü bisküvilerle veya aynı boy kapaklarla döşeyin.","'Her yerini döşe, sonra kaç tane koyduğunu sayalım' deyin.","Birlikte koyulan parçaları tek tek dokunarak sayın."],"soyle":"«Bu tepsiyi bisküvilerle kapladık, şimdi kaç tane var sayalım.»","isaret":"Çocuk yüzeyi parçalarla kaplayıp koyduğu parçaları sayabiliyor."},"oyun":{"t":"Kapla ve say yarışı","adim":["Eşit boy pul, lego ya da şekerlerle iki kâğıt hazırlayın.","Çocuk bir kâğıdı parçalarla döşesin, siz öteki kâğıdı döşeyin.","Herkes kendi koyduğu parçaları sayıp 'seninkinde kaç, benimkinde kaç?' diye karşılaştırın."],"soyle":"«Sen kâğıdını kapla, ben kendiminkini; sonra kaçar tane koyduk sayalım.»","isaret":"Çocuk yüzeyi kaplayıp parça sayısını söyleyerek karşılaştırma yapıyor."},"yaprak":{"t":"Kaç tane sığdı?","adim":["Bir kapağın ya da küçük kutu dibinin içini aynı boy düğme veya madeni parayla doldurun.","Çocuk içine sığan parçaları tek tek saysın.","'Kapladığım yer şu kadar parça' diye sayıyı söylesin."],"soyle":"«Bu kapağın içine kaç düğme sığdı, sayalım mı?»","isaret":"Çocuk yüzeyi doldurup içine kaç parça sığdığını sayabiliyor."}},{"order":4,"kazanim":"Tam Kaplayıp Sayan","gunluk":{"t":"Boşluksuz döşe","adim":["Masayı ya da bir kitabı eşit kare peçete veya karoyla kaplamaya başlayın.","'Aralarda boşluk kalmasın, parçalar üst üste binmesin, her yer tıkış tıkış dolsun' deyin.","Hiç boşluk kalmadan kaç parça olduğunu birlikte sayın."],"soyle":"«Hiç boşluk kalmasın; her yeri tam dolduralım, sonra sayalım.»","isaret":"Çocuk yüzeyi boşluk ve üst üste binme olmadan kaplayıp sayabiliyor."},"oyun":{"t":"Tam kaplama oyunu","adim":["Eşit boy karton kareler ya da dominolar hazırlayın.","Çocuk bir çerçeveyi (kapak, çerçeveli tepsi) boşluk ve binme olmadan tam kaplasın.","Tek bir aralık kalırsa 'burayı da dolduralım' deyip birlikte tamamlayın."],"soyle":"«Bütün çerçeveyi boşluksuz dolduralım; bak şurada bir aralık kaldı.»","isaret":"Çocuk çerçeveyi hiç boşluk bırakmadan tam olarak kaplayabiliyor."},"yaprak":{"t":"Dikdörtgeni doldur","adim":["Kâğıda bir dikdörtgen çizin.","Çocuk içini eşit kare pullarla taşırmadan ve boşluk bırakmadan döşesin.","Önce 'dolu mu?' diye birlikte bakın, sonra kaç kare sığdığını yazsın."],"soyle":"«Bu dikdörtgenin içini boşluksuz dolduralım, sonra kaç kare olduğunu yaz.»","isaret":"Çocuk dikdörtgeni boşluksuz kaplayıp içindeki kare sayısını yazabiliyor."}},{"order":5,"kazanim":"Alan Birimini Tekrarlayarak Ölçen","gunluk":{"t":"Tek kareyle ölç","adim":["Yere ya da masaya tek bir karo veya kare koyun.","'Aynı kareyi tekrar tekrar yan yana kaydırarak bu yolun kaç kare olduğunu ölç' deyin.","Çocuk hep aynı parçayı taşıyıp 'bir, iki, üç...' diye kaç kare ettiğini bulsun."],"soyle":"«Aynı kareyi kaydıra kaydıra, bu yer kaç kare ediyor bulalım.»","isaret":"Çocuk tek bir birimi tekrarlayarak bir uzunluğu/yüzeyi ölçebiliyor."},"oyun":{"t":"Damga oyunu","adim":["Tek bir kare bisküvi ya da tek bir kapak seçin.","Çocuk aynı parçayı defter veya tepsi üstünde adım adım kaydırsın.","Her yeni yerde kalemle işaretleyip baştan sona kaç kare ettiğini saysın."],"soyle":"«Bu tek kareyi kaydırıp her durağı işaretle; kaç kare oldu sayalım.»","isaret":"Çocuk aynı birimi art arda taşıyarak toplam kare sayısını buluyor."},"yaprak":{"t":"Şablonla doldur","adim":["Aynı boy tek bir kareyi şablon yapın.","Çocuk bir dikdörtgenin içine bu kareyi art arda kaydırarak izini çizsin.","Sonunda kaç kare çıktığını saysın; tek parçayı tekrarlayarak alanı doldurduğunu görsün."],"soyle":"«Bu tek kareyi tekrar tekrar çizerek dikdörtgeni dolduralım.»","isaret":"Çocuk tek bir şablonu tekrarlayarak alanı kareye bölebiliyor."}},{"order":6,"kazanim":"Satırları Birim Olarak Görmeye Başlayan","gunluk":{"t":"Satır ve sıra fark et","adim":["Karelerle döşeli bir yüzeye bakın: banyo karosu, satranç tahtası ya da kareli battaniye.","'Bir satırda kaç kare var, alt alta kaç sıra var?' diye sorun.","Tek tek saymadan 'her sırada aynı sayıda var' fikrini birlikte fark edin."],"soyle":"«Bak, her sırada aynı sayıda kare var; bir satırda kaç tane?»","isaret":"Çocuk yüzeyin eşit satırlardan oluştuğunu fark edip bir satırı sayabiliyor."},"oyun":{"t":"Sıra sıra diz","adim":["Legoları ya da şekerleri düzgün satırlar hâlinde dizin.","'Her satırda 4 tane var, bir satır daha eklersek?' deyin.","Çocuk yeni satır eklerken 'yine 4 tane' diyerek satırların eşit olduğunu sezsin."],"soyle":"«Her satıra 4 koyduk; bir sıra daha eklesek yine kaçar tane olur?»","isaret":"Çocuk her satıra eşit sayıda koyup satırları sayarak ilerleyebiliyor."},"yaprak":{"t":"Satır-sütun boya","adim":["Kareli kâğıtta bir dikdörtgen boyatın.","Çocuk önce bir satırı, sonra bir sütunu renkli kalemle işaretlesin.","'Her satırda kaç, her sütunda kaç' diye yazsın."],"soyle":"«Bir satırı boya, bir sütunu boya; her birinde kaç kare var yaz.»","isaret":"Çocuk dikdörtgende satır ve sütunu ayırt edip sayılarını yazabiliyor."}},{"order":7,"kazanim":"Satır ve Sütunlarla Yapılandıran","gunluk":{"t":"Saymadan kaç göz?","adim":["Yumurta kolisi ya da kareli bir kutu gösterin.","'Burada 3 sıra, her sırada 4 göz var' deyip yapıyı birlikte konuşun.","'Tek tek saymadan, satır ve sütundan kaç göz olduğunu bulabilir misin?' diye sorun."],"soyle":"«3 sıra var, her sırada 4 göz; tek tek saymadan toplamı bulabilir misin?»","isaret":"Çocuk satır sayısı ile sütun sayısını kullanarak toplamı bulmaya çalışıyor."},"oyun":{"t":"Diz ve hesapla","adim":["Şekerleri ya da düğmeleri belli satır-sütun düzeninde dizin (ör. 4 satır, 5 sütun).","Çocuk 'kaç satır, her satırda kaç' diye yazsın.","Tek tek saymadan toplamı satır-sütundan çıkarsın, sonra sayarak doğrulasın."],"soyle":"«4 satır, her satırda 5; önce yapıdan tahmin et, sonra sayıp doğrula.»","isaret":"Çocuk satır-sütun yapısından toplamı çıkarıp sayımla kontrol ediyor."},"yaprak":{"t":"Yapıyı kullan","adim":["Kareli kâğıtta bir dikdörtgen çizin.","Çocuk kenarlarına satır ve sütun sayısını yazsın.","'İçinde toplam kaç kare var?' sorusunu çizip saymak yerine satır-sütunu kullanarak doldursun."],"soyle":"«Kenarlara satır ve sütun sayısını yaz; içini saymadan toplamı bul.»","isaret":"Çocuk satır ve sütun sayısından toplam kareyi tek tek saymadan bulabiliyor."}},{"order":8,"kazanim":"Satır-Sütun Düzenini Kavrayan","gunluk":{"t":"Çarpsak kaç eder?","adim":["Çikolata/kraker dizisine ya da fayanslı bir duvara bakın.","'Kaç satır, kaç sütun?' diye sorun.","'Tek tek saymak yerine çarpsak kaç eder?' deyip satır × sütun ile toplam kareyi bulun."],"soyle":"«Kaç satır kaç sütun? Bunları çarparsak toplam kareyi buluruz.»","isaret":"Çocuk satır sayısı ile sütun sayısını çarparak toplam kareyi bulabiliyor."},"oyun":{"t":"Dikdörtgen kur","adim":["Kare parçalar hazırlayın ve bir sayı söyleyin (ör. 12).","Çocuk bu sayıyı 3×4 ya da 2×6 gibi farklı satır-sütun dizilimleriyle kursun.","'İkisi de 12 kare ediyor' diyerek çarpımı alanla bağlasın."],"soyle":"«12 kareyi kaç farklı dikdörtgenle kurabilirsin? Hepsi 12 mi ediyor?»","isaret":"Çocuk aynı toplamı farklı satır×sütun dizilimleriyle kurabiliyor."},"yaprak":{"t":"Çarpma ile alan","adim":["Kareli kâğıtta birkaç dikdörtgenin satır ve sütun sayısını verin.","Çocuk içindeki toplam kareyi çarpma ile yazsın (ör. 4 satır × 6 sütun = 24).","Önce küçük, sonra biraz daha büyük dikdörtgenlerle ilerleyin."],"soyle":"«4 çarpı 6 kaç eder? İşte dikdörtgenin alanı bu kadar kare.»","isaret":"Çocuk satır × sütun çarpımıyla dikdörtgenin alanını yazabiliyor."}}]},"mvol":{"code":"Y18","name":"Ölçme: Hacim","strand":"olcme","levels":[{"order":1,"kazanim":"Hacim Duyarlılığı: Temeller","gunluk":{"t":"Hangisinde daha çok su?","adim":["Banyoda ya da mutfakta iki kabı farklı doldurun: biri ağzına kadar, biri yarıya kadar.","'Hangisinde daha çok su var sence?' diye sorun.","Ölçmeden, sadece gözle birlikte bakıp sezdirin."],"soyle":"«Bu bardak ağzına kadar dolu, bu yarım; hangisinde daha çok su var?»","isaret":"Çocuk iki kaptan hangisinde daha çok sıvı olduğunu gözle seçebiliyor."},"oyun":{"t":"Şişede saklı su","adim":["İki şeffaf pet şişeyi farklı seviyelerde suyla doldurun.","'Hangisinde daha çok su saklı?' diye çocuk tahmin etsin.","Sonra şişeleri yan yana tutup gözle doğrulayın; sıçratıp gülmek serbest."],"soyle":"«Hangi şişede daha çok su saklı dersin? Yan yana tutup bakalım.»","isaret":"Çocuk daha dolu şişeyi tahmin edip yan yana karşılaştırarak görüyor."},"yaprak":{"t":"En az, en çok kap","adim":["Mutfaktan üç farklı boy kap seçin (fincan, bardak, kâse).","Çocuk 'en az alan' ve 'en çok alan' kabı parmağıyla göstersin.","Her seferinde 'aferin, gözün keskinmiş' diye onaylayın."],"soyle":"«En az su alan hangisi, en çok alan hangisi? Göster bakalım.»","isaret":"Çocuk kapları gözle 'en az' ve 'en çok alan' diye ayırabiliyor."}},{"order":2,"kazanim":"Hacmi Fark Eden","gunluk":{"t":"Azı mı çoğu mu?","adim":["Su ya da süt koyarken miktarı sözcüğe dökün.","'Bardağın azını mı çoğunu mu istersin?' ya da 'yarısı mı, ağzına kadar mı?' diye sorun.","Çocuğun 'az / çok / dolu / boş' demesini günlük sohbete katın."],"soyle":"«Bardağın yarısı mı yetsin, ağzına kadar mı dolduralım?»","isaret":"Çocuk sıvı miktarını 'az/çok/dolu/boş' sözcükleriyle anlatabiliyor."},"oyun":{"t":"Az-çok hazırla","adim":["İki özdeş bardak alın; birine biraz, birine bol su koyun.","'Çok olan hangisi?' diye sorun.","Sonra rolleri değiştirin: bu kez çocuk size az ve çok bardağı hazırlasın. Aynı bardak şart ki miktara baksın."],"soyle":"«Hangi bardakta daha çok var? Şimdi sen bana az ve çok hazırla.»","isaret":"Çocuk aynı boy bardaklarda sıvı miktarını az/çok diye ayarlayıp tanıyor."},"yaprak":{"t":"Boş, yarım, dolu","adim":["Aynı boy üç bardağı boş, yarım ve dolu olacak şekilde hazırlayın.","Çocuk hangisinin 'en az', hangisinin 'en çok' sıvı tuttuğunu söylesin.","Eliyle az-çok sırasına dizsin."],"soyle":"«Bunları en azdan en çoğa doğru dizebilir misin?»","isaret":"Çocuk boş/yarım/dolu bardakları sıvı miktarına göre sıralayabiliyor."}},{"order":3,"kazanim":"Kabı Doldurarak Karşılaştıran","gunluk":{"t":"Kaşıkla doldur","adim":["Çocuğa küçük bir ölçü verin: yemek kaşığı ya da küçük fincan.","'Bu kâseyi bununla dolduralım mı?' deyin.","Birlikte kaşık kaşık boşaltarak kabın içini aynı birimle doldurun."],"soyle":"«Hadi bu kâseyi kaşık kaşık dolduralım; aynı kaşıkla devam et.»","isaret":"Çocuk bir kabı aynı küçük ölçüyle tekrar tekrar doldurabiliyor."},"oyun":{"t":"Kaç kaşık alıyor?","adim":["Bir bardak ve bir tatlı kaşığı verin.","'Bakalım bu bardak kaç kaşık su alıyor?' deyin.","Çocuk kaşıkla doldursun, birlikte sayın; dökülen su oyunun parçası, telaş yok."],"soyle":"«Bu bardak kaç kaşık su alır acaba? Sayarak dolduralım.»","isaret":"Çocuk kabı küçük birimle doldururken kaç birim gittiğini sayıyor."},"yaprak":{"t":"Kavanozu doldur","adim":["Kuru pirinç ya da mercimek ve küçük bir ölçü kabı hazırlayın.","Bir kavanozu birlikte doldurun.","Çocuk kabı her boşalttığında 'bir daha, bir daha' diyerek kavanozun dolmasını izlesin; dolunca alkışlayın."],"soyle":"«Bu kabı her boşalttığımızda kavanoz biraz daha doluyor, gördün mü?»","isaret":"Çocuk bir kabı küçük ölçü kabıyla tekrar tekrar doldurabiliyor."}},{"order":4,"kazanim":"Hacmi Nicelendiren","gunluk":{"t":"Kaç birimde doldu?","adim":["Kaşıkla bardağı doldururken kaç birim gittiğini birlikte sayın.","'Bir kaşık, iki kaşık... işte üç kaşıkta doldu' deyin.","Son sayının kabın kaç kaşık aldığını gösterdiğini fark ettirin."],"soyle":"«Üç kaşıkta doldu; demek bu bardak üç kaşık su alıyor.»","isaret":"Çocuk son sayının kabın toplam birim sayısı olduğunu anlıyor."},"oyun":{"t":"Kaç fincan aldı?","adim":["İki farklı kabı aynı küçük fincanla doldurun ve fincanları sayın.","'Bu kâse 5 fincan, bu bardak 3 fincan aldı' diye söyleyin.","'Hangisi daha çok alıyormuş?' diye sayılarla karşılaştırın; tahmin önce, sayım sonra."],"soyle":"«Kâse 5, bardak 3 fincan aldı; hangisi daha çok su alıyormuş?»","isaret":"Çocuk kapların aldığı birim sayısını karşılaştırıp yorumlayabiliyor."},"yaprak":{"t":"Doluluğu yaz","adim":["Üç kabı (küçük-orta-büyük) aynı ölçü kaşığıyla doldurun.","Kaç kaşık aldıklarını bir kâğıda çizik ya da rakamla not edin.","Çocuk sayılara bakıp 'en çok hangisi alıyor?' sorusunu yanıtlasın."],"soyle":"«Sayılara bakalım: en çok kaç kaşık alan kap hangisi?»","isaret":"Çocuk kapların doluluğunu sayıya döküp en büyüğü seçebiliyor."}},{"order":5,"kazanim":"Hacim Birimini Tekrarlayarak Ölçen","gunluk":{"t":"Aynı bardakla ölç","adim":["Yemek yaparken 'tarif 4 su bardağı su istiyor' deyin.","Çocukla aynı bardağı dört kez doldurup dökün.","Bir birimin tekrarıyla büyük bir miktarı ölçtüğünüzü fark ettirin."],"soyle":"«Hep aynı bardağı kullanıyoruz; dört kez doldurursak tarif tamam.»","isaret":"Çocuk tek bir birimi tekrarlayarak büyük bir sıvı miktarını ölçüyor."},"oyun":{"t":"Bir bardak birim","adim":["Tek bir bardağı 'birim' seçin.","Çocuk bir leğeni bu bardakla doldursun; her seferinde aynı bardağı kullansın.","Kaç kez gittiğini taş/düğme dizerek saysın, sonra 'tam 6 bardak suymuş' desin."],"soyle":"«Aynı bardakla kaç kez doldurduk? Her seferinde bir taş koyalım.»","isaret":"Çocuk aynı birimi tekrarlayıp kaç kez gittiğini sayarak ölçüyor."},"yaprak":{"t":"Şişe kaç bardak?","adim":["Bir şişe suyu özdeş bardaklara paylaştırın.","Çocuk her dolu bardak için bir çizgi çizsin.","Sonunda çizgileri sayıp 'şişe tam 4 bardak' diye aynı birimle ölçtüğünü söylesin."],"soyle":"«Her dolu bardak için bir çizgi çiz; şişe kaç bardak çıktı?»","isaret":"Çocuk bir miktarı eşit birimlere bölüp birimleri sayabiliyor."}},{"order":6,"kazanim":"Sıra ve Sütunları Birim Olarak Görmeye Başlayan","gunluk":{"t":"Kat kat diz","adim":["Kutuya bardak ya da oyuncak yerleştirirken katmanı sezdirin.","Tabana bir sıra dizin, üstüne aynı sıradan bir tane daha koyun.","'Alta bir kat, üstüne bir kat daha; iki kat oldu' diyerek yükselişi gösterin."],"soyle":"«Alta bir sıra dizdik, üstüne bir sıra daha; bak iki kat oldu.»","isaret":"Çocuk nesnelerin kat kat üst üste dizilebildiğini fark ediyor."},"oyun":{"t":"İki kat kur","adim":["Özdeş küp şeker ya da kibrit kutularıyla küçük bir kutunun tabanını tek sıra doldurun.","'Üstüne bir kat daha' diyerek ikinci katı dizin.","Çocuk 'bir kat, iki kat' diyerek katları saysın; yıkıp tekrar dizmek serbest."],"soyle":"«Tabanı doldurduk, şimdi üstüne bir kat daha; kaç kat oldu?»","isaret":"Çocuk bir tabakayı kurup üstüne ikinci katı ekleyerek katları sayıyor."},"yaprak":{"t":"İki katta kaç küp?","adim":["Aynı boy 6-8 oyuncak küple bir ayakkabı kutusunun dibine bir sıra dizdirin.","'Bir kat bu kadar küp aldı' dedirtin.","İkinci katı koyup 'iki katta kaç küp oldu?' sorusunu birlikte sayarak yanıtlayın."],"soyle":"«Bir kat bu kadar küp aldı; iki katta toplam kaç küp olur?»","isaret":"Çocuk bir katın küp sayısından iki katın toplamını bulabiliyor."}},{"order":7,"kazanim":"Katman Katman Yapılandıran","gunluk":{"t":"Satır satır yerleştir","adim":["Çekmeceye kaşıkları '3 kaşık yan yana bir sıra, alta bir sıra daha' diyerek dizdirin.","Her sırada eşit sayıda olduğunu birlikte fark edin.","'Her sırada aynı, kaç sıra yaptık?' diye konuşun."],"soyle":"«Her sırada 3 kaşık var; kaç sıra dizdik bakalım.»","isaret":"Çocuk eşyaları eşit satırlar hâlinde düzenli dizebiliyor."},"oyun":{"t":"Kutu inşa et","adim":["Lego ya da küple '3 uzunluğunda, 2 derinliğinde' bir taban yapın.","Üzerine 2 kat çıkın.","Çocuk 'her sırada 3, 2 sıra, 2 kat' diyerek yapının satır-sütun-katını söyleyerek kursun."],"soyle":"«Her sırada 3, 2 sıra, 2 kat; yapımızı böyle kuralım.»","isaret":"Çocuk satır, sütun ve kat sayısını söyleyerek 3B bir yapı kuruyor."},"yaprak":{"t":"Katları çiz","adim":["Şeker küpleriyle 3x2 tabanlı 2 katlı bir blok yaptırın.","Çocuk bir kâğıda '3'er 3'er' sıraları çizip her katı ayrı göstersin.","Yapının düzenli satır ve sütunlardan oluştuğunu anlatsın."],"soyle":"«Her katı ayrı çiz; her sırada kaç küp var gösterelim.»","isaret":"Çocuk 3B yapının satır-sütun düzenini çizerek gösterebiliyor."}},{"order":8,"kazanim":"Üç Boyutlu Düzeni Kavrayan","gunluk":{"t":"Her katta kaç, kaç kat?","adim":["Düzenli kutu ya da koli dizerken çarpımsal düşündürün.","'Her katta 6 kutu var, 3 kat koyduk, hepsi kaç eder?' diye sorun.","Tek tek saymak yerine '6'şar 3 kez' gibi grupla hesaplamayı birlikte deneyin."],"soyle":"«Her katta 6 kutu, 3 kat; saymadan kaç eder bulabilir misin?»","isaret":"Çocuk kat sayısı ile bir kattaki sayıyı çarparak toplamı buluyor."},"oyun":{"t":"6 çarpı 2","adim":["Özdeş küplerle 2x3 tabanlı 2 katlı bir yapı kurun.","'Bir katta 6, iki katta 6+6' ya da '6 çarpı 2' diyerek toplam küpü bulun.","Sonra söküp tek tek sayarak tahmini doğrulatın."],"soyle":"«Bir katta 6, iki kat var; 6 çarpı 2 kaç eder?»","isaret":"Çocuk bir katın sayısını kat sayısıyla çarpıp toplamı doğrulayabiliyor."},"yaprak":{"t":"Hacmi çarpımla bul","adim":["Yumurta kolisi gibi düzenli bir kabı verin.","'3 sıra, her sırada 4 göz, kaç göz eder?' diye sordurun.","Çocuk '3 kere 4 = 12' diye satır × sütun çarparak kaç birim olduğunu hesaplasın."],"soyle":"«3 sıra, her sırada 4 göz; 3 çarpı 4 kaç eder?»","isaret":"Çocuk satır × sütun çarpımıyla toplam birim sayısını hesaplayabiliyor."}}]},"mang":{"code":"Y19","name":"Ölçme: Açı ve Dönme","strand":"olcme","levels":[{"order":1,"kazanim":"Açı ve Dönme Duyarlılığı: Temeller","gunluk":{"t":"Açılıyor, kapanıyor","adim":["Mutfakta dolap kapağını, bir kitabı ya da makası birlikte yavaşça açıp kapatın.","'Bak, açılıyor... şimdi kapanıyor' deyin.","Çocuğun kendi kolunu dirsekten açıp kapatmasına yardım edip 'kolun da açılıyor!' diye gülümseyin; amaç hareketi hissettirmek, sayı yok."],"soyle":"«Bak kapak açılıyor, şimdi kapanıyor; senin kolun da öyle!»","isaret":"Çocuk bir şeyin açılma-kapanma hareketini fark edip taklit edebiliyor."},"oyun":{"t":"Aç-Kapa oyunu","adim":["Bir oyuncak makas ya da çamaşır mandalı alın.","Siz 'ardına kadar aç' / 'minik aç' deyin, çocuk açıklığı ayarlasın.","Tam kapalı ile sonuna kadar açık olanı abartılı gösterip 'hangisi daha açık?' diye sezgisini yoklayın."],"soyle":"«Şimdi ardına kadar aç... şimdi minik aç; hangisi daha açık?»","isaret":"Çocuk bir açıklığı 'çok' ya da 'az' açacak şekilde ayarlayabiliyor."},"yaprak":{"t":"Çok açık mı, az açık mı?","adim":["Evdeki menteşeli şeyleri bulun: kapı, çekmece, dizüstü ekranı.","Gün içinde birlikte 'çok açık mı, az açık mı?' diye konuşun.","Doğru-yanlış yok; sadece açıklığı fark ettiğiniz için başarı garantili."],"soyle":"«Bu kapı çok mu açık, az mı? Hadi başka açık şey de bulalım.»","isaret":"Çocuk çevredeki açıklıkları 'çok/az açık' diye betimleyebiliyor."}},{"order":2,"kazanim":"Açıyı Oyunda Sezen","gunluk":{"t":"İki kol bir köşe","adim":["Sofrada iki çatalı ya da iki pipeti uçlarından birleştirip bir 'köşe' yapın.","'İki kol bir noktada buluştu' deyin.","Çocuk kolları açıp kapatarak bir kez 'sivri', bir kez 'geniş açık' köşe kursun; köşenin iki kolu olduğunu parmağınızla gösterin."],"soyle":"«İki kol burada buluştu, bir köşe oldu; sivri mi yapalım, geniş mi?»","isaret":"Çocuk iki kolu bir noktada birleştirip köşe oluşturabiliyor."},"oyun":{"t":"Köşe Yap oyunu","adim":["İki pipet/kürdan ya da iki kuru spagetti verin.","Siz 'bana çok geniş bir köşe yap', sonra 'şimdi sivri bir köşe yap' deyin.","Çocuk her seferinde kolların açıklığını değiştirerek farklı köşeler kursun."],"soyle":"«Bana çok geniş bir köşe yap; şimdi de sivri bir köşe yap.»","isaret":"Çocuk istenen genişlikte (sivri/geniş) bir köşe oluşturabiliyor."},"yaprak":{"t":"Köşeleri taklit et","adim":["Bir kâğıda birlikte çatı, dağ ve açık makas çizin.","'Bunların hepsinde iki kol bir köşede buluşuyor' deyin.","Çocuk aynı köşeleri iki pipetle taklit etsin; kolayca başarır çünkü sadece açıp kapatıyor."],"soyle":"«Bu çatının köşesini iki pipetle yapabilir misin?»","isaret":"Çocuk gördüğü köşeleri iki kolla yeniden oluşturabiliyor."}},{"order":3,"kazanim":"Açıyı Farkında Olmadan Kullanan","gunluk":{"t":"Dik köşe yap","adim":["Bloklarla ya da legoyla kare/dikdörtgen bir şey kurun.","'Köşeyi tam dik yaptın', 'bu iki kenar yan yana gidiyor, hiç buluşmuyor' diye yaptığını adlandırın.","Bir parça oturmazsa 'çevir bakalım, hangi köşeyle oturuyor?' deyip döndürtün."],"soyle":"«Bu köşeyi tam dik yaptın; bu iki kenar ise hiç buluşmuyor.»","isaret":"Çocuk yapı kurarken dik köşeleri örtük olarak kullanıyor."},"oyun":{"t":"Döndür ve Otur","adim":["Çerçeveli bir yapboz ya da geçmeli bloklar hazırlayın.","Bir parçayı bilerek ters verin.","Çocuk doğru açıyla oturana kadar parçayı döndürsün; oturunca 'işte tam dik köşeyle yerine geçti' deyin."],"soyle":"«Parçayı döndür bakalım, hangi açıyla tam yerine oturuyor?»","isaret":"Çocuk bir parçayı doğru açıya getirene kadar döndürebiliyor."},"yaprak":{"t":"Dik mi değil mi?","adim":["Bir kitabın ya da fayansın dik köşesini, çocuğun yaptığı köşeyle yan yana koyun.","'Seninki de bunun gibi tam dik mi?' diye karşılaştırın.","Dik olmayan üçgen bir parça da ekleyip onu da döndürerek oturtsun."],"soyle":"«Seninki de kitabın köşesi gibi tam dik mi? Yan yana koyalım.»","isaret":"Çocuk bir köşenin dik olup olmadığını bir örnekle kıyaslayabiliyor."}},{"order":4,"kazanim":"Açı Eşleyen","gunluk":{"t":"Kollar farklı, açı aynı","adim":["İki kuru spagettiden biri kısa biri uzun, ama AYNI açıklıkta iki köşe yapın.","'Sence bu ikisi aynı açıda mı?' diye sorun.","Üst üste bindirip 'tepe noktaları ve birer kol çakıştı, öteki kollar da aynı yöne gidiyor; demek aynı açı, kollar farklı uzunlukta olsa bile' deyin."],"soyle":"«Kollar farklı uzunlukta ama açıklık aynı; bunlar aynı açı mı?»","isaret":"Çocuk kol uzunluğu farklı olsa bile aynı açıklıktaki açıları eşleyebiliyor."},"oyun":{"t":"Aynı mı? eşleme","adim":["İnce kâğıttan açı kopyaları kesin.","Çocuk iki açıyı tepe noktasından üst üste koyup öteki kolların çakışıp çakışmadığına baksın.","Bir açının kollarını kâğıt şeritle uzatıp 'kollar uzadı, açı değişti mi?' (hayır!) diye şaşırtın."],"soyle":"«Tepeden üst üste koy; öteki kollar da çakışıyorsa açılar aynı.»","isaret":"Çocuk iki açıyı üst üste koyarak eşit olup olmadıklarını bulabiliyor."},"yaprak":{"t":"Aynı / farklı ayır","adim":["Çocuğa kolları farklı uzunlukta ama bazıları aynı açıklıkta açı çiftleri verin.","Çocuk 'aynı' ve 'farklı' diye ayırsın.","Takılırsa 'uzun kollu daha büyük değil; önemli olan kolların ne kadar açıldığı' diye hatırlatın."],"soyle":"«Uzun kollu daha büyük değil; bak açıklıkları aynı mı?»","isaret":"Çocuk açı çiftlerini kol uzunluğuna aldanmadan aynı/farklı diye ayırabiliyor."}},{"order":5,"kazanim":"Açı Büyüklüklerini Karşılaştıran","gunluk":{"t":"Hangisi daha geniş açılmış?","adim":["İki kapıyı ya da iki makası farklı açıklıkta tutun.","'Hangisi daha geniş açılmış?' diye sorun.","Çocuk kenara değil açıklığa baksın diye kasten uzun ama az açık bir şeyle, kısa ama çok açık bir şeyi yan yana koyun: 'hangisi daha çok dönmüş?'"],"soyle":"«Hangisi daha geniş açılmış? Uzunluğa değil, ne kadar döndüğüne bak.»","isaret":"Çocuk iki açıdan hangisinin daha geniş olduğunu açıklığa bakarak söylüyor."},"oyun":{"t":"Hangisi Daha Geniş yarışı","adim":["İki kuru spagetti köşesi yapın: biri uzun kollu dar, biri kısa kollu geniş.","Çocuk genişini seçsin.","Kararsızsa ikisini tepeden üst üste bindirip 'hangi kol daha dışarı dönmüş?' diye gösterin."],"soyle":"«Hangisi daha geniş? Üst üste koyalım, hangi kol daha dışarı dönmüş?»","isaret":"Çocuk kol uzunluğundan bağımsız olarak daha geniş açıyı seçebiliyor."},"yaprak":{"t":"Sivriden genişe sırala","adim":["Üç-dört köşeyi en sivriden en genişe doğru sıralatın.","Bir kitabın dik köşesini ölçüt alıp her açı için 'bundan dar mı, geniş mi?' desin.","Uzun kollu dar bir açıyı kasten araya koyup kenara aldanmadan sıralamasını sağlayın."],"soyle":"«En sivriden en genişe sırala; dik köşeyle kıyasla dar mı geniş mi.»","isaret":"Çocuk açıları büyüklüklerine göre doğru sıralayabiliyor."}},{"order":6,"kazanim":"Açı Ölçen","gunluk":{"t":"Çeyrek dönüş ölçü","adim":["Bir kitabın dik köşesini (gönye gibi) alıp 'bu çeyrek dönüş, tam köşe' deyin.","Evdeki bir açıyı (açık dolap kapağı, saatin akrep-yelkovanı) buna kıyaslayın.","'Bundan küçük mü, büyük mü?' diye konuşup derecenin tekrarlanan bir ölçü olduğunu sezdirin."],"soyle":"«Bu kitabın köşesi tam dik; saatin açısı bundan küçük mü büyük mü?»","isaret":"Çocuk bir açıyı dik açı ölçütüyle kıyaslayıp küçük/büyük diyebiliyor."},"oyun":{"t":"Açı Ölç oyunu","adim":["Kâğıttan ya da gerçek bir açıölçer alın.","Merkezini köşenin tam tepesine, sıfır çizgisini bir kola oturtun.","Öteki kolun gösterdiği dereceyi okuyun; kolları uzatıp 'derece değişti mi?' (hayır) diye pekiştirin."],"soyle":"«Merkezi köşeye koy, sıfırı bir kola; öteki kol kaç derece gösteriyor?»","isaret":"Çocuk açıölçeri doğru yerleştirip bir açının derecesini okuyabiliyor."},"yaprak":{"t":"Dereceyle akıl yürüt","adim":["Birkaç hazır açıyı (sivri, dik, geniş) açıölçerle ölçtürün.","Önce dik açıyı bulup '90 derece' çıpasını kurun, sonra 'bu ondan küçük, demek 90'dan az' diye akıl yürütsün.","İleri adım: 'bana 60 derecelik bir açı çiz' deyip açıölçerle kurdurun."],"soyle":"«Dik açı 90 derece; bu ondan küçükse kaç derece olabilir?»","isaret":"Çocuk açıları dereceyle ölçüp 90 dereceye göre yorumlayabiliyor."}}]},"classif":{"code":"Y20","name":"Sınıflama ve Veri Analizi","strand":"veri","levels":[{"order":1,"kazanim":"Benzerlik Sezgisi: Temeller","gunluk":{"t":"Bunlar birbirine benziyor","adim":["Çamaşır katlarken iki çorabı yan yana koyun.","'Bak, bunlar birbirine benziyor, ikisi de yumuşacık ve aynı' deyin.","Çocuktan benzeyen başka bir ikiliyi göstermesini isteyin; kural aramadan sadece 'aynı görünenleri' fark etsin."],"soyle":"«Bunlar birbirine benziyor; sen de benzeyen iki şey gösterir misin?»","isaret":"Çocuk birbirine benzeyen iki nesneyi gösterebiliyor."},"oyun":{"t":"Hangi ikisi benziyor?","adim":["Sofradan iki kaşık, bir çatal alın.","'Hangi ikisi birbirine benziyor?' diye sorun.","Çocuk benzeyen ikiliyi sezgiyle seçsin; doğru-yanlış yok, her seçimi 'evet, bunlar benziyor' diye onaylayın."],"soyle":"«Bunlardan hangi ikisi birbirine benziyor sence?»","isaret":"Çocuk bir grup içinden benzeyen ikiliyi sezgiyle seçebiliyor."},"yaprak":{"t":"Benzeyenleri yan yana","adim":["Bir tabağa 2 elma 1 muz koyun.","Çocuk 'birbirine benzeyenleri' eliyle yan yana itsin.","Tek doğru cevap aramayın; benzerliği fark etmesi yeterli, her denemesini sıcak bir gülümsemeyle karşılayın."],"soyle":"«Birbirine benzeyenleri yan yana koyabilir misin?»","isaret":"Çocuk benzeyen nesneleri yan yana getirerek benzerliği fark ediyor."}},{"order":2,"kazanim":"Benzer/Farklı Grup Oluşturan","gunluk":{"t":"Benzer bir yana, farklı bir yana","adim":["Oyuncakları toplarken 'benzeyenleri bir araya, farklı olanları öbür yana koyalım' deyin.","Arabaları bir köşeye, hayvanları başka köşeye yığın.","Çocuk benzerleri kümelesin, siz sadece eşlik edin."],"soyle":"«Benzeyenleri bir araya, farklı olanları öbür tarafa koyalım.»","isaret":"Çocuk benzer nesneleri bir küme, farklıları ayrı küme yapabiliyor."},"oyun":{"t":"Benzeyenler aynı kutuya","adim":["Çatal-bıçak-kaşıkları masaya karıştırın.","'Birbirine benzeyenler aynı kutuya' oyununu oynayın.","Çocuk benzer olanları bir grupta, farklı olanı ayrı grupta toplasın; her küme tamamlandığında alkışlayın."],"soyle":"«Birbirine benzeyenleri aynı kutuya koyalım; farklı olan nereye?»","isaret":"Çocuk benzer/farklı kümeleri ayrı kaplara doğru toplayabiliyor."},"yaprak":{"t":"İki küme yap","adim":["Bir avuç düğme ya da kapağı masaya dökün.","'Benzer olanları' bir tabağa, 'farklı olanı' boş tabağa ayırsın.","Kural söylemeyin; o benzerliğe göre iki küme kursun, başarısı garanti olsun."],"soyle":"«Benzer olanları bir tabağa, farklı olanı öbür tabağa ayır.»","isaret":"Çocuk nesneleri benzer/farklı diye iki kümeye ayırabiliyor."}},{"order":3,"kazanim":"Basit Gruplayan","gunluk":{"t":"Sadece kırmızıları","adim":["Çamaşırları renge göre ayırırken 'sadece kırmızıları bu sepete' deyin.","Çocuk yalnızca tek bir özelliğe (renk) bakarak ayırsın.","Şekil ya da büyüklüğe karışmasın, tek kurala sadık kalsın."],"soyle":"«Sadece kırmızı olanları bu sepete koy; başka renge bakma.»","isaret":"Çocuk tek bir özelliğe (renk) göre ayırma yapabiliyor."},"oyun":{"t":"Renge göre çorap","adim":["Karışık çorapları yere dökün.","'Sadece renge göre' gruplara ayırın: kırmızılar bir yığın, maviler bir yığın.","Çocuk tek ölçütü (renk) seçip uygulasın; 'hepsi doğru yerde mi?' diye birlikte kontrol edin."],"soyle":"«Çorapları sadece rengine göre ayıralım; kırmızılar, maviler.»","isaret":"Çocuk nesneleri tek bir ölçüte (renk) göre tutarlı gruplayabiliyor."},"yaprak":{"t":"Büyükler / küçükler","adim":["Legoları ya da kapakları 'yalnız büyükler / yalnız küçükler' diye tek özelliğe göre iki kutuya koyun.","Tek ölçüt verin (büyüklük), karıştırmadan ayırsın.","Bitince 'bu kutuda hepsi büyük mü?' diye birlikte bakın."],"soyle":"«Yalnız büyükleri bu kutuya, küçükleri öbürüne koy.»","isaret":"Çocuk tek bir özelliğe (büyüklük) göre iki gruba ayırabiliyor."}},{"order":4,"kazanim":"Benzer Özelliklere Göre Gruplayan","gunluk":{"t":"Kendi kuralınla grupla","adim":["Market dönüşü poşeti boşaltırken 'hadi birbirine benzeyenleri kendin grupla' deyin.","Ölçütü çocuk seçsin (yiyecekler, temizlikçiler, içecekler).","'Neye göre ayırdın?' diye merakla sorun, kendi kuralını anlatsın."],"soyle":"«Bunları kendi seçtiğin bir kurala göre gruplar mısın? Neye göre ayırdın?»","isaret":"Çocuk kendi seçtiği ortak özelliğe göre gruplayıp kuralını anlatabiliyor."},"oyun":{"t":"Neden bir araya?","adim":["Bir kutu karışık eşya verin (kalem, silgi, taş, yaprak).","'Benzer olanları kendi seçtiğin kurala göre topla' deyin.","Çocuk ölçütünü kendi bulup gruplasın; 'bunları neden bir araya koydun?' diye konuşun."],"soyle":"«Benzer olanları kendi kuralınla topla; neden bunları seçtin?»","isaret":"Çocuk benzer özellikleri bulup kendi kurduğu ölçütle gruplayabiliyor."},"yaprak":{"t":"Ortak özelliği seç","adim":["Mutfak dolabından güvenli kapaklar/kaşıklar verin.","Çocuk 'birbirine benzeyenleri' kendi seçtiği ortak özelliğe göre kümelesin.","Ölçütü siz dayatmayın, o belirlesin; her mantıklı gruplamayı takdir edin."],"soyle":"«Birbirine benzeyenleri kendi seçtiğin özelliğe göre kümele.»","isaret":"Çocuk benzer özelliklere göre kendi ölçütüyle kümeler kurabiliyor."}},{"order":5,"kazanim":"Tutarlı ve Esnek Sınıflayan","gunluk":{"t":"Şimdi başka türlü ayır","adim":["Düğmeleri önce renge göre ayırın.","Sonra 'şimdi de büyüklüğe göre yeniden ayıralım' deyin.","Aynı eşyaları farklı bir kurala göre baştan grupladığını fark ettirin: 'aynı düğmeler, ama bu sefer başka türlü ayırdık.'"],"soyle":"«Aynı düğmeleri bu sefer büyüklüğüne göre ayıralım mı?»","isaret":"Çocuk aynı nesneleri ölçüt değiştirerek yeniden sınıflayabiliyor."},"oyun":{"t":"İki tur grupla","adim":["Aynı oyuncak setini iki turda gruplayın: 1. tur renge göre, 2. tur şekle göre.","Çocuk ölçütü değiştirip aynı nesneleri yeniden sınıflasın.","'Başka nasıl ayırabiliriz?' diye yeni ölçütler bulun."],"soyle":"«Önce renge göre ayırdık; şimdi şekle göre ayırabilir misin?»","isaret":"Çocuk aynı seti iki farklı ölçütle esnekçe gruplayabiliyor."},"yaprak":{"t":"Esnek ayır","adim":["Bir avuç karışık kapağı önce renge göre, sonra boyuta göre tekrar ayırması için iki tur planlayın.","Aynı malzemeyi farklı ölçütlerle esnekçe gruplasın.","'İki türlü de ayırabildin!' diye başarısını vurgulayın."],"soyle":"«Aynı kapakları hem renge hem boyuta göre ayırabilir misin?»","isaret":"Çocuk aynı nesneleri farklı ölçütlerle esnek biçimde sınıflayabiliyor."}},{"order":6,"kazanim":"Tek Tek Verileri Okuyan","gunluk":{"t":"Hangisi daha çok?","adim":["Meyve sepetine bakıp 'elmalar mı çok, portakallar mı?' diye sorun.","Çocuk yığınlara bakıp tek bakışta hangisinin daha çok olduğunu okusun.","Sayı saymadan, gruba bakıp durumu yorumlasın."],"soyle":"«Sepette elmalar mı çok, portakallar mı? Bakar bakmaz söyle.»","isaret":"Çocuk iki yığına bakıp hangisinin daha çok olduğunu okuyabiliyor."},"oyun":{"t":"Nereden anladın?","adim":["İki tabağa farklı sayıda kuruyemiş koyun.","'Hangi tabakta daha çok var, nereden anladın?' diye sorun.","Çocuk görsel yığını okuyup yorumlasın; cevabını 'çünkü bu taraf daha kalabalık' gibi anlatsın."],"soyle":"«Hangi tabakta daha çok var? Nereden anladın söyle bakalım.»","isaret":"Çocuk tek bir veri durumunu (hangi yığın çok) okuyup gerekçelendirebiliyor."},"yaprak":{"t":"En çok hangi renk?","adim":["Renkli kalemleri renk renk küçük yığınlar yapın.","'En çok hangi renkten var?' diye tek bir durumu okumasını isteyin.","Karşılaştırıp en kalabalık yığını göstermesi yeterli; doğru okumayı birlikte kutlayın."],"soyle":"«En çok hangi renk kalemden var? En kalabalık yığını göster.»","isaret":"Çocuk yığınları karşılaştırıp en çok olanı okuyabiliyor."}},{"order":7,"kazanim":"Veriyi Sınıflayan","gunluk":{"t":"Ayır, sonra say","adim":["Akşam toplananları 'giysiler, oyuncaklar, kitaplar' diye adlandırılmış kümelere ayırın.","'Her kümede kaç tane var?' diye sayın.","Çocuk veriyi önce sınıfa koysun, sonra her sınıfı saysın."],"soyle":"«Önce türlerine ayıralım, sonra her kümede kaç tane var sayalım.»","isaret":"Çocuk nesneleri sınıflara ayırıp her sınıfı sayabiliyor."},"oyun":{"t":"Topla ve say","adim":["Bir avuç karışık nesneyi (taş, yaprak, çubuk) doğada toplayın.","Eve gelince türlerine göre kaplara ayırın.","Her kabı sayın; çocuk topladığını kategorilere bölüp sayılabilir veri hâline getirsin."],"soyle":"«Topladıklarımızı türlerine ayırıp her birinden kaç tane var sayalım.»","isaret":"Çocuk topladığı şeyleri kategorilere ayırıp her birini sayabiliyor."},"yaprak":{"t":"Sayım tablosu","adim":["Çekmecedeki kapakları renge göre kaplara dağıtın.","'Kırmızıdan 4, maviden 3' diye her kümenin sayısını yan yana yazdırın.","Sınıflara ayırıp her sınıfı sayması yeterli; küçük bir sayım tablosu çıksın."],"soyle":"«Her renkten kaç tane var? Yan yana yazıp küçük bir tablo yapalım.»","isaret":"Çocuk sınıflara ayırıp her sınıfın sayısını yazarak basit veri çıkarabiliyor."}},{"order":8,"kazanim":"Çoklu Özelliğe Göre Sınıflayan","gunluk":{"t":"Hem kırmızı hem küçük","adim":["Çorap çekmecesini düzenlerken 'hem kırmızı hem küçük olanları bul' deyin.","Çocuk aynı anda iki özelliğe (renk + boy) bakarak seçsin.","Tek özellik yetmesin, ikisini birlikte düşünsün."],"soyle":"«Hem kırmızı hem küçük olanları bulabilir misin? İkisine birden bak.»","isaret":"Çocuk iki özelliği aynı anda sağlayan nesneleri seçebiliyor."},"oyun":{"t":"Hem büyük hem mavi","adim":["Legolarla 'hem büyük hem mavi olanları bu kutuya' oyununu oynayın.","İki koşulu aynı anda sağlayan parçaları ayırsın.","'Büyük ama mavi değil' olanları neden almadığını birlikte konuşun."],"soyle":"«Hem büyük hem mavi olanları al; büyük ama yeşil olanı neden almadın?»","isaret":"Çocuk iki koşulu birden sağlayanları ayırıp tek koşullu olanları dışarıda bırakabiliyor."},"yaprak":{"t":"İki ölçütü kesiştir","adim":["Kapakları/düğmeleri 'hem yuvarlak hem büyük' gibi iki ölçütü birden sağlayanlar olacak şekilde ayırması için kart hazırlayın.","İki özelliği kesiştirip seçsin.","Doğru ikili-eşleşmeyi takdir edin."],"soyle":"«Hem yuvarlak hem büyük olanları seç; ikisi birden olmalı.»","isaret":"Çocuk iki özelliğin kesişimindeki nesneleri seçebiliyor."}},{"order":9,"kazanim":"Veriye Bütün Olarak Bakan","gunluk":{"t":"Hafta boyu çetele","adim":["Markette ya da evde 'bir hafta hangi meyveyi kaç kez yedik?' diye birlikte çetele tutun.","Her gün buzdolabına bir çizgi ekleyin.","Çocuk günlerce veri biriktirip hafta sonunda 'en çok hangisi' diye özetlesin."],"soyle":"«Bu hafta her meyve için bir çizgi atalım; hafta sonu en çoğu hangisi?»","isaret":"Çocuk günden güne çetele tutup hafta sonunda toplamı özetleyebiliyor."},"oyun":{"t":"Hava durumu defteri","adim":["Her gün güneşli/yağmurlu/bulutlu için bir çetele çizgisi atın.","Hafta boyunca veri toplayın.","Sonunda 'en çok hangi hava oldu?' diye birlikte özet çıkarın."],"soyle":"«Bugün hava nasıl? O kutuya bir çizgi atalım; hafta sonu sayarız.»","isaret":"Çocuk birkaç gün boyunca veri toplayıp en sık durumu özetleyebiliyor."},"yaprak":{"t":"Günlük tek bilgi","adim":["Bir hafta boyunca her akşam 'bugün kaç kitap okuduk' gibi tek bir bilgiyi küçük bir kâğıda çetele ile işaretletin.","Veriyi günden güne biriktirin.","Hafta sonunda toplamı söylesin; süreklilik başarısı garantili."],"soyle":"«Bugün kaç kitap okuduk? Çeteleyle işaretleyip biriktirelim.»","isaret":"Çocuk tek bir bilgiyi günlerce biriktirip toplamını çıkarabiliyor."}},{"order":10,"kazanim":"Hiyerarşik Sınıflayan","gunluk":{"t":"Grup içinde grup","adim":["Oyuncakları toplarken 'bunların hepsi hayvan; içlerinden köpekler ayrı, kediler ayrı olsun' deyin.","Büyük bir grubun içinde alt grupları görmesini sağlayın.","'Köpekler de hayvan ama hepsi köpek değil' diye iç içe ilişkiyi fark ettirin."],"soyle":"«Bunların hepsi hayvan; köpekleri ayrı, kedileri ayrı kümeleyelim.»","isaret":"Çocuk büyük bir grubun içinde alt gruplar (köpekler/kediler) oluşturabiliyor."},"oyun":{"t":"Dallara ayır","adim":["Düğmeleri önce 'yuvarlaklar' büyük grubuna koyun.","Sonra yuvarlakları kendi içinde 'büyük yuvarlaklar / küçük yuvarlaklar' diye bölün.","Çocuk grup-içinde-grup (iç içe küme) kursun; ağaç gibi dallandığını gösterin."],"soyle":"«Önce yuvarlakları topla; şimdi onları büyük ve küçük diye böl.»","isaret":"Çocuk bir grubu alt gruplara bölerek iç içe (hiyerarşik) küme kurabiliyor."},"yaprak":{"t":"Halka içinde halka","adim":["Bir kâğıda büyük bir halka çizip 'meyveler' yazın.","İçine iki küçük halka çizip 'kırmızılar / sarılar' diye ayırttırın.","Üst kümeyle alt kümeleri iç içe yerleştirsin; hiyerarşiyi görsel olarak yakalasın."],"soyle":"«Büyük halka meyveler; içine kırmızılar ve sarılar için iki halka çizelim.»","isaret":"Çocuk üst küme ile alt kümeleri iç içe halkalarla gösterebiliyor."}},{"order":11,"kazanim":"Veriyi Temsil Eden","gunluk":{"t":"Sütunlarla resmet","adim":["Akşam yemeğinde 'bu hafta en sevdiğin meyveyi soralım' deyip aile bireylerinin oyu için her birine bir kare boyatın.","Kareler yükseldikçe 'en uzun sütun kazandı' deyin.","Çocuk veriyi sütunlarla resme döksün."],"soyle":"«Herkesin oyu için bir kare boyayalım; en uzun sütun hangisi olacak?»","isaret":"Çocuk topladığı oyları üst üste karelerle sütuna dönüştürebiliyor."},"oyun":{"t":"Sticker grafiği","adim":["Kâğıda alt alta meyve isimleri yazın.","Her 'oy' için yanına bir sticker/kare yapıştırın.","En uzun sıra hangisiyse onu bulun; çocuk gerçek veriyi basit bir grafiğe çevirip 'en uzun hangisi?' diye okusun."],"soyle":"«Her oy için bir sticker yapıştır; en uzun sıra hangisi oldu?»","isaret":"Çocuk veriyi sticker'larla grafiğe çevirip en uzun sırayı okuyabiliyor."},"yaprak":{"t":"Sütun grafiği çiz","adim":["Hafta boyunca topladığınız hava/meyve çetelelerini alın.","Kareli kâğıtta her gün/seçenek için bir kutu boyayarak sütun grafiğine dönüştürün.","Veriyi grafikle temsil etsin; siz sadece 'en yüksek sütun neyi anlatıyor?' diye sorun, çizimi ona bırakın."],"soyle":"«Çetelelerimizi sütun grafiğine çevirelim; en yüksek sütun neyi anlatıyor?»","isaret":"Çocuk topladığı veriyi sütun grafiğiyle temsil edip okuyabiliyor."}}]}}};
